/* 令和8年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r08.committeeSessions.push(...[{"id":"r08-20260511-5","meetingId":"r08-m0405","date":"2026年5月11日","dateIso":"2026-05-11","committee":"総務委員会","time":"午後１時00分～午後２時36分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"多言語通訳の三者間通話サービス等の導入","agenda":"多言語通訳の三者間通話サービス等の導入","exchanges":[{"speaker":"西本委員","kind":"確認","question":"確認をしたいと思います。そういったときには、やはり携帯等々で、 スマホ等々からの問合せという形になるのか、そこをもう少し説明を求めました。","respondent":"與那嶺デジタル推進課長","answer":"こちらのサービス自体は、既存でやっている窓口でのビデオ通話サービスで対応しているオペレーターの方が、電話でも対応しますという形ですので。なので、これまで実際に行政との通訳のやり取りをずっと続けている方が対応しますので。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"これは要望になるのですけれども、そういう形でできると思うのですけれども、その操作自体が伝わるかどうかということが少し心配なのです。これは大丈夫ですよねという確認だけ。","respondent":"與那嶺デジタル推進課長","answer":"区に転入してきたときに、転入手続と一緒に実際にこういうサービスもやっていますので、ぜひご利用くださいというチラシも作成する予定です。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"最後に、電話がつながらないというケースはどのぐらい増えているのでしょうか。大体どのぐらいを想定しているのか、そのボリューム的なところを説明するよう求めました。","respondent":"與那嶺デジタル推進課長","answer":"こちらのサービスですけれども、窓口でのビデオ通話と電話での通話を合わせた形で、年間５００時間ほどの運用時間という想定で契約をしております。まだ２割程度の時間の余裕があるというところでありますので、一旦は、そこの中で見ていこうかなという形で考えている次第です。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"ただ、どうしてもそこに、今度、通訳者のスキルとか、専門用語とか、あと、プライバシーの問題も出てくると思うのです。通訳者が全部その内容を一緒に聞いているわけですから、専門的な内容になると、きちんとそれに応えられるような対応ができるようになるのか尋ねました。","respondent":"與那嶺デジタル推進課長","answer":"行政窓口手続での通訳サービスに関しては、品川区でも比較的長い歴史を持っておりまして、今、大体９年目になっております。その中で、先ほどご指摘のありましたプライバシーの問題であるとか、その中で新たなサービスについてもしっかりやっていきたいと考えてあります。","id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"やはり言語、言葉の技術的な対応も大事だと思うので、その辺をしっかり今まで積み上げてきたノウハウを活かしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"品川区のほうで配信されていると思うのですけれども、在住外国人の方はどれくらい登録されているのかということをお伺いしたいのですけれども。少し違いますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"澤田委員","kind":"質問","question":"どれくらい把握されているか分からないのですけれども、これも活用されるのかなというところでご予定されているのでしょうか。例えば、今回の多言語の電話のサービスをやりますとかということは、 こちらも活用されるご予定なのか尋ねました。","respondent":"與那嶺デジタル推進課長","answer":"こちらも情報発信の１つですので、住んでいる多くの方に知っていただくことが非常に大事だと思っていますので、ＰＲにつなげていきたいと考えています。","id":"exchange-007"},{"speaker":"澤田委員","kind":"意見","question":"すみません、数を聞いてしまって申し訳なかったのですけれども、そうしましたら、こちらを使っていただけるということでよかったなということと、すごくいいので、このＬＩＮＥに登録してくださる在住外国人の人が増えるといいなと思っていますので、今後ともどうぞとの意見を述べました。","respondent":"中西総務課長","answer":"在住外国人のＬＩＮＥの登録者数です。令和７年度で、英語版が８９５名の方が登録されている状況です。","id":"exchange-008"},{"speaker":"澤田委員","kind":"質問","question":"割合としては何割ぐらいというか、全体としてどれぐらいなのか尋ねました。","respondent":"中西総務課長","answer":"割合は、すみません、今、正式な在住外国人の人数については、手元に資料がございませんが、１万 ８,０００人程度の方がいますので、そういった意味では、その中での約９００名という形になりますので、その程度の割合になります。","id":"exchange-009"},{"speaker":"澤田委員","kind":"質問・要望","question":"とてもいいシステムだと思うので、たくさんの方に登録していただけるようにしていただけたらいいなと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"山本委員","kind":"確認","question":"私からも質問します。１３言語の方々はということだと思うのですけれども、そういう理解で間違いないのか、確認したいと求めました。","respondent":"與那嶺デジタル推進課長","answer":"委員ご認識のとおりでこざいます。最初の説明でも少し触れたのですけれども、７３か所配置をしているのですけれども、このサービスを使うというイメージでおります。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問","question":"よく「窓口に行っても、そういう案内をできるかどうかというところ、窓口担当の職員の皆さんが案内できるかというところが１つあるかなと思うのです。その辺りの区の職員の皆様への周知の状況、取組があれば説明を求めました。","respondent":"與那嶺デジタル推進課長","answer":"まず、これは通訳に関わらずなのですけれども、質問に対して分かりやすい説明をするというところがまず前提にあろうかと考えています。庁内に、まさに今やっている最中なのですけれども、周知を行っている感じです。","id":"exchange-012"},{"speaker":"山本委員","kind":"意見","question":"照会を受ける皆さんが、そのサービスを適切に案内できるように、職員の皆様にしっかりとご理解いただけるように進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"さらに通訳者を広げていくとか、そういうところは今のところはないのでしょうか。予測は、どう考えていらっしゃるのか説明を求めました。","respondent":"與那嶺デジタル推進課長","answer":"ただ、今まで使ってきた中で、極端にこれがつながりにくくなったということは実績としてはないというところがまず前提です。そういったところがあろうかと思いますので、まず運用を進めながら、そこの実績を見ながら検討していきたいと考えています。","id":"exchange-014"}]},{"id":"topic-02","title":"連携自治体との新たな取組み","agenda":"連携自治体との新たな取組み","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"どこから来ているアクセスというか、参加申込みが来ているのかという、それはいかがですか。そこをお尋ねします。","respondent":"野口官民共創担当課長","answer":"いろいろな多世代の方が参加いただけるような今までとは違うような申込みというＰＲをさせていただいたところであります。五反田バレー の加入企業へのＰＲをさせていただいたりというところで多角的に実施していますので、改めてその辺は検証していきたいと考えています。","id":"exchange-015"},{"speaker":"西本委員","kind":"提案","question":"連携自治体が提案するワーケー ションプログラムということなので、これからですか、こういうものをやりますと参加自治体からの提案があって。どういう形式になるのか尋ねました。","respondent":"野口官民共創担当課長","answer":"２点ほど、ご質問いただいたかと考えています。６月で意思を合わせる部分を設けているというものになりますので、そこをすり合わせていって、これから少しずつ増やして検討していきたいです。","id":"exchange-016"},{"speaker":"西本委員","kind":"提案","question":"企業で、 それだったら、こういうことを提案できるのだけれどもとかという、それから内容を詰めていくという感覚でよろしいでしょうか。その確認だけとの意見を述べました。","respondent":"野口官民共創担当課長","answer":"おっしゃるとおり、そこはこれから具体的な内容を詰めていくという部分になります。自治体でつくってもらったものなので、品川区でつくったものではなくて、あくまで自治体側から出してもらっていることになります。","id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"それがＷｉｎ－Ｗｉｎという形にならないと、両者にメリットがないと、なかなか難しいと思うのです。それがリンクしているのかどうかということをぜひ、そうならないように、ぜひ満足度の調査をよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"今回、参加事業者は、販路拡大や就業者の健康増進に取り組んでいくということなのですか。就業者の健康増進もそうなのですけれども、それに加えて、こういう事業をこれから推進していくということなのか尋ねました。","respondent":"野口官民共創担当課長","answer":"あくまでも総務課が今回これを実施するというところで、今回、事業を構築しております。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"２３区は特にそうですけれども、これだけ多くの人を抱えているような自治体が多数あるわけですから、これとは少し意味合いが違うのでしょうか。それだけ説明を求めました。","respondent":"野口官民共創担当課長","answer":"距離が離れた自治体と連携することで、平時からの連携をするという、いかにどうスムーズに有事の対応をするかという部分ももちろんあるかと思います。連携させていただいている自治体の中には、今回、この事業を拡大するというものになります。","id":"exchange-020"},{"speaker":"須貝委員","kind":"意見","question":"今、意味合いはよく分かりました。品川区としても、何かあったときにお互いに助け合えるような、そういう連携事業につながるような仕組みを構築してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"塚本副委員長","kind":"確認","question":"業務というふうに位置づけられるものかどうかが、特段の企業側にとっての意味があったりするのかどうかということを確認したいというか、どうか尋ねました。","respondent":"野口官民共創担当課長","answer":"もう１点が、品川区として、今回、自治体連携をやっている意味合いというところです。各都市から連携することによって、自治体連携という事業を新たに予算要求させていただいて、認めていただいたという部分になるかと思います。","id":"exchange-022"},{"speaker":"塚本副委員長","kind":"意見","question":"やはりワーケーションとは何なんだろうというのがどうしても腑に落ちなくて、そういう延長にある話として、それはすごく分かるのです。ウエルカムで来てほしいとなると思いますけれども、企業側からも、そういうところはどういうふうに見ていますかとの意見を述べました。","respondent":"野口官民共創担当課長","answer":"今、やはりバケーションという位置づけも１つ考えられるとは思います。この６月での打合せは重要視しておりまして、この６月の部分でいろいろお話をさせていただいて、品川区の思いを強く伝えていきたいと考えています。","id":"exchange-023"},{"speaker":"塚本副委員長","kind":"意見","question":"では、ぜひよろしくお願いします。飯田市が２００万円と出ていまして、一応、参加される方は負担していただくお金がありますよねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"塚本副委員長","kind":"質問","question":"３人コースが２万円、この２００万円というのは、どの辺にかかるお金なのか。飯田市のお話になるので、そういう意味では、補正とかで拡充できる可能性があるのかどうかというところを視野に入れた答弁をお願いします。","respondent":"野口官民共創担当課長","answer":"２００万円のお金に関しては、あとは、１泊２日の飯田市体験ツアーの費用等に充てているというふうには聞いております。これから検討していきたいというところで聞いていまして、いろいろお話をさせていただいて、今後のというところは考えていきたいと考えています。","id":"exchange-025"},{"speaker":"山本委員","kind":"提案","question":"ほかの委員からも質問がございましたけれども、どれぐらいの申込みがあるのか、もし分かれば教えていただきたいです。相手側から、連携自治体からの提案とかをうまくもらってやったのかという、ツアーの出来上がり方みたいなところを少し教えてほしいと求めました。","respondent":"野口官民共創担当課長","answer":"我々もいろいろな自治体と連携している中で、魅力というようなところを考えて、ツアーができたというものになります。ユニクロのＴＯＣ店と小田原市と品川区で木育の連携をさせていただいたりとか、今回、小田原市ともツアーができたというふうになってあります。","id":"exchange-026"},{"speaker":"山本委員","kind":"提案","question":"小田原市などは、何かそういう連携都市、連携自治体の方々の提案や予算などをうまく活用させていただきながら。先方、同種の取組をほかの自治体とも参考にしていただきたいですし、飯田市ともこういった連携をさらに広げてほしいというふうに思っておりますとの意見を述べました。","respondent":"野口官民共創担当課長","answer":"おっしゃられるような地図にプロットして、ここの自治体はどこというようなことだと、私は今、理解しました。マンパワーという部分もありますので、できるところから実施していきたいと思いますので、引き続きよろしくお願いいたします。","id":"exchange-027"},{"speaker":"澤田委員","kind":"意見","question":"今いろいろなことを聞いてきた中で１つ思ったのが、お考えはあるのかな、来ていただくという方向もあるのかということをお聞かせほしいと求めました。","respondent":"野口官民共創担当課長","answer":"そうですね、今後については、体験交流ツアー等を使って、各自治体間の住民同士が交流をしていくと。その上で、今後のステップとして、今おっしゃられたところも、委員からいただきましたので、今後、検討していきたいと考えています。","id":"exchange-028"}]},{"id":"topic-03","title":"区ホームページ全面リニューアル","agenda":"区ホームページ全面リニューアル","exchanges":[{"speaker":"西本委員","kind":"質問","question":"担当のところ、戦略広報課なのだろうなと思うのですけれども、それがどういう形に変わろうとしているのかということが１つ。とても不便さを感じているので、そこの情報の伝達の仕方を分かりやすくなるのかどうか、そこのイメージを説明するよう求めました。","respondent":"田口戦略広報課長","answer":"ただいまの委員からの質問、２点、お答えいたします。２点目の最新情報を探しやすくですとか、ホームページのトップページからもそういう情報にアクセスしやすくするようにと考えているところです。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"新着情報と、アクセスの多いものをまとめていくというのは １つの方法ではあるのですが、やはりざっと一覧に出しておくことも必要だと思います。もっと住民の方々がどういうアクセスの仕方をしているのかということを、だからこういうふうにするのですよということがあれば、説明を求めました。","respondent":"田口戦略広報課長","answer":"職員の研修も９月に実施を予定しておりますので、リニューアルに合わせまして、しっかりと活用していくというところで進めてまいります。品川区より先んじて既にリニューアルを実施している自治体などもありますので、現在、考えているところです。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"何かをやるとしたときに、アップの仕方が簡単になるということですから、意識を高めるというところも含めてお願いしたいと思います。それを教えてほしいということと、業務委託で、約４,０００万円ですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"それはもう決まっているのですか。これは入札とかではなくて随意契約とか、そういう形になって決められているのか、それだけ説明を求めました。","respondent":"田口戦略広報課長","answer":"１つ目の自分たちのやっていることをしっかりと宣伝していくというところについては、研修などでも引き続き進めてまいります。もう１点、昨年度にプロポーザルを実施しまして、現在のフューチャーイン株式会社という会社に決まっているという状況です。","id":"exchange-032"},{"speaker":"須貝委員","kind":"質問・要望","question":"これ、どうやって開いて中までのぞけるのかなということが分からないという方も出てくると思うので、その辺を対応していってほしいと思います。ＡＩも使って導入していくわけですから、何とか皆さんに分かりやすいようなホームページをリニューアルするように工夫してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"山本委員","kind":"質問・要望","question":"区ホームページのリニューアルのところは、これまでも要望してきたところでして、このように進んでいるということで、うれしく思っております。それは９月の職員研修でやられるということだったのですけれども、その研修の内容と、どのように進めるのかというところで確認したいと求めました。","respondent":"田口戦略広報課長","answer":"１点目ですが、そこの部分については、改めて浸透させていくというようなところになっております。職員研修などでも実施いたしますし、いろいろな通知文でも使える考え方ですので、そのようなところを浸透していきたいと考えております。","id":"exchange-034"},{"speaker":"山本委員","kind":"質問・要望","question":"そのようにしてほしいと求めましたし、しっかりと検索で新しいものが引っかかるように進めていただきたいということで要望いたします。ＵＸライティングのところ、アクセス件数が多いものから順番にということで、１００件というところで、まずは進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.05.11so.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":26,"characters":32983,"voices":82}},{"id":"r08-20260512-21","meetingId":"r08-m0405","date":"2026年5月12日","dateIso":"2026-05-12","committee":"子ども若者支援・共生社会推進特別委員会","time":"午後１時00分～午後１時04分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.05.12kw.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":5,"characters":1786,"voices":12}},{"id":"r08-20260512-20","meetingId":"r08-m0405","date":"2026年5月12日","dateIso":"2026-05-12","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午後１時00分～午後１時06分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"ここで、もう文言も含めて入れていただければありがたい。⑸のとおりなのですが、中立性の確保を図るとともにの後に、議会への説明を尽くすなど当該事業化プロセスの透明性の担保に万全を期すことの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"意見","question":"前回指摘したとおり、議会への説明が全くない中で事業化されてしまっているということ。中立性の確保は非常に大事なのですけれども、もっと分かりやすくするために、その文言を入れていただければありがたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.05.12sd.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":5,"characters":2331,"voices":16}},{"id":"r08-20260513-22","meetingId":"r08-m0405","date":"2026年5月13日","dateIso":"2026-05-13","committee":"まちづくり・公共交通推進特別委員会","time":"午後１時00分～午後１時07分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"石田（秀）副委員長","kind":"意見","question":"議会でも、こういう場でもう一度しっかり行っていければと考えていますので、どうぞこれからもよろしくお願いします。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.05.13ma.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":5,"characters":2274,"voices":9}},{"id":"r08-20260514-10","meetingId":"r08-m0405","date":"2026年5月14日","dateIso":"2026-05-14","committee":"議会運営委員会","time":"午後１時00分～午後１時46分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"会派変更届","agenda":"会派変更届","exchanges":[{"speaker":"せお委員","kind":"質問・要望","question":"未来にお聞きしたいのが、会派変更する前も本会議等で議案などの態度が会派内で違うことがあったと思います。やはり一番は、私たちは会派の動きという常識の中でやってきたところで、今後もそういう常識は持っていて構わないのか確認させていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"松永委員","kind":"意見","question":"情報共有させていただきながら、円滑な議会運営について、幹事長として努めていきたいと考えていますので。〔「まだ幹事長ではない」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"松永委員","kind":"意見","question":"すみません。これから頑張っていきたいと思っていますので、どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"確認","question":"伺いたいのですけれども、まず、未来は会派とはどういうものだとお考えですかというところを確認しておきたいのです。会派とは、一言でどういうものかをお伺いしたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区議会のホームページには載っていて、ご覧になったかもしれませんけれども、会派とはどのようなものですかという区民向けのＱ＆Ａもあるのです。今年度に入って４年目ですか、今まで数えると４０件以上、意見が一致していない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"私からも質問させていただきたいのですけれども、議案への態度が会派内で変わったりを認めるというのが未来の会派としての方針なのかどうか、そこを確認させてもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"松永委員","kind":"意見","question":"それは一人一人、個人個人の意見があるのは当たり前だと思っていまして、それを一つにするために、話合いの中で今後も決めていく。では、何を終着点にするかは、議論を深めながら必ず一つに絞っていくですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりよく話し合って、そして結論を出したらその結論で動くのが基本的な在り方なのかなと、意見だけ述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"確認","question":"第一会派を名のって、与党でやっていこうというお話は何度も聞いたけれども、確認のためにお伺いしたい。それをどう考えていらっしゃるのかを一つだけお聞きしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"それがきちんと、そうではないですよと、会派なのだから。これから新幹事長になられる方としては、やっていくつもりですと言うのは、やれないということも含めて言っているという理解でいいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"意見","question":"現実問題それが違ったらどうしますかみたいになってしまうわけで、何をしていくかは、それはいつまでたったって第一会派と認められないよと。現時点では我々はそう思うとだけは伝えておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]},{"id":"topic-02","title":"常任・議運・特別委員会の構成","agenda":"常任・議運・特別委員会の構成","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"申合せ確認事項の、今回の案も出されていると思うのですけれども、そうなのか確認をさせてほしいと求めました。皆さん、あるいは正副のご意見なども伺えればと思います。","respondent":"まつざわ委員長","answer":"比例配分につきましては、そのとおり比例配分でやらせていただいております。今ここで私が答えるというよりも、そういったことも含めて、ご意見として頂戴しながらも議論は深めていけばいいのかなと思っています。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"どこかで現行のルールを、変更の是非も含めて、議論していきたいとの話だったのですけれども、ぜひそういうのを議題にしていただきたいというか、議論のテーブルには乗せていただきたいと思うのですけれども、今後どのような場所で議論されていくのか、委員長にご意見を伺えればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"子ども若者共生が１名入っていたのが、あるいは共産党が改めて子ども若者共生特別委員会にも委員を配置したいという要望については、どのようにお考えか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"確認","question":"一応、念のために確認させてください。各会派から話を聞いて、その上でこの配分になっているとのことでしたけれども、これは本当にそういうことでいいのかどうか確認したいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"まつざわ委員長","kind":"確認","question":"そのお話もさせていただきました。未来に確認しましたところ、それを信じて、今回このような案としてご提出させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりより民主的で合意できる配分のやり方を求めるべきだと思っていまして、これはやはり比例配分を基本にして考えることかなと思っています。そのように、選挙ではなく変えたほうがいいのではないかと思うのですけれども、正副委員長、あるいは皆さんのご意見などもお伺いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"これからも基本的にはそういう考えもベースにしながら、現行のやり方で決めていくと捉えたのですけれども、そういった理解で間違いないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問・要望","question":"このたび、議会運営委員会の委員長に当たりまして、議会運営等いろいろと検討させていただいた結果、このたび辞退をさせていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.05.14gu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":17,"characters":14029,"voices":99}},{"id":"r08-20260521-10","meetingId":"r08-m0405","date":"2026年5月21日","dateIso":"2026-05-21","committee":"議会運営委員会","time":"午後１時00分～午後１時02分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.05.21gu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":5,"characters":1415,"voices":15}},{"id":"r08-20260526-10","meetingId":"r08-1r","date":"2026年5月26日","dateIso":"2026-05-26","committee":"議会運営委員会","time":"午前10時30分～午前10時54分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件整理しています。","topics":[{"id":"topic-01","title":"議事日程（１）、追加議事日程および追加議事日程（２）","agenda":"議事日程（１）、追加議事日程および追加議事日程（２）","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"第５７号議案、専決処分の承認を求めることについて、総務委員会は時間短縮のためにもすぐやるということですよね。ここで一応、言っておいてもらったほうがありがたい。","respondent":"大澤区議会事務局長","answer":"休憩後、すぐに総務委員会を開きまして、ほかの常任委員会の予算の審査が終わった後に、もう一回総務委員会です。そういう順番でよろしくお願いいたします。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"選任同意は１名だけで、第１会派になったしながわ未来からは選任されず、第２会派となった自民党はそのまま残りました。議会改革推進会議の場で議論して、あらかじめみんなで決めて定める必要があると思いますので、この場で議論します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"議員研修会","agenda":"議員研修会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"政務活動費の研修ということでいろいろな角度があると思うのです。どのような趣旨というか、あと、 要望が出たということなのですけれども、どういった要望だったのかを含めて説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からも要望させていただいて、これから２つの小会議体が立ち上がるということで、みんなばらばらの状況で議論がスタートすると。一応補足で、そのとき要望させていただいた者の１人として補足をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.05.26gu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":10,"characters":8459,"voices":47}},{"id":"r08-20260527-6","meetingId":"r08-1r","date":"2026年5月27日","dateIso":"2026-05-27","committee":"区民委員会","time":"午前10時00分～午前11時９分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"第５６号議案、令和８年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第５６号議案、令和８年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"まずそこの中で１人世帯と複数人の世帯の中でもどうしても電気代の差が、そうなるとやはり１人世帯と複数人の世帯との格差というのでしょうか。算定方法も含めて教えてほしいと求めました。","respondent":"今井しながわ生活応援担当課長","answer":"一律４,０００円給付とさせていただいた理由ですけれども、区としても認識しています。例えば、その考え方は少し今回の事業の考え方にふさわしくありませんでした。","id":"exchange-001"},{"speaker":"こしば委員","kind":"質問・要望","question":"世帯の中の数と電気・ガス代が必ずしも比例するものではないという答弁をいただき、理解いたしました。この辺りの考え方、低所得世帯の方も４,０００円ということですので、その辺りをどのように検討されていたのか教えてほしいと求めました。","respondent":"今井しながわ生活応援担当課長","answer":"そういった状況の中で猛暑による熱中症リスクに直面する区民への健康面での支援ということで実施するものです。以上の経緯から、所得制限によって一定の対象、非対象の線引きをすることなく、全世帯一律４,０００円を給付することが今回の区の考え方です。","id":"exchange-002"},{"speaker":"こしば委員","kind":"質問・要望","question":"当然に猛暑ですので、エアコンを使われると電気の使用量も３割か４割くらい増してくる。当然そうなると電気代も上がってくるのですけれども、それも一応日本での料金設定であるのかどうかを教えていただきたいです。","respondent":"今井しながわ生活応援担当課長","answer":"今回の１か月当たり１,０００円で、４か月で４,０００円という金額の根拠ですけれども、２０２５年と比較して６％上昇すると想定されておりました。","id":"exchange-003"},{"speaker":"こしば委員","kind":"質問・要望","question":"本来の業務ではないわけですので、その辺りは区でどういうフォローをしていくのか。これは、当然所轄の警察との連携も必要になってくると思いますけれども、今の時点でどのように検討されているのか教えてほしいと求めました。","respondent":"今井しながわ生活応援担当課長","answer":"区内の４警察署および消費者センターと連携いたしまして、また、広く丁寧に実施することが前提としています。ご指摘のとおり外国人の店員も増えているような状況の中で、丁寧に１件、１件操作を支援していただくことは難しいと区としても認識しております。","id":"exchange-004"},{"speaker":"こしば委員","kind":"質問・要望","question":"店舗によっては、入り口の近くにあるところや結構奥まったところにあるところもありますので、その辺の周知をぜひ。店舗との関係性もあるかもしれませんけれども、ぜひ防犯にもつながる対策を進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問","question":"バニラＶｉｓａギフトカードに落ち着いたと認識しておりますが、今回はデジタル申請ということで、概要をお聞かせいただけたらと思います。どういった申請方法になるのか尋ねました。","respondent":"今井しながわ生活応援担当課長","answer":"現在、事業者とスキームの詳細な詰めを行っているところなので、今回はスキームの概要という形でご説明させていただければと思います。","id":"exchange-006"},{"speaker":"おぎの委員","kind":"確認","question":"紙のほうがあるということで、不慣れな方は紙申請ということは確認いたしました。デジタル申請ですけれども、区長の記者会見でＬＩＮＥというワードが出ておりましたが、ＬＩＮＥ を携帯電話で使うということでよろしいか尋ねました。","respondent":"今井しながわ生活応援担当課長","answer":"２５日の区長定例記者会見の資料に基づくご質問かと思いますけれども、電子申請の場合は区の公式 ＬＩＮＥを用いた申請をしていただく形で、今現在スキームを組んでいるところです。","id":"exchange-007"},{"speaker":"おぎの委員","kind":"確認","question":"以前、防災の安否確認にＬＩＮＥを活用してといったお話も出てきたと思うのですけれども、それとも今回は単純に配布のみの単会使用なのか。その辺はいかがか尋ねました。","respondent":"今井しながわ生活応援担当課長","answer":"なので、今後も同様にＬＩＮＥを用いた電子申請サービス等を実施する際には、同様のスキームで継続して使っていくことができる可能性はあります。提携先コードが ４桁、お客様番号が１６桁、暗証番号が４桁ということで、それぞれ入力していただくことになります。","id":"exchange-008"},{"speaker":"おぎの委員","kind":"質問","question":"ほかにも聞きたい方がいらっしゃると思いますので、最後に１点だけ。受け取りですけれども、セブン銀行ＡＴＭということはイトーヨーカドー等でも機械があれば受け取れるという認識で間違いないか尋ねました。","respondent":"今井しながわ生活応援担当課長","answer":"お見込みのとおりでございまして、基本的にはセブン‐イレブン全店舗に設置されているものと、提携先のスーパーマーケットですとかそういったところにも設置されていますので、そういったところでも下ろしてしていただくことは可能です。","id":"exchange-009"},{"speaker":"こんの委員","kind":"質問","question":"こうした光熱費の補助は、国でもやっていますのでそれは初ではないだろうし、何が初なのかを教えていただきたいのが１点。何点かあるのですが、まずはこの２点をお願いいたします。","respondent":"今井しながわ生活応援担当課長","answer":"前提としてですけれども、本交付金を活用した事業に関してはプッシュ型の支援を実施されたいということが推奨されておりました。今回の電気・ガス料金支援につきましては、まずは電子申請、区として支援金を給付する形を取らせていただいております。","id":"exchange-010"},{"speaker":"こんの委員","kind":"確認","question":"申請のときに、給付要件の中に申請者の本人確認とありますけれども、その契約をしている世帯主の本人確認なのか。いわゆるこの本人確認はどういう人を指して、何を申請するのか。","respondent":"今井しながわ生活応援担当課長","answer":"自治会ですとか、申請へのご協力の依頼ですとか、あるいは地域センターと連携いたしまして一定申請支援の実施も予定させていただいてあります。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"目の前でそこをタップしてくださいと教えてあげるサポートをイメージしているのですけれども、そういうものでいいのでしょうか。領収書で幾ら使ったかの確認よりもその世帯は必ず使っているという観点から世帯主を確認させていただいてといったところだと理解いたしました。","respondent":"今井しながわ生活応援担当課長","answer":"申請期限については、９月１日から１０月３１日までの２か月間を予定しています。なので、特に困難を抱える世帯の生活もこちらの事業の中で支援をしていければと考えているところです。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"申請期限ですけれども、今お聞きしていて１０月３１日は短くないですかという気がしました。１０月３１日までの２か月は少し短いかと思うのですが、その ２か月の根拠なども確認させていただきたいです。","respondent":"今井しながわ生活応援担当課長","answer":"先ほど申し上げました重複防止のために電子申請が終わってから紙申請の給付事業を開始する形になりますので、１２月頃から給付を開始いたします。なので、例えば ９月１日に申請を開始いたしまして、１２月頃ですと３か月くらい振込までにお時間を頂戴してしまうことになります。","id":"exchange-013"},{"speaker":"こんの委員","kind":"確認","question":"あるいは、一人暮らしの方が多いかと想像すると、重複の確認作業は必要ですけれども １２月よりもっと早くならないのですかというところです。お知らせの中に、紙申請の場合は１２月頃に給付ですとか、そういうものが入るのか尋ねました。","respondent":"今井しながわ生活応援担当課長","answer":"紙申請の振込のタイミングにつきましては、所管としても努力いたしまして、１日でも早く振込ができるように今後努力してまいりたいと考えております。１２月頃になりますというご案内につきましては、申請書もそうですけれども、細かく周知をさせていただきたいと考えております。","id":"exchange-014"},{"speaker":"こんの委員","kind":"意見","question":"促していくためにも、やはりスマホが必要なのだと促していくところの１つかと思うので、紙申請だともらえる期間が遅くなってしまう。すぐもらえますといったところのアナウンスをどうするか、サポートをどうするか、ぜひその辺をとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"せらく委員","kind":"質問","question":"私からも、しながわ電気・ガス料金緊急支援事業について質問させていだきます。この制度趣旨をどのように区民へ周知していくのか伺います。","respondent":"今井しながわ生活応援担当課長","answer":"委員会資料にもお示しさせていただいたとおり、支払っていただいたものに対して４,０００円を給付していくという形の事業になりますので、この面はきちんと広報ですとかホームページ等でも区民の皆様にお知らせできるように努めてまいりたいと考えております。","id":"exchange-016"},{"speaker":"せらく委員","kind":"質問・要望","question":"電子申請と紙申請を併用するということで、今回電子申請はＬＩＮＥから入るので区の電子申請サービスは使用しないのか確認させてください。ＬＩＮＥから入った際のセキュリティ、安全性はどのようになっているかも説明を求めました。","respondent":"今井しながわ生活応援担当課長","answer":"韓国企業のほうで情報漏えいが発生したというところで、今回の申請事業におきましても厳正な情報管理に努めてまいりたいと考えているところです。","id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問","question":"質問が２点あります。青パトも分かるのだけれども、この対応方法を各警察署とも連携するとおっしゃっていましたが、改めてそこを詳しく聞きたいです。","respondent":"今井しながわ生活応援担当課長","answer":"先ほど申し上げました区内４警察署との連携という部分で、区内のセブン‐イレブン店舗にも共有させていただきまして、区内全体で対応を取らせていただきたいと考えております。","id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そういった粗相があったら駄目ですから、ぜひそこはきちんと対応してほしいと求めました。令和８年度は４００件を対象としていると思うのですけれども、令和７年度も ４００件だったと思うのですが、そこを確認したいと求めました。","respondent":"吉岡地域産業振興課長","answer":"実績のところですけれども、昨年度も４００件の申請を見込んで予算を立てさせていただきました。実績といたしましては、３６３件の申込みということで、今回も４００件分の予算を提案させていただいたところです。","id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"質問","question":"医療系もあると思うのですけれども、お分かりになればでいいのですが、３６３件あった中で建設業はどのくらいの数だったのですか。ある程度のパーセンテージでもいいです。","respondent":"吉岡地域産業振興課長","answer":"その後に続きますのが生活関連サービス業、医療業、製造業で、それぞれ７％か ６％の間というところでこういった申請がありました。今までの実績を見てみますと、飲食業の方から厨房設備ですとか空調、こういった申請が多かったと認識しています。","id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひこれは建設組合３団体とかに周知をしていただくのが、ぜひ建設業のほうにも力を入れていただくというか、投げかけをほしいと求めました。これは要望です。","respondent":"吉岡地域産業振興課長","answer":"やはりこういった補助制度は周知というより割と口コミで広がるという話も聞いておりますので、各団体にどういったら伝わっていくかも含めて、しっかりこういった事業が伝わるように努めてまいります。","id":"exchange-021"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.05.27ku.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":16,"characters":17934,"voices":59}},{"id":"r08-20260527-7","meetingId":"r08-1r","date":"2026年5月27日","dateIso":"2026-05-27","committee":"厚生委員会","time":"午前10時10分～午前10時48分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"第５６号議案、令和８年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第５６号議案、令和８年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"そもそも今どういう状況の方が廃止された状況なのかというのをまず一つ教えていただきたいということ。申出の締切りというのは今のところどういう形で、また、品川区としてお考えになっていることがあれば説明を求めました。","respondent":"豊嶋生活福祉課長","answer":"８月から開始予定の廃止の方のお申出の終期、終わりですが、１月か２月の説明会では、複数年度という言い方を国はしておりました。手元の新しい情報では、終わりについては示されていないというのが、現在、こちらで把握している情報です。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その分も品川区が支給するということなのか確認させていただきたいということと、そうか、追いかけられないのか……。例えば直近で他の自治体に引っ越されてしまった方については、品川区としては周知のしようがないということなのか、確認したいと求めました。","respondent":"豊嶋生活福祉課長","answer":"説明するというのは、各自治体同じように行われることと認識していますので、ご説明としてさせていただいています。いろいろ説明を受けることがいいよねというような話が２３区の中では、基本的にはそのような対応をするということで品川区も考えてあります。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"確認","question":"最後にもう一度だけ確認させてください。これは基本的には２３区もしくは全国で一律同じような運用をするという認識でいいかどうかだけ、最後、確認したいと求めました。","respondent":"豊嶋生活福祉課長","answer":"国からそのようなマニュアルが出ているわけではないです。なので、この件に携わるケースワーカーは全て同じような対応をとるものだと認識しておりますので、そのような説明とさせていただければと思います。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問","question":"保護費の減額処分を取り消して、品川区としては、この判決をどういうふうに受け止められているのかということを一つ伺いたいと思います。品川区で不服審査請求を行った人がいたのか、また、いたとしたら、その人数についても伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"ゼロ人ではなかろうかと考えてあります。原告はいないと聞いております。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうことにもかかわらず、なぜ今年の３月までの期間の方が対象になるのか、その点についても伺いたいと思います。廃止世帯は３,７５０世帯で、就労に伴う収入の増加による廃止というのも１０.８％となっているのですが、その点についても伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"それは質問していないので大丈夫です。認識しておいてくださいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"意見","question":"令和６年度というところですけれども、その期間、生活保護が減額されたままというところでは対象になるわけですよね。そういう方にも知らせないのかということを……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問","question":"それと、受けていた自治体のほうに請求してくださいという、その期間というのは今年の３月までということなのですか。平成２５年のときにはほかの区だったけれども、３月の時点では品川区にいたという方は、その点も伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"生活保護の受給者はどこかの自治体１か所でしかその期間は受けることができませんので、品川区に今いる方は、品川区が支給するということになります。もう１点、令和８年１ 月１日以降に生活保護を開始した人の中で、あらゆる加算がついていない方はゼロ円となります。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"確認","question":"例えば２つの区にまたがって、それで前の平成２５年の最も減額されたところは別の区にいたといったら、その確認をお願いしたいと思います。東京都からのお金も入っていたと思うのですが、都支出金がどういうことで入るのか、その点について伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"都の４分の１についてですが、生活保護は国が４分の３、自治体が４分の１を持つということがルール上決められております。住所不定の方、つまり品川区に住民票がない方については東京都が持つことになっていますので、その分の４分の１です。","id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お伺いしたいのが、ではその代わりに、やはり品川区から周知を強めなくてはいけないかなと考えます。そのうち広報・周知と相談窓口で、どれぐらいの内訳でこの１億２,０００万円を使う予定なのか、大体が分かれば示すよう求めました。","respondent":"豊嶋生活福祉課長","answer":"各地方自治体が国から委託をされて行っているという考え方の下に、今回、そこの周知まで各自治体が行うということは現在考えておりません。まずは一人ずつ計算の金額が違うので、そこを間違わないように、いち早く支給するということに全力で当たっていきたいと考えております。","id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"区の各施設へのチラシの設置ということで、もともと今、区ができる体制の中でのみ行うということだと理解しました。国は今どういった周知活動をするというのを、ぜひお知らせしていただきたいのですが、いかがか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"国は既にコールセンターを開設しております。しれっと、公共施設に置かせていただくということで各自治体考えているところで、品川区もそのように考えています。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"私も本当にこれは国の責任でもっと広報すべきだと思うのですけれども、だから、要は同じ注射針を使っていたのですよね。国のほうにそれぐらいの力は入れて広報してほしいということを品川区として要望していただきたいなと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.05.27ko.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":12,"characters":12368,"voices":54}},{"id":"r08-20260527-5","meetingId":"r08-1r","date":"2026年5月27日","dateIso":"2026-05-27","committee":"総務委員会","time":"午前10時12分～午後０時48分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"第５７号議案、専決処分の承認を求めること","agenda":"第５７号議案、専決処分の承認を求めること","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"継続するものもある。例えば（１）大口株主だったら、（１）から（５） まで、ざっとでよいので教えていただきたい。","respondent":"初貝税務課長","answer":"１から５まで大まかにご説明します。実務上は、環境性能割と種別割の２つを、例えばパンフレットなどで表記していましたが、それが軽自動車税に統一されるという変更があります。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"影響はあまり変わらないのかなと感じていますけれども、（１）の大口株主は品川区の中には結構いるのでしょうか。これは国が決めることで、品川区は関係ないので、むしろ知っていたら教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区に聞きたいのは、先ほど国から補塡があるとおっしゃっていましたけれども、大体どれぐらいの補塡があるのか伺いたいです。（１）に該当する方は数名いるということですけれども、これが区民税配当割の対象となることでどう変わるのか伺いたいと思います。","respondent":"初貝税務課長","answer":"令和７年度予算額ベースで７９０万円の環境性能割の予算組みをしていますので、そちらの部分に対しての補塡であると思います。配当する時点で差し引いてはいませんでしたけれども、それが実際に配当される時点で差し引かれるという、そのような変化があります。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"意見","question":"生活に苦しむ区民へ地方税の面から抜本的な改善を図るべきということは、延長されるものもありますので、賛成はいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]},{"id":"topic-02","title":"第５６号議案、令和８年度品川区一般会計補正予算","agenda":"第５６号議案、令和８年度品川区一般会計補正予算","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"しながわ電気・ガス料金緊急支援事業について幾つかお伺いしたいと考えています。区として上乗せ補助を行うことを短期間で進めた、決めた理由、お考えをお聞かせほしいと求めました。","respondent":"加島財政課長","answer":"ですので、見え方として急になったことは大変申し訳ないと思いますが、こちらの事業については年度当初から必要な検討を進めておりました。そういった状況にある中で、区として必要なことをできないかと、今回電気・ガス料金緊急支援をご提案したという背景となっております。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"分からないですか。すみません、伝わりましたか尋ねました。","respondent":"加島財政課長","answer":"熱中症のリスクを抱え、それを低減していくという側面もありますので、区としては支援する必要があると感じたところです。私どもとしては国際情勢の影響による電気代上昇の懸念を見据えて迅速に対応するために、世帯単位で支給したいということで制度設計をしたものです。","id":"exchange-006"},{"speaker":"澤田委員","kind":"意見","question":"しかし、申請をどのように届けるのか、手元に届くようにしようと考えていらっしゃるのか。申請期限や、受け取れる日程や、紙での申請は何世帯ぐらいとお考えになっているのか説明を求めました。","respondent":"加島財政課長","answer":"紙申請ですけれども、申請書についてはご案内と同封する形で、８月下旬に世帯主宛てに全世帯に発送する予定です。申請の期限については、９月１日から１０月末日までを考えているところです。","id":"exchange-007"},{"speaker":"澤田委員","kind":"質問","question":"聞き方が下手で申し訳ありません。今、届け方と申請期限をお伺いしましたが、申請期限は１０月末で、いつ頃に振込が行われるのか説明を求めました。","respondent":"加島財政課長","answer":"電子と紙の想定数ですが、電子が８割、 紙が２割と考えております。紙申請は９月１日から１０月末に申請をいただきまして、書類の不備がないかどうか審査等をして、支給の時期については１２月１日からを考えています。","id":"exchange-008"},{"speaker":"澤田委員","kind":"質問","question":"紙が１２月１日ということですが、デジタルのほうもやはり同じ１２月１日か尋ねました。","respondent":"加島財政課長","answer":"デジタルについては、支給日は９月１日の申請開始で、即日受け取ることも可能な場合があります。","id":"exchange-009"},{"speaker":"澤田委員","kind":"質問","question":"高齢者の方こそ早めに対応しなければならないのではないか、そちらを優先してほしい思いがありますが、いかがでしょうか。お考えを説明するよう求めました。","respondent":"加島財政課長","answer":"今現在の制度設計上では、審査の過程で優先順位をつけることはしておりません。ただ、紙申請については、今後の予算を執行していく中で、少しでも早く振り込まれるように、所管課と工夫していきたいと考えております。","id":"exchange-010"},{"speaker":"澤田委員","kind":"質問","question":"次に、新機能が追加された決済端末への入替え等を挙げていらっしゃいますけれども、これらの８割から９割はリースであると聞いています。それら企業への支援策、例えばゼロゼロ融資などを行うことについて、区としてはどのようにお考えか尋ねました。","respondent":"加島財政課長","answer":"今後の経済情勢を見据えての中小企業への支援策になりますけれども、業務改善設備更新助成をご提案させていただいているところです。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"なぜこれが今唐突に出てくるのですか。これはいつから計画していたのですか、そこをきちんと説明を求めました。","respondent":"加島財政課長","answer":"本事業について検討を始めたのは４月以降になります。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜこの時期にこれをやるのですか。けれども、なぜ今なのかを教えていただきたいです。","respondent":"加島財政課長","answer":"私どもは、当初予算編成後における事情の変更を含んで、今回５月臨時会の場をお借りして補正予算を提案させていただきました。私どもといたしましては、今回の支援を緊急・迅速に行う必要があるとして、５月の補正予算に提案させていただきました。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"どうするのですか。区民の人たちにどう説明するのか尋ねました。","respondent":"加島財政課長","answer":"一般家庭で考えれば、７月から９月の３か月分で、国の支援で大体５,０００円程度の負担軽減になると私どもも把握しているところです。家計に実感できる負担軽減という額で、国の支援が決まったとしても、区としてここに支援を注いでいく意味はあると考えております。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"誰がどのような経緯でそうなるのですか。今回に関しては、どうして読売新聞や朝日新聞が報道に至ったのか教えてもらえますか。","respondent":"加島財政課長、田口戦略広報課長","answer":"先ほど申し上げました国の支援は、まだ考え方等、緩和であると捉えております。ただ、２人以上世帯の電気・ガス料金は平均額でも １,０００円程度の上昇が見られますので、区としての支援の趣旨です。 今回の電気・ガス料金緊急支援事業については、５月２２日以降を情報解禁日と定めておりました。ですので、それ以降に、 何かそのような支援などはあるかとメディアからお問合せがあったものについては、こちらで個別に対応しています。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"どうやってマスコミの人たちは気づいて、２３日にマスコミ報道するのですか。どうか尋ねました。","respondent":"田口戦略広報課長、石田（秀）委員長","answer":"今、区で何か対策をやる予定があるかとお尋ねされた場合、こちらでもこのようなことを予定しておりますというお話はしております。そのような関係でお尋ねがあった場合は、 情報解禁日以降であれば個別に対応しています。 だから、２２日に問合せがあれば、答えたということですね。だから、２３日に出ても普通だということですね。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"ほかの方も質問があると思うので繰り返したくないですが、今回のことに関しては熱中症対策になっていないというのが私の見解です。それをあたかも４月以降に分かったということで片づけないでほしいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"終了するたびに私たち共産党は復活を求めて、緊急要望をしたり、予算要望にも入れたりしてきました。期限を設けずに継続的な支援にするべきだと共産党は求めてきていますけれども、改めてそれを今日も求めたいと思いますが、いかがか尋ねました。","respondent":"加島財政課長","answer":"電気・ガス料金支援の本人確認書類ですけれども、お名前、マイナンバーカードを持っていないから決して申請できないということではございません。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"提案","question":"電気・ガスのほうは、電子申請はマイナンバーのみではないと分かりました。国に求めるものも含めて、区としてできるきめ細かな対応をぜひ求めたいと思いますし、私たちも今後提案していきたいと思っていますのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"その辺について多くの区民が疑問に思われているので、 理由を教えてください。それからお願いします。","respondent":"加島財政課長","answer":"私ども区といたしましては、また熱中症のリスクを下げていく必要があるというところは、全世帯やっていく必要があるものだと考えています。一定程度に区切ることによりまして、私どもとしては今回所得制限を設けず、全世帯を対象ということでご提案をしています。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"もうこれだけの状況が出ていたら、品川区として省エネルギーが見込める設備更新費用に対して助成する、支援をするというのはお門違いではないですか。それだったら小規模事業者に多くの支援をするべきではないか尋ねました。","respondent":"加島財政課長","answer":"所管のほうでは、区内の経済団体ですとか、窓口でのお声を聞き取って検討を重ねてきたところです。そのような状況を踏まえながら、区として必要な施策、できることがあるのであれば、今後考えていく必要があると考えております。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、ご答弁ありましたけれども、本来はもう分かっているのではないですか。死活問題ではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"山本委員","kind":"質問・要望","question":"丁寧な確認が必要だと考えておりますので、以下、質問と要望を申し上げたいと思います。お考えを改めてお聞きします。","respondent":"加島財政課長","answer":"ただその時点で、区としてこの支援の検討をやめるかというと、 そのような考えはございませんでした。国の支援については、区の支援をそこに入れることによって、家計が実感できる負担軽減に届いていない部分を支援できると考えました。","id":"exchange-023"},{"speaker":"山本委員","kind":"質問・要望","question":"引き続きそのようにしていただきたいと要望してまいります。区民の皆様に幅広く使ってもらえる、物価高対策としての支援ということなのかなと考えていますけれども、そのような認識でよろしいか尋ねました。","respondent":"加島財政課長","answer":"区で電気・ガス料金の支援を行う目的といたしましては、家計負担の軽減と、エアコンの使い控えによる熱中症リスクの低減になっております。昨年１２月の補正予算では、真夏の暑い時期等を見据えた家計の負担の軽減と熱中症リスクの低減という目的を持って進めるものであります。","id":"exchange-024"},{"speaker":"山本委員","kind":"質問","question":"１世帯当たりに換算すると９００円、約１,０００円程度の事務コストが４,０００円を配付するのにかかっていると予算からは読み取れます。この手数料は多いと思うかどうか、区のご見解をお伺いします。","respondent":"加島財政課長","answer":"ただ、仮に支援金を５,０００円と想定いたしました場合には、今回の電気・ガス料金の緊急支援事業に係る事務費の割合は１５.３％となっております。","id":"exchange-025"},{"speaker":"山本委員","kind":"質問・要望","question":"質問したのは、そこの高いと思うのかどうかというところのご見解がお聞きできなかったので、それは改めてお伺いしたいです。では、この冬の支援、それから来年の夏の支援はどのような見通しを持っていますか尋ねました。","respondent":"加島財政課長","answer":"それから、今後の見通しですけれども、今回の電気・ガス料金の支援につきましては、一過性の事業として考えております。今後の冬等の支援ですとか、また、その他の必要な支援等につきましては、区民や議会のお声を聞きながら考えていくことになろうと思います。","id":"exchange-026"},{"speaker":"山本委員","kind":"質問・要望","question":"２回分けての支援になっていますけれども、ほかの自治体では、去年の１２月に決めた時点で１万円の給付をしているところもあります。先々の見通しを持って、その見通しに対して効率的、経済動向の予測を持って無駄のない効率的な区民支援を要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"松本委員","kind":"質問","question":"本来は所管にお伺いするべきことを、引き続き私からもお伺いします。今回の電気・ガスの支援ですけれども、 申請書の発送が８月下旬ということですが、この事業自体の周知はいつ頃に行われる予定か尋ねました。","respondent":"加島財政課長","answer":"事業の周知時期は、今回補正予算の議決をいただきました後、７月頃の広報で事業の周知をしていきたいと所管は考えていると聞き取っております。","id":"exchange-028"},{"speaker":"松本委員","kind":"質問","question":"申請書が来るまで１か月以上空くことになると、７月の段階で一回周知して、あとは８月の下旬に申請書を送りますというやり方でいいのか。むしろ ８月になって真夏日が多くなった時期に、財政課長に伺うのもあれですが、この点はいかがか尋ねました。","respondent":"加島財政課長","answer":"一発目の周知ということで７月頃の広報と申し上げましたけれども、委員からございましたように、 ホームページやＳＮＳ等を活用して、きちんと申請漏れがないように、それから、地域等にも説明に入っていく必要があると考えております。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問","question":"これはどうかと思うのが、 去年も同じ時期に補正予算が上がってきて、おととしも上がってきている。去年、おととしと中小企業が置かれている状況は変わっていないというご認識でしょうか、伺います。","respondent":"加島財政課長","answer":"所管はもちろん把握しているところではありますけれども、申し訳ございません、私どもの手元には持っておりません。今回スキーム等は特に昨年と変更はないけれども、団体からの要望を聞いて、今回同じメニューで補正予算を提案いたしました。","id":"exchange-030"},{"speaker":"松本委員","kind":"質問","question":"お伺いしたいのは、これも財政課が把握しているか分かりませんが、団体というのはどこの団体とそのような話をしたのか尋ねました。","respondent":"加島財政課長","answer":"申し訳ございません。こちらについては所管課に確認をいただければと思います。","id":"exchange-031"},{"speaker":"松本委員","kind":"質問","question":"団体の関係で言いますと、先ほど申し上げたとおり、２年前も去年も同じ補正予算が上がっているということです。なので、本来的には、質問という形に戻すならば、この助成金については本予算で扱うべきだったのではないかと思いますが、いかがか尋ねました。","respondent":"加島財政課長","answer":"その点につきましても、所管に意見を申し伝えます。","id":"exchange-032"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"５月にうちの会派としても区に要望させていただきましたけれども、その中ではやはり電気・ガス、そういったことをお願いしました。光熱費の要望をさせていただきましたけれども、区としても電気・ガスの補助を、その辺の議論の経過等も含めて教えてほしいと求めました。","respondent":"加島財政課長","answer":"それを受けまして、区として今回どのような支援が、家庭に対して、それから事業者にできるか検討してきたところになっております。先ほど国の統計等の関係でも、国の支援が入るかどうかは検討を始めた段階では定かではございませんけれども、昨年２０２４年から２５年にかけて。","id":"exchange-033"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"どうしても紙という手段を使わざるを得ない方については、従来どおりになるので、一定の時間がかかることはしようがないと思います。速やかに予算が成立するということが前提ですけれども、速やかに執行してほしいと求めました。","respondent":"石田（秀）委員長","answer":"それをあえて住民票からスタートしているから、世帯分離の対応等はできないです。品川区議会自民党・無所属の会からお願いいたします。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"その要望というのも、本当に現場のこと知っているのか、調べているのかという指摘もありました。区民のほうに目を向けた施策をしていただきたいと強く求めて、賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.05.27so.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":25,"characters":30363,"voices":115}},{"id":"r08-20260527-10","meetingId":"r08-1r","date":"2026年5月27日","dateIso":"2026-05-27","committee":"議会運営委員会","time":"午後２時20分～午後２時23分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.05.27gu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":4,"characters":1205,"voices":11}},{"id":"r08-20260608-6","meetingId":"r08-m06","date":"2026年6月8日","dateIso":"2026-06-08","committee":"区民委員会","time":"午後１時00分～午後２時46分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"令和８年度区民まつりの予定","agenda":"令和８年度区民まつりの予定","exchanges":[{"speaker":"まつざわ委員","kind":"質問・要望","question":"それぞれが大変だから一緒にしてやるというのはすごくいい取組で、こういったいい取組はぜひ広めていただきたいのです。ほかの地区への積極的な横展開というのですか、まず、説明するよう求めました。","respondent":"平原地域活動課長","answer":"大井第２地区と荏原第３地区、これまでの区民まつりに加えまして防災的な要素を一緒に行うということが試行的に開始されたところです。","id":"exchange-001"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"なかなかそういうものはできないものなのですか。実行委員ですから実行委員で決めなければいけないのですけれど、どういうふうにしてほしいかなど、何かそういった思いがあれば説明を求めました。","respondent":"平原地域活動課長","answer":"例えば暑い時期に実施するところも、体育館の中で行うなどといった工夫がされていると聞いているところです。どういう対応かですけれども、各実行委員会におきましても、そのような基準といいましょうか実際の取組にすると聞いてあります。","id":"exchange-002"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"いつもの要望ですけれど、本当に地区まつりなんかにはこうやって予算をつけていただいて、 すごく本当にありがたいと思っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問","question":"それは各区民まつりの開催においては、開催の実行委員、なおかつそのこともしっかり現場を分かった上で行っているということでよろしいのでしょうか。飲食の提供などの準備には、中止になった場合のその補填というのは、それぞれ現場がしっかり予算の中で組んでやっているということか尋ねました。","respondent":"平原地域活動課長","answer":"区の事業だった場合こういうような事例で、そこを参考にといいましょうか準拠してやっていただくような方向でご説明させていただいているところです。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問","question":"このシェードポリシーの在り方とか、そういうところで何か違ってくることがあるのか、その関連を少し何かあればお聞きしたいと思います。","respondent":"平原地域活動課長","answer":"これはもともと８月にやっていたところ、やはり２か月以上前倒しをやってみたということで、時期を替えてよかったねというようなお話がございました。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"暑さに対しては本当になかなか抑えることもできないわけですので、対策をしていかないといけないなと思っています。ぜひ柔軟にご対応いただきたいということをまた、要望させていただいて、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"しながわシティラン開催報告および次回開催に向けた進捗","agenda":"しながわシティラン開催報告および次回開催に向けた進捗","exchanges":[{"speaker":"まつざわ委員","kind":"確認","question":"１件確認です。ボランティアの募集の中で、消防団の活用というのが、あるのか説明を求めました。","respondent":"山下スポーツ推進課長","answer":"消防団に関しましては、これまでも品川消防団、大井消防団に関しましては区域ですので、 警戒活動をしていただいております。こちらのほうからお申出がありましたので、毎回依頼文を差し上げまして、警戒の区域を指定いただいているところです。","id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"すると多分、これで５０人などにしてしまうと、一緒に走る方の分まで参加料を無償にしていただきたいなみたいな感覚があるのです。そこら辺まだこれからだと思うのですけれど、感覚としてはどのような感じなのか説明を求めました。","respondent":"山下スポーツ推進課長","answer":"伴走者が必要かどうかというチェック欄も設ける予定でございまして、伴走者の方の、伴走者のビブスも一緒にお送りする予定になっております。こちらの抽せん枠のほうに入ってまいりますので、お知り合いの方がいれば、お持ちかどうかをご確認いただければと思います。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"２点確認させてください。一応２次の締切りまで設けられていると思うのですが、自分も参加したかったよねと思う、その辺りの考え方を教えてほしいと求めました。","respondent":"山下スポーツ推進課長","answer":"２,５００名を設けておりますので、残念ながら当日の参加者に関しましては、当日来られた方という形でカウントをさせていただいているのが現状です。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"それでも当日の参加者が減っているということですよね。この９０.６％の参加率というのは、もう少しこの当選者数というのでしょうか、その検討の中では検討されているのか尋ねました。","respondent":"山下スポーツ推進課長","answer":"この９０％にとどまっている要因といたしましては、３月のこのような時期でございまして、それでもかなりぎりぎりを攻めて出している現状です。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"それは１００％を求める必要もないのかもしれませんけれども、しっかりまた、そこは考えていただきたいなと思います。どの段階でどう活用されるのか、これを渡していただけるのか、お聞きしたいと思います。","respondent":"山下スポーツ推進課長","answer":"結局マラソンをするときは置いて帰ったりするので、その部分に関しては今、担当と一緒に検討しています。せっかく作ったマップですので、当日も含めて、その後も活用していただけるような形で作ってまいりたいと存じます。","id":"exchange-011"},{"speaker":"横山委員","kind":"確認","question":"こちらはリバースメンターの方から具体的にどういった提言があって、どういった経緯で今回、確認したいと求めました。","respondent":"山下スポーツ推進課長","answer":"その後立ち寄っていただけるとか、その後使っていただけるようなマップになるのではないかという形でご提言いただきましたので、そのような内容を反映できるようなものを作っていく予定です。","id":"exchange-012"},{"speaker":"横山委員","kind":"提案","question":"という具体的なご提案があって、それを今回実際に形にしていくということで、確認をさせていただきました。とてもすばらしい提案内容であって、ぜひ前向きに進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.08ku.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":29,"characters":36959,"voices":76}},{"id":"r08-20260608-7","meetingId":"r08-m06","date":"2026年6月8日","dateIso":"2026-06-08","committee":"厚生委員会","time":"午後１時00分～午後３時46分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"しながわ未来の筒井ようすけと申します。１年間、どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"今回の人員増で、これが改善できる配置なのかについて、１点伺いたいと思います。主要な計画に対しては、説明会をしていただきたいと求め続けてきましたので、いつ頃どのような形を考えているのか伺いたいと思います。","respondent":"石橋障害者施策推進課長、芝野障害者支援課長、崎村障害者施策推進担当部長","answer":"説明会の実施方法等は所管で検討にはなりますが、１１月の中旬以降、その前に区民説明会を実施したいと考えております。区民説明会の日程等が決まりました… 相談支援担当は事務職が担っているのかですが、福祉職ですのでなかなか採用も難しいと聞いております。そういうのも併せて事務職を配置して… 施政方針で法的拡充ということをお示しさせていただいて、具体的にどのように進めていくのか、また拡充していくことをお示ししていきたいと考えています。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"介護保険も含めて伺いたいのですけれども、介護保険の事業計画は、そこの点を改めて確認させてほしいと求めました。介護保険は、毎回ぜひ説明会をやってほしいと求め続けてきたのですけれども、ぜひ介護保険も住民説明会を行っていただきたいと思うのです。","respondent":"佐藤高齢者福祉課長","answer":"３年に１度の計画ですので、３年前と同様に、計画に関してはパブリックコメントにかけて区民のご意見を伺うという形を取っております。障害の計画と同様に、どういった形で区民にご説明するか、これからの検討ですけれども、説明する場を設けたいと考えております。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"傍聴者もすごく少ない状況なので、それは少し工夫していただけたらと要望させてほしいと求めました。では、認知症策定委員会のことについてもいいか尋ねました。","respondent":"樺島高齢者地域支援課長","answer":"認知症に関する施策推進委員会につきましては、委員がご指摘のとおり、介護保険事業計画の委員会とは別のものになっております。６回ほど委員会を開催する形になっておりまして、ご本人、当事者の方もご参加いただく委員会となっております。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"実は結構いるという話を伺ったと思ったのですけれども、今、お聞かせいただきたいです。それで、 これを見ると保健師は、非常勤を入れても５人しかいないことになっているのですけれども、その実態がどうなっているのかを伺います。","respondent":"樺島高齢者地域支援課長、冨田地域包括支援センター担当課長","answer":"認知症策定委員会につきましては、現状、公開というのはあまり想定はしていないですが、適宜、会議録等は適切に周知していきたいと考えているところです。 ただ、今の体制のままがいいのか、どのような形が望ましいのかは検討してまいりたいと考えています。形としては、必要であればできると認識しておりますので、そういったものの必要性は検討してまいりたいと考えております。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"要望があったときには、１つか２つからモデルを始めてということなので、多分十一期までかかっていくと思うのです。さらに職員の方があまり負担でない状況で働けるような体制は、ぜひお願いしておきたいと、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"それと、６割前後からの回答というのは数としてどうなのか、評価を伺いたいです。そういうことはごく一部かもしれないですけれども、現状どうなのか、評価を伺います。","respondent":"芝野障害者支援課長、冨田地域包括支援センター担当課長","answer":"私からは、基幹相談支援センターの役割、位置づけという点について、ご説明します。総合的、それで総合的に品川区の相談支援体制をつくってありますので、基幹相談支援センターはあくまでも障害者支援課が請け負っております。６割程度の方にお答えいただいたアンケートですけれども、感想としては、６割は、比較的多い方にご回答いただいたと考えています。","id":"exchange-007"},{"speaker":"吉田委員","kind":"確認","question":"人員を増やしているのか、専門医を増やしているのか、その辺について改めて確認させてください。もし何かコメントがあったら伺いたいと思います。","respondent":"芝野障害者支援課長、冨田地域包括支援センター担当課長","answer":"地域にあります拠点相談支援センターとの連携を図るために、総合的な相談支援や相談支援体制の強化を目途に設置しているものでございまして。そちらを加味して要求していただいているものではなくて… ２０通を超えるお礼のお手紙やお電話で、３万７,０００人ぐらいの方にお配りしますので、反対される方は出てくると考えています。","id":"exchange-008"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"アンケートの回答が６０％前後で、３５％ ぐらいの乖離が、どういった原因なのかをお伺いしたいのが２点目です。実績で２億５,０００万円ぐらいかけた事業なので、ただ、誰でも確認できるような公表をするような予定があるのかお伺いします。","respondent":"冨田地域包括支援センター担当課長、山下国保医療年金課長、菅野福祉部長、五十嵐保健予防課長","answer":"アンケートの回答が６割で、３割ぐらいの方は、ご家族の方からアンケートは大丈夫ですとお断りされたりした方がいらっしゃったところです。… ７.４％、８.１％、令和７年度末時点では８.６％という現状です。３％台で、加入の率としても２倍程度で… 認知症の見守り宅配についての補足説明をします。","id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"提案","question":"公表をぜひ、有意義なアンケートは公にしたほうがいいと思いますので、その辺はご提案します。〔「死亡は減っている」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"私がなぜこの質問をしたのか、医療費で占めるのが１.４％で、品川区はどうなのか確認をさせていただきました。誰かが得をしている、ただ乗りしているということではないことは、何か機会があればぜひ周知していただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう要望をすごくたくさん受けていて、それを１点、お聞かせほしいと求めました。救える命を救うということでも、増やしていただきたいのですけれども、その点についても伺います。","respondent":"豊嶋生活福祉課長、宮澤福祉計画課長","answer":"それから区の平均年収など、区によって違う部分もありますので、一概に同じ土俵で見るのはなかなか難しいと考えています。今年度はゼロを１にすることをまずは考えて、命を守るということで進めしていますので… まず今年度取り組んだところとして、遠方に住んでいるご家族でも申請できるように、オンラインでの申請も受付できるようにしました。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ゼロを１に、品川区から先に予算化したということで、それはよく分かりますけれども、東京都がこういう形で４分の３になりましたので、柔軟にご検討いただけたらと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.08ko.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":37,"characters":50937,"voices":87}},{"id":"r08-20260608-8","meetingId":"r08-m06","date":"2026年6月8日","dateIso":"2026-06-08","committee":"建設委員会","time":"午後１時００分～午後３時０４分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"えのした副委員長","kind":"意見","question":"副委員長を務めします、えのした正人です。１年間どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"私たちとしては、中間見直しの予定はあるのか、もしあるとしたらどれくらいを考えているのかというのをお伺いしたいのが１つです。併せて、４月から阿部部長が東京都から着任されたということなのですけれども、簡単に略歴等も伺えればと思います。","respondent":"髙梨都市計画課長、阿部都市整備推進担当部長","answer":"立体交差事業等々、東京都等と非常に密に連携・協議をしていなければいけない業務であり、担当部長を設置したものと認識しています。東京都から派遣いただくことで、東京都との連携をより密にして… 管理職になってからは、 ほとんどが下水道関係、治水対策等をやっていたというところです。１０年ぐらい前になりますけれども、まちづくり関係というところで、新しく来たです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"例えば騒音に対する住民からの苦情とか相談とかというのを受け付けていらっしゃるのかというのを伺いたいのと、ここで聞くのですが。昨年度も分科会４回、幹事会２回行われて、そこについても併せて最後に伺わせていただきます。","respondent":"髙梨都市計画課長","answer":"区民負担軽減につながる具体的な取組を早期に行っていただきたいといった各種固定化回避検討会等々に区から要望書を国土交通大臣宛て等で出していま…改めて我々レベル、部長・課長級レベルにおいても、国に対してしっかりと区の要望事項を伝えられる場として認識しています。","id":"exchange-003"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"人的被害もないということで、非常に安心しております。物的被害のところで１点お伺いしたいのですが、どちらのエリアで、どういった状況なのかを簡単にお聞かせほしいと求めました。","respondent":"森道路課長","answer":"それから道路冠水につきましては、大井一丁目立会道路のところが１か所、もう一か所は確認して、 後ほどご答弁いたします。もう一か所は東五反田です。","id":"exchange-004"},{"speaker":"おぎの委員","kind":"質問","question":"今の計画でこのまま進めていけば、こういった問題は特に見直ししなくてもいいのかをお聞きしたいのが１点です。１点、今の計画で大丈夫かという部分だけ見解をお願いいたします。","respondent":"関根河川下水道課長","answer":"は下水道管内にたまった空気を逃がす必要もあるということで、潮位の影響といった構造上の影響もあったのかと考えているところです。ですので、何かできる対策があるかといったところは、今後下水道局と連携して取り組んでまいりたいと考えております。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"それと自主避難施設の運営で、今回１０名の方が避難ということでしたけれども、運営してみて今後に活かすべき課題などは何かあったのでしょうか。１０名の方が避難ということなのですけれども、そういうのはあるのでしょうか、伺いたいと思います。","respondent":"森道路課長、羽鳥防災課長","answer":"そちらのドアの開閉部分に雨の水が少し入って、不具合が生じたと聞いております。管理会社がすぐに駆けつけまして、部品等を交換して、夕方１９時には復旧して、運転を再開しているところです。 大雨であれば、ホームページ等では丁寧に説明をさせていただいているのですけれども、そういった問合せもコールセンターに何件か来ておりました。避難指示の発令と避難の行動については今後も丁寧に周知していきたいと考えています。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"出さないで、こちらが予想していた以上に風雨が激しくなったら大変なことになるわけですから、区内全域への避難指示が出るわけですよね。ですから、いろんな媒体があるものですから、啓発というのはすごく大事だと改めて思ったわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"なぜ２０時だったのかというところを１点お聞きしたいと思います。併せて、この時点で２か所を開設するよりは先にと考えるわけですが、その辺の避難所開設の考え方というところも確認したいと求めました。","respondent":"羽鳥防災課長","answer":"区民の皆様からの様々なお問合せに対応できるような態勢をまず一旦取ったということです。その５か所をいずれもレベル４の土砂災害の危険警報が発表された段階で開設することを決定して、開設に至ったという流れです。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"できれば夕方ぐらいの時間でというのがあってもいいのかなという思いで、２０時がなぜその時間だったのかというのを確認させていただきました。そうだったのだと私自身も確認しましたが、そうではないですよ、そこら辺のアナウンスというのは本当に大事だなと思うところです。","respondent":"羽鳥防災課長","answer":"早めの開設のところに関しましては、今回早めに、１３時に台風会議を開いて、方針を決定させていただいたところです。様々検討した結果、１７時に本部、２０時に開設ということでございました。","id":"exchange-009"},{"speaker":"こんの委員","kind":"質問・要望","question":"細かい課題等々が見えたところは、次回そこを活かしていただきながら、引き続き対応してほしいと求めました。今回も本当にありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"高橋委員","kind":"質問・要望","question":"１点だけ質問なのですけれども、合計８３件あって、半数ぐらいはあったのですか。今私の想像で話しているのだけれども、分かれば教えていただきたい。","respondent":"羽鳥防災課長","answer":"２０件近くであるという認識です。同様に多かったお問合せといたしましては、避難に関するものが２４件のお問合せいただいたという状況です。","id":"exchange-011"},{"speaker":"高橋委員","kind":"質問","question":"今まで ５だったのを、夏になったら８にするとか、そういう対策があるのですか。過ぎ去った後、低気圧の大きいのが通ったときもそうなのだけれども、区内でどういうふうに音量調節をしているのかというのを説明するよう求めました。","respondent":"遠藤防災体制整備担当課長","answer":"新庁舎の移転に伴いまして、スピーカーも、音響に関しても今後検討していきます。こちらで改善できるところがあれば、改善していきたいと考えております。","id":"exchange-012"},{"speaker":"高橋委員","kind":"質問・要望","question":"特にご高齢の方とか、それぞれ、それは分からないですよ。避難していいのかどうかというのも含めて、コールセンターにかかってくると思うので、ぜひ検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"えのした副委員長","kind":"質問","question":"そして今回は防災対策を本当に迅速にしていただいて、感謝を申し上げます。なぜ避難指示を出すのとか、６月１日の広報しながわにも垂直避難をご案内していただいたと伺いましたけれども、あればお聞かせ願えますか尋ねました。","respondent":"羽鳥防災課長","answer":"今後出水期はまだ続きますので、事前の広報というところで、避難についてもしっかり周知してまいりたいと思ってあります。","id":"exchange-014"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"しっかり周知啓発をしていただければ、こちらは要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"安藤委員","kind":"提案","question":"所管事務調査、幾つか提案したいのですが、１つ目は住宅なのです。ここは思い切って見直すべきときなのではないかと、まちや暮らしへの影響について、所管事務調査に入れてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"こんの委員","kind":"提案","question":"確認ですが、今の安藤委員のご提案の中の住宅という観点は、その辺も含めて正副でということですか。確認ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"安藤委員","kind":"提案","question":"再開発について提案させていただいたのですが、世田谷区とか練馬区とかは、まちづくり条例をつくっているわけです。環境とか条件が２３区内の品川区と合うかというと、ぜひ２３区ですとか、東京都内といったところもぜひ選択肢に入れていただきたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.08ke.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":30,"characters":38488,"voices":95}},{"id":"r08-20260608-9","meetingId":"r08-m06","date":"2026年6月8日","dateIso":"2026-06-08","committee":"文教委員会","time":"午後１時00分～午後３時40分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"山本副委員長","kind":"意見","question":"副委員長を務めしますしながわ未来の山本やすゆきです。１年間、どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"それで、この４月での担任の不在があったのかも分かれば伺いたいと思います。校庭にシェードを上に通すような学校も、ほかの地域でもあったりするので、そうしたものも参考に検討されているのかを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"提案","question":"保護者からも遊べなくなってしまったという声等を伺いますし、議会からも、提案等をしていきたいと思っています。ここは区だけでどうのというところではないでしょうけれども、こちらからも提案等をしていきたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"西本委員","kind":"確認","question":"今年は予算もかけている関係上、これからの令和８年度のこの文教委員会の中でも、お考えをお聞きしたいと思います。そうなってくると、どういう関係を持ちながらやっていくのでしょうかということの全体の考え方をお聞きしたいと思います。","respondent":"荒木学校施設担当課長、石井学務課長、髙木教育施策推進担当課長、舩木庶務課長","answer":"今年度の検討内容につきましては、残りの２校を除いた１６校についても知見やノウハウといったことは反映してまいりたいと考えています。ですので… さらに国が見る部分の残りの２分の１は東京都が見るので、簡単に令和８年度予算ベー スで試算しますと、約９割程度の国と都の財源が入る部分です。… 企業や地域の方と連携する際の講師費用を、ＩＣＴを活用して、自分の考えを可視化したりですとかといったことを支援するアプリを導入しました。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"教育委員会として取り組むのは初めてになってくると思いますので、しっかりやっていただきたいと要望して、いろいろと報告をお願いしたいと思います。今の現状を考えると、ぜひそういう観点で、これから密に連携を図っていただく一つの事業として発展していただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"なかなか教育長や次長のお考えを伺える機会はないので、よろしくお願いしたいと思います。そしてもう１つは、当然ですが、その意気込みを伺います。","respondent":"伊﨑教育長、小林教育次長","answer":"重点校等々進めておりますので、今年もそれを継続するとともに学校を拡大して進めていきたいと考えているところです。これが全て子どもを真ん中に置いた支援、家庭への支援を広げることで… そういう中で、１つでも多く現場の声を聞いて、しっかり丁寧に意見を聞いていきたいと考えています。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問","question":"なかなか１年の最初に教育長や次長の意気込みを聞く機会がないので、すみません、あえて伺いました。そのようにしていただけるというそういった意欲も、言い方は失礼ですけれども、決意も伺えたので、ぜひお願いします。","respondent":"伊﨑教育長","answer":"特別支援教育に関しましては、やはり特別支援教育が教育の一番の基本的な形、特別支援教育は進めていきたいと考えております。自分の学校のビジョンを明確にして進めていけるように教育委員会として指導・支援をしていくというスタンスを大事にしていきたいと考えています。","id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"今回はそういった意気込みをお伺いしたので、また別の機会にお尋ねしていきたいと思います。ぜひ、１年間、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問","question":"令和８年、今現在はどういう状況なのか、もう何か取り組まれているのか伺いたいと思います。課題解決にしていったりとかするのかという、今後の取組のところで、もしあれば伺いたいと思います。","respondent":"柴田子ども施策連携担当課長","answer":"検討体制の強化ということで、専門的な知識を持った方に検討にご参画いただきたいということで、今、部会をつくることを考えてあります。現在も健康課ですとか人権・ジェンダー平等推進課とそれぞれ実施事業を共有しておりまして、様々、情報共有をしながら進めているところです。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"提案","question":"引き続き、見守りつつ、提案もさせてほしいと求めました。さらなる周知と引き続きの各部署との連携等、これも見守っていきたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"この間、どうされるのですか。この実態をどうされているのですかというのを説明するよう求めました。","respondent":"柴田子ども施策連携担当課長、柏木子育て応援課長、佐藤保育入園調整課長","answer":"どちらの事業も委託という形で実施しているのですけれども、そういったところを区として受け止めて、今後の事業展開につなげていく。… 高校生奨学金につきましては、以前は完全貸付けという形でやってございましたが、平成３０年度に奨学金免除制度を導入しています。ただ… 方針としましては、単独の幼稚園につきましては、閉園も視野に入れての検討というところで、方針を出しています。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"それも関係なく、品川区の現状として、一律にみんな無償で、保育料は何もかかりませんという認識でいいか、そこだけ確認させてください。具体的なことはこれからなのでしょうが、当面、廃園はないという認識でいいのかどうかを確認したいと思います。","respondent":"佐藤保育入園調整課長","answer":"先ほども少しご説明いたしましたが、認可外保育施設等につきましては、同等の助成が受けられるという形での負担軽減をしています。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこでまず第一に、子ども未来部として、最も今年度、重点的に取り組みたい課題はどのようなものとお考えでしょうか。大変幅広い事業を行わないといけないということで、大変さは認識しておりますが、今年度にかける意気込みを伺います。","respondent":"米田子ども未来部長","answer":"子どものことについて広く認識をしていただくということが重要だと考えていますので、それから、広くお示しをしていければと思います。その事業を実施している中での利用者に対するアンケートだったり、困り事を広く、私どもの部門の事業だけではないと思うのですけれども。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"子ども施策のプロとして、必要な場合は子どもを真ん中に置いてという考え方で意見を述べていって、施策に反映していってほしいと求めました。様々な提案がトップおよびその周辺から出てくると思うのですけれども、その点についてのご見解を伺います。","respondent":"米田子ども未来部長","answer":"そういうものを中心に置くのではなく、子ども全体に対しての利益あるいは組織全庁的に運営していく中において何が一番最善なのか。こういうものを模索していくことが重要だと考えていますので、家庭もそうですが、そちらを念頭に置いて注力していければと思っています。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"令和６年１０月に開設されたということで、様々な状態の子どもたちを対応していくというところでは、やはり職員の皆様の力が大事だと思っています。やはりここが大事になってくるのかと思うのですが、ここでの人材の確保と育成での課題は今の時点であれば伺いたいと思います。","respondent":"阿部児童相談課長","answer":"そういった中で、例えば性被害を受けられてしまった子どもへの対応など、そういったところの専門的な能力の習得について課題を感じているところです。","id":"exchange-015"},{"speaker":"西本委員","kind":"確認","question":"それから一時保護所は品川景徳学園のことですか。それともこの一時保護所というのは、ほかの施設もあるのか尋ねました。","respondent":"阿部児童相談課長","answer":"３点目の子ども家庭支援センターの連携について、そのご家庭にとって、より子どもの支援になりそうな案件などがあります。子ども家庭支援センターのほうで協力といいますか、適切な機関で対応していくというのが、両機関での両輪での支援の具体的な中身となっています。","id":"exchange-016"},{"speaker":"西本委員","kind":"意見","question":"品川区の中に１か所あるのですね。今後、動向を調査等々しているのであれば、その報告もお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問","question":"２つ目に、どれを重点的にというお聞きの仕方が失礼かもしれませんが、令和８年度は重点的に取り組む課題はどのようなことになるのでしょうか。ほかの委員からのご質問もありましたれども、職員体制などを含め、どこに力を入れていこうかとお考えになっているか伺います。","respondent":"原品川区児童相談所長","answer":"子ども家庭支援センターもそうですが、非常にスピーディーに検討できる、より強くしていく部分ではないかと考えています。そういう姿勢を今の若い新しい経験の浅い職員に伝えていきたいなと考えています。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"意見","question":"令和８年度ということは新たなスタートというか、私も責任を持って、支援していきたいと思います。１年間、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"これから委員から要望が出てくるとは思いますけれども、ぜひとも探究的な学習を柱に私はやりたいのです。一応、要望は出しますけれども、ご理解を求めたいと思って発言させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.08bu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":38,"characters":50732,"voices":114}},{"id":"r08-20260608-5","meetingId":"r08-m06","date":"2026年6月8日","dateIso":"2026-06-08","committee":"総務委員会","time":"午後１時00分～午後２時47分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"見習だと１,６３７円と大きく下がってしまう中で、しっかり担保されるのかを伺いたいと思います。これはどういった理由なのかを伺えればと思いますし、この間、そういった姿勢が変わったのかどうかも伺いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"２０３０年までカーボン・オフということだと思いますので、ぜひこれを早く進めて、カーボンは ６０％ですか。公契約条例については、会計年度とか区の給料表を参考にされているということでよろしいか尋ねました。","respondent":"廣瀬経理課長","answer":"失礼いたしました。そちらは委託の金額でございまして、工事の部門については工事の設計単価を出すときの公共工事設計労務単価を参考にしております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"昨年度は ５名、一昨年度は４名採用されているということで、現状を伺いたいです。まだ届いていなければ、どう推進していこうと考えているのかを伺いたいと思います。","respondent":"廣瀬経理課長、木村人権・ジェンダー平等推進課長、横田人事課長","answer":"最初の労働報酬下限額の話ですけれども、公共工事設計労務単価と同額ではなくて、そちらを参考にして９０％を目安として算出しております。現在町の中の会議体での説明を行っているところです。今のところ、計画を推進するというところで昨年の計画策定のところから相談を各課としておりますので… 私からは、障害者雇用の採用について説明いたします。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこを確認させていただきたいです。何年やったら熟練なのかが分かれば伺いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（秀）委員長","kind":"質問","question":"のだて委員に申し上げますが、それを幾らでどうとか細かいことに入るのは、ここでやるべきではないと私は委員長として思っています。それを踏まえて質問していただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"つまりは、公契約の労働者が熟練となるのは、何年くらいになるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのは行政計画やプランについて、また、策定や準備を検討しているものはどういうものがあるのかご説明ほしいと求めました。現在策定して準備しているものがあれば、今年の特徴は何かという質問の中でご説明いただけたらと思いますけれども、いかがか尋ねました。","respondent":"藤村企画課長","answer":"ただ、今の区のほうは総合実施計画に基づいて様々な事業を進めているところです。令和７年度から総合実施計画を始めてまいりまして、そういったものを踏まえて各種事業の推進を図っていくというところで考えています。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えばこういうものは行政計画各プランの策定とか、その準備に当たるのではないかと思うのですが、任期が２年なのでもう１年やって残りの１年なのか。今年から１年やって来年もう１年なのか、いずれにしても新しい行政計画や各プランについて、改めてご説明いただけたらと思います。","respondent":"木村人権・ジェンダー平等推進課長、藤村企画課長","answer":"今年の３月に終了いたしましたが、前年度の推進状況評価を報告するということを実施していきますので、委員の方々と実施をしていくところになります。そちらも含めて検討していくというような会議体になっておりますので… 計画策定を予定しているもの、更新を予定しているものも含めてですが、特別支援に関わる計画は教育委員会で検討しています。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"この１年間のどこかで、ぜひ総務委員会に報告をしていただきたいと、これは要望で結構です。要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"それから修正、そして変更等に対して、ＣｈａｔＧＰＴなどを利用して推進するような方向に向かっているのかどうか教えてください。それとも、ＣｈａｔＧＰＴなどを使って企画等に取り組んでいるのか、その辺について現状を説明するよう求めました。","respondent":"西澤ＤＸ戦略担当部長","answer":"ただ、そういった職員も多くいますので、今年はもう少し教育といったところも含めて実施して普及に努めていきたいと思っています。そして、やはり行政の効率化を目指していきたいと考えております。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"こういうことを疑問に思うのですけれどもこれはどうしたらいいですかと言うと、それなりに返事が返ってきて、またそれなりに回答してくれる。一人一人の意見をそこに打ち込めば勝手に返ってくるのですから、そういう幅広い使い方をぜひ取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"公契約条例ができて今運用しているので、どんなふうに進んでいるかが１つです。取りあえず策定された計画をどういうものかしっかり見ていきたいのと、今後どういう計画が必要なのか、この２つを提案したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"毎年行っているので行き過ぎている人は置いておいて、行っていない人を主体に行かれたらどうかと思います。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"やはり身近で同じような苦労を抱えている自治体を何か所か回って、全部回れるのであれば全部回ってというのも近いからいいと思うのです。何かいい試案があったらそこを皆さんで議論して、この品川区にとっても活かしていくという考え方がそろそろ必要ではないかと私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.08so.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":29,"characters":33788,"voices":141}},{"id":"r08-20260609-21","meetingId":"r08-m06","date":"2026年6月9日","dateIso":"2026-06-09","committee":"子ども若者支援・共生社会推進特別委員会","time":"午後１時00分～午後１時46分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"松本委員","kind":"意見","question":"確かに５７園出てきているのですが、４月１日から始まった事業と理解していますが、受付状況が準備中と書かれているところがかなり多い。まだ大半が準備中という状況と思いますが、今後の動向といいますか、どうなっていくのかということをお願いできればと思いますとの意見を述べました。","respondent":"佐藤保育事業担当課長","answer":"職員配置ですとか、事業者に対する支援を継続して行うことによって、実施していく施設を当然増やしていくことが必要であると認識しています。例えばそういった声が非常に大きくなってしまって、一定程度の問題になっているかというと、そういった状況ではないという認識です。","id":"exchange-001"},{"speaker":"せお委員","kind":"質問","question":"これが細かい内容になるのかが分からなくて、今後取り上げるかどうか分からないので、お聞かせいただきたい。巡回相談に関連して５歳児健診が始まっていて、ここの関わりは私も前から質問していますが、まず説明するよう求めました。","respondent":"佐藤保育事業担当課長","answer":"まず巡回相談においては、保育園の先生の皆さんに対して、特別支援児に対する対応方法等の研修という意味合いを持って実施をしています。","id":"exchange-002"},{"speaker":"せお委員","kind":"質問・要望","question":"２９ページ、だけれども、トータル在園数は減っているわけです。いろいろ考えていらっしゃると思うのですけれども、そういったところも現在、どう考えていらっしゃるか説明を求めました。","respondent":"佐藤保育入園調整課長","answer":"冒頭に申し上げました単独園の閉園の検討につきましても、城南・浜川につきましては、一定数の４歳児の在園もある状況です。もともと幼稚園の人数の減少等も鑑みながら検討を進めるということで、施設の状況を確認しながらになりますが、引き続き検討を進めていく状況です。","id":"exchange-003"},{"speaker":"せお委員","kind":"質問・要望","question":"最初にもある行政経営資源を有効活用する観点からといったところがどんどん薄れていってしまうと昨年から見ていると感じていたので、そこは早急に検討していただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"おぎの委員","kind":"質問","question":"私からも１点だけお願いいたします。保育園ですけれども、令和７年６月より第１子無償化が始まりまして、それ以降の希望申込み等の全体的な流れは今までどんな感じか尋ねました。","respondent":"佐藤保育入園調整課長","answer":"委員おっしゃっていただいたとおり、そこの要因に関しては、無償化等の部分についても一定の要因になったと認識をしております。受入れの体制等を含めて、先ほど申し上げた園の支援等も含めまして、受入れの体制に関しては整えていきたいと今後も考えております。","id":"exchange-005"},{"speaker":"おぎの委員","kind":"意見","question":"大きな流れの変化があった場合は、またこちらでもご報告いただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問","question":"これは委員長に聞くのですけれども、議運でどうだったか、自分も今、覚えていないのですが、概要説明でひとり親も含めて説明いただいたのですけれども、この委員会の質疑、審査項目の中で、今後ここでそれに関わることになるのですが、ひとり親について取り上げるタイミングはどうなるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"つる委員","kind":"確認","question":"そうなのですけれども、質疑の機会がある調査項目として、委員会の日程の中であるかないかという確認です。","respondent":"西本委員長","answer":"分かりました。後ほど皆様方にお願いをいたしますけれども、これから項目に関しましてはご要望をいただきまして、そこで正副で調整していきたいと考えています。","id":"exchange-008"},{"speaker":"つる委員","kind":"確認","question":"分かりました。それで、そのときに確認します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.09kw.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":14,"characters":13905,"voices":56}},{"id":"r08-20260609-20","meetingId":"r08-m06","date":"2026年6月9日","dateIso":"2026-06-09","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午後１時00分～午後２時00分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"ゆきた副委員長","kind":"意見","question":"副委員長の公明党のゆきた政春です。１年間、どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"当時、部長ですか、これについては、 スケジュール等も検討をしていただくというような、たしかそういうご答弁をいただいたと思います。そこについてしっかり説明をしていただきたいということを、これは多分、ここについての検討状況について説明を求めました。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"具体的検討事項のまとめを踏まえまして、事業化検討状況につきまして、令和９年１月の本委員会にてご報告する予定です。３０日を予定していますが、３月３０日にリバースメンターに向けた事業化報告会、区長からのリバースメンターへの報告会を実施する予定です。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"提案","question":"確認をさせていただいて、そもそもこの事業自体が、中高生自ら政策提言をして社会を変える実感を持つということが１つの目的になっている。子どもが提案をしたことを実現して社会を変える、そこについては我々も責任があるので、やはりそこで精査をしなければいけないとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ＳＤＧｓの推進事業について伺いたいのですけれども、私、少し基本的なところが分からないところを教えてほしいと求めました。ＳＤＧｓの１７の目標が出されていると思うのですけれども、そういうものはあるものなのか、その点について伺いたいと思います。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"７月から、指標の見直しの検討を、１１月にかけて計画素案を作成する予定です。ＳＤＧｓ推進本部を経まして、本委員会への報告と内閣府への素案提出を行いまして、１２月から１月にかけてパブリックコメントも実施する予定です。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"それで、ＳＤＧｓ推進課ですか、課になるのですか、ＳＤＧｓ推進課という課の職員は何人くらいいるのかということもお聞かせいただけたらと思います。例えば、ＳＤＧｓの目標に対しての品川区の課題はそれぞれどうなっているかみたいな、その点についても伺えたらと思います。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"１点目の計画策定で、推進本部のほうでやるのかというご質問なのですが、こちらにつきましては、中心はＳＤＧｓ推進本部、区長を本部長とした推進本部で……。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"では、本部というのは、どういう構成でつくられているのかを教えてほしいと求めました。すごくよかったなと思っているのですけれども、これもぜひ説明会もしていただきたいと思うのですけれども、その点も伺えたらと思います。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"１点目の区内の執行体制につきまして説明しますと、こちらにつきましては全庁的な連絡調整を行います。パブリックコメントを実施する際の住民説明会の実施ですが、検討中ではありますが、映像でのオンラインでの説明を。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問","question":"ぜひ説明会は、国の認識もいろいろと高まるというところにもつながっていきますので、やる方向でぜひご検討いただけたらと思います。もう１つ伺いたかったのが、どういう形で実際に活動が、メンバーも含めて教えていただけたらと思います。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"２ページ目の専門部会につきましては、先ほどの推進体制の中でお伝えした部会とはまた別物というご認識でお願いいたします。こちらは年４回程度実施されまして、３回検討会を行って、そこの考え方でまとめを行うような形でスケジュールを考えてまいります。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"すみません、あともう１つ、公有地のところで伺いたいのですけれども、２番の東品川清掃作業所のところのスケジュールを教えていただきたいのです。そこら辺のスケジュール、いつ頃、どういうふうに決まっていくのかというスケジュールも含めてお聞かせいただけたらと思います。","respondent":"井添政策推進担当課長","answer":"東品川清掃作業所のところと関連して、中延四丁目の中野中継所の案件ですので、私のほうから回答します。こちらは公有地の資料の２番目の旧品川清掃作業所のことではなくて、恐らく北品川の……。","id":"exchange-008"},{"speaker":"山本委員","kind":"質問・要望","question":"特定事件調査の機会にお伺いして意見を申し上げたいと考えていますけれども、この機会に１点、財政計画に関してお聞きしたいと考えています。２年前、予算特別委員会の総括質疑で詳しくご説明を要望して、その後も度々申し上げてきております。","respondent":"加島財政課長","answer":"長期の財政シミュレーションにつきましては、こちらは将来の財政状況を把握する上で有用な手段であるということは区としても認識しております。長期計画をはじめ総合実施計画、現在、整理をしています。","id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"昨年度ですか、そういうことも踏まえて、ご検討を前に進めてほしいと求めました。今年度の特定事件調査で扱われるときには、何らかの進捗やアウトプットがなされることを要望し、 期待し、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"まつざわ委員","kind":"質問","question":"４つぐらい出ていますけれども、旧荏原第四中学校がああいう形であったときに、図書館の在り方があるわけではないですか。今回、そういったことを出していただけると大変ありがたいかなと考えていますけれども、それについて意見だけ。","respondent":"中川公有地活用担当課長","answer":"エリアで考える必要は確かにあるかと思います。その中で所管とも協議しながら総合的な検討を進めてまいりたいと考えています。","id":"exchange-011"},{"speaker":"まつざわ委員","kind":"意見","question":"ぜひこの委員会でも何かそういったことを、これから会議の中であると思うのですけれども、その課題の１つにしていただければいいかなと思っています。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"今回も、もしよろしければ、こういったところを視察したらどうですかというようなご提案をさせてほしいと求めましたし。１日かけて移動する意義、また事務局の皆さんのご協力も得て進めてほしいと求めましたが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.09sd.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":18,"characters":19475,"voices":70}},{"id":"r08-20260610-22","meetingId":"r08-m06","date":"2026年6月10日","dateIso":"2026-06-10","committee":"まちづくり・公共交通推進特別委員会","time":"午後１時00分～午後２時36分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"石田（秀）副委員長","kind":"意見","question":"昨年に引き続いて副委員長を拝命いたしました、自民党・無所属の会、石田秀男です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"資材不足や高騰の影響がないのかどうか伺いたいのと、現庁舎解体基礎調査に４月から着手するということですけれども、これはどのような調査をするのかを伺いたいと思います。","respondent":"小林新庁舎建設担当課長、泉広町事業調整担当課長","answer":"およそ令和１０年あたりの納期の時期になりますので、近々に今、必要となっている資材ではないというところが現状です。いわゆる工事の施工への影響というのは、代替品の検討や工程上の工夫など… 解体の基礎調査の具体的な内容というお尋ねかと思います。補助１６３号線との近接が予想されてありますので、全体的にそういった可能性があるのかといった、次の調査につなげるための調査を行うところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったバス事業者への、家賃助成や運転士採用強化支援などの実施を今考えていらっしゃるのかどうか、伺いたいと思います。トラックスは経由して、元の終点に戻してほしいという声が寄せられましたので、どうにかできないかと思うのですが、いかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"区単独での支援がなかなか難しいという状況ではありますが、総合的なバス事業者支援のパッケージを予算化もしくは計画として検討していますので。２点目の、その辺りは、バス事業者のほうで総合的に様々な利用者の意見を踏まえながら決定したものだと認識しております。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"井０１路線のところは、ぜひ、区でできることをやっていただきたいと要望しておきたいと思います。やはり区営住宅というのが１つ、ぜひ検討していっていただきたいと思うのですが、いかがか尋ねました。","respondent":"川原住宅課長","answer":"これに代わるものとして、民間賃貸住宅への支援というところで、セーフティネット法も令和６年１０月に改正されたところです。引き続き、不動産協力会社９９社とも連携を深めまして、引き続き協力要請を行っていきたいと考えています。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところでしっかり支援していってほしいと求めましたし、実際、区内には専用住宅は２戸しかない。これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"総論的なところで１点だけ確認したいのですが、より一層、法律違反に対する罰則が明記されたということだと思います。その辺の表記に対する考え方は変更することが、まず検討されているのかどうか、現状をお聞かせほしいと求めました。","respondent":"原交通安全担当課長","answer":"事故の危険性の多い・少ないに応じまして、表現の仕方も調整しているような状況です。その後に青切符での反則告知をするという大きな方針がございまして、使い分け、周知・啓発のスタンスを定めてまいりたいと考えています。","id":"exchange-006"},{"speaker":"田中委員","kind":"意見","question":"マナーというのは、例えば食事をするときのマナーなど、社会人としてあるべきルールに基づくことが、評価に値するといいますか。交通安全の実効性が高まるのではないかと考えていますので、そういった視点も踏まえて今後の安全対策に臨んでほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"それぞれのところで伺いたいのですけれども、一応、所管というか取り仕切るというところでの質疑応答ということでよろしいのかというのが１点です。令和 １１年が目標年度ということで、改定していくということになっていくのかどうかというところの、現状での見通しみたいなものをお伺いしたい。","respondent":"三井新庁舎整備課長、櫻木地域交通政策課長、川原住宅課長","answer":"現実問題、新庁舎整備課だけで進められるものではございませんので、また各窓口の所管課を含めて検討していく内容になっています。ただ… いわゆる地域公共交通計画や方針などの前倒しでの見直し等のお尋ねですが、大崎地区でＡＩオンデマンド交通を予定しておりますので、一定。… 地価が上がっていて売買しやすい状況が、やはり委員がご指摘のとおり、非常に売買が成立しやすい環境になるのではないかと感じております。","id":"exchange-008"}]},{"id":"topic-03","title":"子育て世帯への住まいの支援","agenda":"子育て世帯への住まいの支援","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ぜひ利用される制度にしてほしいと思うのですけれども、いかがでしょうかというのと、あと対象経費です。これを利用する際に、町会加入は義務だ、防災訓練に参加することが義務になるなどということがあるのかどうかを伺いたいと思います。","respondent":"川原住宅課長","answer":"敷金は、戻ってくることも考えて対象経費から外してはいるのですけれども、物件の家賃金額の約１か月分というところが相当なのかなと考えております。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、町会加入以外は、絶対にやらないといけないというものはないということですか。そこを確認させていただきたいのと、ファミリーですから１５万円とか、利用される制度にしていってほしいと求めました。","respondent":"川原住宅課長","answer":"１点目にご質問いただいたことについてお答えします。チェック項目を設ける形でございまして、その２つを含めてきちんとやってくださるだろうということを、自己申告いただきたいといった思いがあります。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"何点かお伺いしたいのですが、品川区内に ２年以上住んでいる方が対象であって、１８歳以下の子どもを養育されている。目的が、２年以上住み続ければ今までどおりでいいのではないかという話ですし、その辺のもう少し明確な目的というのをご説明ほしいと求めました。","respondent":"川原住宅課長","answer":"Ａ４縦の資料の「子育て世帯への住まいの支援について」というところでは、令和３年以降、データとして明らかになったところです。さらに広く３ＬＤＫ以上の部屋を探したときに、住替えも一定、区内の方を対象とした転居費用助成を創設させていただいたといったところであります。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"継続する・しないは言えないのかもしれないのですが、その辺の将来性といったことも、ぜひお聞かせほしいと求めました。改めてお伺いしたいのと、宅建協会や全日本不動産協会の理解が得られているのかどうかが気になるので、その辺もお伺いしたいと思います。","respondent":"川原住宅課長","answer":"そして２点目は、７月１日予定で始めて、助成対象となった方には任意でアンケートにも答えていただきたいと考えています。なので、いろいろな窓口を増やしていくといったところでは、引き続き不動産団体の方にもご協力を仰ぎながら進めていきたいと考えています。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"やっぱりぜひ進めていただきたいというのが、これまでの質疑・一般質問等も含めて感じていただいていると思うので、ぜひこれをしっかりリンクさせる。ぜひ工夫したほうがいいのではないかと思うのですけれども、その考え方と工夫について、ご意見があればお聞きしたいと思います。","respondent":"川原住宅課長","answer":"２つ一緒にタイアップという形で、一定、転居費用のこういったものをやっているというのを一緒にアピールしていくというふうに考えているところです。今後も引き続き、子育て世帯への住まいの支援というところは、引き続き検討してまいりたいと考えています。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"もしあったら、聞き漏らしたので、どういう開始式か、日時、場所、内容などを確認させていただきたいのが１つ。「等」なので、また「そうではないのです」というところの周知も当然必要になってくるのだろうと思いますので、その辺の考え方を説明するよう求めました。","respondent":"川原住宅課長","answer":"７月１０日にバンクが開始される、午後２時から３時までの予定で、本庁舎６階の第２委員会室での開催を予定しています。内容としましては、今のところはケーブルテレビ品川に入ってきていただいて、いろいろ取材を行っていただくといったことを予定しています。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"メディアも取材に来られるので、そういう、見せ方と言うと変ですかね。区民がどう受け取るかというのもあるので、ぜひ今からでも考慮できるのであれば、検討していただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"塚本委員","kind":"確認","question":"例えば５年住む予定などというのは、５年後どうだったのですかというところまで、それはそれとして申請順なのだというところの確認です。窓口は結構、大変かなというのもあるのですけれども、その辺の懸念から確認したいと求めました。","respondent":"川原住宅課長","answer":"ただ、７月１日から開始予定ですので、当然、電子申請のオープンの時間も、窓口の開始時間にも合わせたいと考えています。区民の方は皆様初めて、そういったところでは、どちらかが早いというところがないように心がけたいと考えています。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"住宅購入費や家賃の高騰がある中で、その傾向や、あと低家賃の住宅供給がどれだけあるのかというのが分かる資料があったらいいなと思います。バス事業者への支援がどういうことができるのかということで、議論が深まるのかなと思いますので、要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"学識経験者が５人ぐらいいましたか、どういう位置づけというか、それはどうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"塚本委員","kind":"意見","question":"そうですね。その辺がどういうふうに受け止められているのかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問","question":"今、説明を聞いて、本当にボリュームが、前期もそうですが今期も、まちづくり・公共交通推進特別委員会は非常にボリュームがあるということで、資料も含めて、また事務局を通じて提出するというやり方か尋ねました。","respondent":"石田（ち）委員長","answer":"ただいま頂きました意見と併せて、正副委員長で十分調整させていただいて、可能な限り、今後の委員会運営に活かしてまいりたいと考えています。","id":"exchange-020"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.10ma.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":25,"characters":30999,"voices":93}},{"id":"r08-20260612-10","meetingId":"r08-m06","date":"2026年6月12日","dateIso":"2026-06-12","committee":"議会運営委員会","time":"午後１時00分～午後１時17分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２番目の報告のところで、一般質問の原稿のところなのですが、かなり最後の最後まで原稿を推敲するという。努力はしますが、議長に相談することもあろうかと思いますが、柔軟に対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001","title":"一般質問原稿の差し替え"},{"speaker":"西本委員","kind":"質問","question":"議員研修の亀井会長のほうは所要１時間という形でよろしいのか尋ねました。","respondent":"渡辺議長","answer":"１時間です。","id":"exchange-002","title":"議員研修会の内容と所要時間"},{"speaker":"西本委員","kind":"意見","question":"できれば、大井町トラックスの件については、この間、高輪ゲートウェイシティとか、いろいろ東日本のＪＲのほうでまちづくりという形で何かやっていると思うのですが、そこの全体像というか、それをおさらいも含めてやってもらいたいとの意見を述べました。","respondent":"渡辺議長","answer":"テーマ的には品川圏という感じですかね。","id":"exchange-003","title":"議員研修会の内容"},{"speaker":"西本委員","kind":"意見","question":"その中で、かなり違いを鮮明に出していると思うのです。さらに品川区のよさというものを踏まえた上で議論ができるとありがたいと思っているので、そこも含めて全体の流れもぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004","title":"議員研修会の内容"},{"speaker":"西村委員","kind":"質問・要望","question":"議員バッジの仕様の変更についてなのですけれども、経費負担の軽減等のために、議員バッジの仕様の変更についてと。ぜひ進めていただいて、検討していただきたいと思うのですが、その辺はいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005","title":"議員バッジの仕様見直し"},{"speaker":"西本委員","kind":"質問","question":"内容を少し教えていただいてもよろしいですか。すみません、意味が分からなくて。","respondent":"渡辺議長","answer":"議長会では、ちなみに紹介すると、各区で見直しを検討しようという機運が高まっていました。正副委員長とも相談しながら、前向きに検討していい案件かと。","id":"exchange-006","title":"議員バッジの仕様見直し"},{"speaker":"西本委員","kind":"質問","question":"現状を教えてほしいのですが、改選期の後、議員バッジを頂くことになると思うのです。いろいろ選択肢があって、ただ、今のお話はどこの時点の話をされているのかと。","respondent":"渡辺議長","answer":"今、西本委員おっしゃられるように、個々の実費弁償は自由でいいと思うと、今お話を聞いていて感じています。ですから、一番は私たちがすべきことは、改選の後、議会費で購入するものはなるべく価格を抑えるスタイルがいいのかという捉え方です。","id":"exchange-007","title":"議員バッジの仕様見直し"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.12gu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":8,"characters":5875,"voices":41}},{"id":"r08-20260624-10","meetingId":"r08-m0708","date":"2026年6月24日","dateIso":"2026-06-24","committee":"議会運営委員会","time":"午前10時30分～午前11時00分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"令和８年第２回定例会","agenda":"令和８年第２回定例会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"請願・陳情の件なのですけれども、陳情第２７号の付託先の委員会は総務委員会ということですけれども、介護制度の中身に踏み込んだ審査も必要なこともあるかと思いますので、介護制度の担当課の理事者の出席を求めるなど、運営上の配慮が必要なのではないかと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"区民と議会の交流会議からの報告事項","agenda":"区民と議会の交流会議からの報告事項","exchanges":[{"speaker":"こんの副委員長","kind":"質問・要望","question":"実施後のアンケート結果から、生徒の政治や社会への関心の高まりなど、一定の効果が確認された。これは、後日また改めてお願いをしたいと思いますが、全体で約１０名の議員をお願いしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"開催に至るまでの経緯を簡単に改めて教えていただきたいということと、せめて３０分ほどは延長してはいかがかなと思うのですけれども、こちらは検討していただければなと思っているのですがという意見です。","respondent":"渡辺議長","answer":"これはもう世代問わずなのですが、その１つの実行プランとお考えになっていただければと思います。今やはり安藤委員の指摘で、若干の幅は持たせたいと、今のご質疑も踏まえて検討していきたいと思います。","id":"exchange-003"},{"speaker":"つる委員","kind":"質問","question":"今年度から月２回になって、１日号と１５日号。編集関係でいろいろその辺、説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"つる委員","kind":"質問","question":"チラシなどを作るのかということも併せて説明を求めました。","respondent":"大澤区議会事務局長","answer":"広報しながわは、７月１日号に囲み記事で載ります。改めてチラシの配布はないですけれども、もし必要でしたら、データがあるので、事務局のほうにお声がけくだされば印刷は可能ですので、お願いします。","id":"exchange-005"},{"speaker":"つる委員","kind":"意見","question":"議会だよりは全戸配布していただくわけですけれども、少しでも確実に手元に届く仕組みではいいかなと。ぜひ議会側の取組としても、確実に届くように、お願いをぜひしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"田中委員","kind":"確認","question":"確認だけしたいのですが、大変我々も新たな視点、考えをしっかり確認できたということで有意義だったと思っています。増村先生のお話を踏まえてということなのですが、そこは我々の思いも踏まえて対応してもいいということなのかどうか、確認だけ。","respondent":"渡辺議長","answer":"説明がすごく上手だったので、要は、議会側を守る立場の発言も多々あったかと思います。とにかく議会改革推進会議に委ねる部分が結構あるかと思いますので、逆にお願いしたいなと思いました。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"視点があって、ああいう機会を設けていただいて、大変よかったと思っています。伺うようなことは、いいとか悪いとか言えるのかどうか分からないですけれども、可能なのか尋ねました。","respondent":"渡辺議長","answer":"当然ながら、今、立ち位置が議会アドバイザーということで正式に依頼をしているので、やはりそういう場が増えることが一番有意義だと考えています。手続上は、また経費のこともありますが、事務局とともに前向きに捉えていきたいと考えています。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"多分、答えを求めてしまう場合もあるのですよね。ほかの弁護士はどうですかというのは難しいかと思いますけれども、ぜひそういうことも検討に入れてほしいと求めました。","respondent":"渡辺議長","answer":"ただ、議会アドバイザーにご就任いただいている方だったので、そういう意味がまず１つあります。全体については、また機を見てということですが、まず当面は、それぞれの会議体で調整をいただくことがベストかなというのが見解です。","id":"exchange-009"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.24gu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":11,"characters":10102,"voices":43}},{"id":"r08-20260629-6","meetingId":"r08-m0708","date":"2026年6月29日","dateIso":"2026-06-29","committee":"区民委員会","time":"午前10時00分～午前11時54分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"令和８年陳情第２２号、自衛官募集事務に係る個人情報提供","agenda":"令和８年陳情第２２号、自衛官募集事務に係る個人情報提供","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"私、住民基本台帳の閲覧を経験したことがありませんので、少し一般論として、このやり方についてお聞きしたいと思います。区民の方がこの閲覧をしたいと思った場合には、どのような手続で、そして、この閲覧がどのような形でできるのか、教えてほしいと求めました。","respondent":"築山戸籍住民課長","answer":"まず１つは、もう１つが、閲覧できる場合はかなり限定的です。こういった手続を踏まえ、区の窓口で専用の閲覧ブースがありますので、そこで閲覧していただくという形を取っているところです。","id":"exchange-001"},{"speaker":"大倉委員","kind":"質問・要望","question":"理由としては、今ご説明いただいたとおり、事前通知というところでは、セットになっている。２番のところもやっていないということ、３番のオンラインについても、不採択にさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"まつざわ委員","kind":"意見","question":"結論を出すで、不採択です。２、３もそうですけれども、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"せらく委員","kind":"意見","question":"ご説明もいただきました。除外申請もそのため制度がないということでしたので、今回、こちらの陳情については不採択という判断をいたしましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問","question":"もしお子さんご本人ですとか保護者の方からのお問合せがあった際には、丁寧なご対応をお願いいたします。今後も、住民基本台帳法の事務として、適切な取扱いをお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"令和８年度防犯支援事業","agenda":"令和８年度防犯支援事業","exchanges":[{"speaker":"まつざわ委員","kind":"質問","question":"防犯カメラの町会の助成、これは本当にありがたいと思っていて、２４分の ２３、本当にぜひ継続していってほしいと思っています。地域は忘れてしまったのですけれども、最近もあったのですが、あれで私がすごく気になるのが、下見というのが非常に出てくるではないか尋ねました。","respondent":"澤邉生活安全担当課長","answer":"しかしながら、なかなか広い地域ですので、警察単独ではそこのところを把握することはできないと考えています。こういった今回の防犯カメラというのは、地域の皆様と警察とで手を合わせて、そういったことの対策ということをやっていけるのかと考えています。","id":"exchange-006"},{"speaker":"まつざわ委員","kind":"質問","question":"下見もするわけですから、それにはやはり地域と消防と警察と一緒に一体化できる、そういった共有のプラットフォームが絶対必要だと思っているのです。何回も質問しているのですが、情報共有の体制というのは絶対にやる必要があると思うのですけれども、そこを説明するよう求めました。","respondent":"澤邉生活安全担当課長","answer":"地域の方々と警察との連携という部分ですけれども、警察署協議会ということで、地域の方々と警察署の幹部とで意見交換をする場があります。いろいろな地域、いろいろな階層の方々が情報を入手して、それを犯罪の抑止ということに役立てていきたいと考えております。","id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"それをぜひこれからの検討に活かしていただきたいというのが１点と、例えば、１００万円をまず払わなければいけないのです。３万円が出せないから大変だから、そういったお金の配慮というのもあっていいのかと思うのですけれども、いかがか尋ねました。","respondent":"澤邉生活安全担当課長","answer":"上限が２０万円ということになっておりますので、窓口ではそのようなことで区民の皆様にご説明をさせていただいているところです。ですので、我々としてはきちんと東京都と協力しながら、区民の皆様の防犯力向上を図ってまいりたいと考えています。","id":"exchange-008"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"大変すばらしいと思うので、ぜひやってほしいと求めました。東京都が来年はやらなそうな感じをしているので、またこれでお金が減ってしまうと思うので、ぜひ品川区はやめずに継続していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"今も要望がありましたとおり、今後の品川区の考え方を少し教えてほしいと求めました。なかなかそこでどう声を上げていくのかということもあろうかと思うので、今後、もう少し教えてほしいと求めました。","respondent":"澤邉生活安全担当課長","answer":"来年度、都の方針についてはまだ確定はしておりませんが、区としては、その方向性については注視してまいりたいと思います。いろいろな教育関係のところの部署と連携しまして、こういった講習会というのを今計画していますので、よろしくお願いいたします。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問","question":"詐欺メールもすごく多いのですけれども、本当に注意していても分からないのです。実は詐欺に遭ってしまったのだというお話を伺ったのですが、自分が詐欺に遭ってしまったというお話を伺って、本当にひどいと思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"せらく委員","kind":"質問","question":"防犯対策ミラーについてお聞きしていきたいと思うのですが、区として６００枚購入するというご説明があったと思います。例えば公共施設内なのか、それとも、民間の施設にも貼っていくのかというところもお聞かせほしいと求めました。","respondent":"澤邉生活安全担当課長","answer":"共連れ対策のシールミラーは、これは１,０００枚を予定しております。この夏が始まる前にぜひとも警察と連携して、駅、そういったところの設置を急いで対策を取ってまいりたいと考えております。","id":"exchange-012"},{"speaker":"横山委員","kind":"確認","question":"私からも、具体的にどういった場所の被害が多いのかというところと、どういった部分に設置していく予定なのかというところを確認させてください。その後どういう行動をしたらいいかというのがまだ分からない方、設置されている建物の所有者や管理者の方など、説明を求めました。","respondent":"澤邉生活安全担当課長","answer":"委員ご指摘のとおり、オートロックのエントランスやエレベーター、こういったところに設置というのを検討しております。やはり公共の場所的なところの設置が多いかと思いますけれども、どちらかというと私有地の中というところが検討されるかと思います。","id":"exchange-013"},{"speaker":"横山委員","kind":"確認","question":"１,２８３件だったと思うのですけれども、今年に関しては何件ぐらいを想定されているのでしょうか。多くの方にご利用いただきたいという意図があるのか、どういった形で分析がされているのか、確認したいと求めました。","respondent":"澤邉生活安全担当課長","answer":"これまでも、２年目となりますけれども、非常に反応が、反響が大きくて、申請も多く受け付けているところです。今後ともこの制度、非常に補助率も高いので、区民の皆様に引き続き周知してまいりたいと思っています。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"いろいろご説明いただいたので、少しだけ確認を。情報を使ってやっていくほうが、より周知と設置が進むのではないかと思いますので、その辺について教えてほしいと求めました。","respondent":"澤邉生活安全担当課長","answer":"ただいま品川区では、品川警察署と連携しまして、この特殊加工されたミラーを多発地区に先行して設置をしています。３点目の周知方法ですけれども、設置必要な場所であれば、区全体で防犯力の向上というのを図ってまいりたいと考えています。","id":"exchange-015"},{"speaker":"大倉委員","kind":"意見","question":"分かりました。共連れ対策のほうなどもなかなかどうやって効果を計っていくのかというのが少し気になったところであったので、ぜひ進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"まつざわ委員","kind":"質問","question":"簡単ですごく分かりやすくていいと思ったのと、あと、こういった防犯の設置もそうなのですけれども、集合住宅が入ったではないですか。これだけ安くするからどうですかとか、マンション自体のパッケージで売り込むというのか、申請させるというのですかね。","respondent":"澤邉生活安全担当課長","answer":"そのマンション、まさに委員ご指摘のとおり、パッケージとしてのマンション全体としての防犯力の向上というのが図れるのかと思っています。区としましては、ベストプラクティスといいますか、そういった成功事例についても、併せてこの事業について周知してまいりたいと思います。","id":"exchange-017"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"本当にいい、本当にすばらしい助成金だと思うので、ぜひ知らせて、また拡充して、みんなで使ってほしいと求めました。それだけ説明を求めました。","respondent":"澤邉生活安全担当課長","answer":"窓口に来ていただくような形になりますけれども、なかなか品川区も広うありますので、区に来られないという方もいらっしゃると思います。","id":"exchange-018"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そういうのを、例えば、高齢者福祉でもスマートフォンのお勉強会みたいなのがあるではないですか。携帯電話の対応の仕方、そういったのも並行してやっていく必要があるのではないかと思うのですけれども、そこら辺はいかがか尋ねました。","respondent":"澤邉生活安全担当課長","answer":"各警察署と連携しまして、そういったところにもこちらのほうから部局と連携して行きまして、自動通話録音機の話をしています。一部警察署によりますと、高齢者の方がこれを設置ができないといったときに、ご自宅まで行って設置をするということもやっていると聞いております。","id":"exchange-019"}]},{"id":"topic-03","title":"スポーツ×エンタメ 多彩カイギの実施","agenda":"スポーツ×エンタメ 多彩カイギの実施","exchanges":[{"speaker":"まつざわ委員","kind":"質問・要望","question":"化学反応ではないですけれども、ぜひスタートアップのそういったものと一緒にやっていくみたいな、何かそういう人選というのですかね。そういうのも、決まったことかもしれないですけれども、ぜひ念頭に入れていただけたらと思っています。","respondent":"大森文化観光戦略課長","answer":"１回目ということで、１４団体ぐらいの方々ということで、そこから枝葉を広げていきたいと考えています。そういった中で、こちらの会議がもっと広く浸透していくということにつながればいいと思っていますので、頑張ってまいりたいと思います。","id":"exchange-020"},{"speaker":"新妻委員","kind":"質問・要望","question":"この１４団体の団体名をご紹介いただきたいというところと、年に２回これを開催して、どういう形に持っていくのか。何かイベントを開催することが目的になっていくのか、区民の方がどのようにここに関わっていけるのか、少し教えてほしいと求めました。","respondent":"大森文化観光戦略課長","answer":"そこに区としてどういう支援ができていくのかというところで、幾つかイベントが出来上がるということが実現すればいいと思っているところです。地域の方々をいい意味で一緒に歩んでいけるような形で、今後、どういったことができるかというのを考えていきたいと思います。","id":"exchange-021"},{"speaker":"新妻委員","kind":"質問・要望","question":"なかなかそれはまだこれから、第１回しか開催をされていないようなので、大きくいろいろな分野でのまた展開を進めてほしいと求めました。では、ご答弁いただければ。","respondent":"大森文化観光戦略課長","answer":"そのときはスポー ツと、あと、ちょっとしたアート的な文化的なことのブースを出されていたのです。なので、今回はインクルーシブスポーツという分野の代表ということでお声がけをさせていただいているところです。","id":"exchange-022"},{"speaker":"大倉委員","kind":"確認","question":"そこが確認できればと思うのと、いろいろなさらにＤＸとか、ぜひ声はかけて広く取っていったほうがいいのではないかと。今、お話を聞いていて、伺いました。","respondent":"大森文化観光戦略課長","answer":"絞っていったところ、１４団体全ての方たちが出ていただけるという形になったので、非常にありがたいと思っているところです。ＰＲしていける場になればいいのかと思ったので、まずは大きなことをやっている方たちを今回あえて集めたというようなところになります。","id":"exchange-023"},{"speaker":"大倉委員","kind":"意見","question":"ぜひ団体の数が１４と今おっしゃっていたので、今後広がっていければいいかと思っていまますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"例えば、団体として区に要望を上げていく力であったり、一つの要望みたいなところが立てにくいみたいなところの特殊性もあるので。さらに交流が活発になっていくのかと私は思っていますので、これは要望で終わらせていただきたいと思うのですが、一言お願いします。","respondent":"大森文化観光戦略課長","answer":"今、ファシリテーターをどうするかというところは、結構、確かにというか、 すごく刺さりました。全体のファシリテーターを考えていくというのは確かにあるのかというところと、小さな事業所の方、こちらで尽力しながら進めてまいりたいと思います。","id":"exchange-025"},{"speaker":"新妻委員","kind":"質問・要望","question":"すみません、長時間になっている中で。そういう方たちも今後またぜひお声がけをいただきたいというところとか、また次の段階としてそういう方にもぜひお声がけをいただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-04","title":"令和８年度文化センター他工事等による休室・休館予定","agenda":"令和８年度文化センター他工事等による休室・休館予定","exchanges":[{"speaker":"まつざわ委員","kind":"意見","question":"いろいろあると思うのですけれども、荏原文化センターにも関わってくるのですが、そういった分割工事というのですかね。そうですよねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"まつざわ委員","kind":"質問","question":"そういう工事もいろいろあって、工期もあって、例えば今回、改修がメインですから、やらなければいけない工事なのかと考えています。何かそういった措置があってもいいのかと思っているのが１点と、あと、荏原文化センターは駐車場が使えないのか尋ねました。","respondent":"大森文化観光戦略課長","answer":"そうです。","id":"exchange-028"},{"speaker":"まつざわ委員","kind":"質問","question":"半年、利用できないというと、どうなるのか。駐車場が半年ないところの、そういった部分での気の遣い方というのはあってもいいのかと思っていますが、どうか尋ねました。","respondent":"大森文化観光戦略課長","answer":"こういうところがありますという形で、区の施設も当然あるのですけれども、なかなか音楽ホールは難しいと。工事のほうとも連携しまして、表のお客様が各団体１台でというような、現地の施設整備課とも相談しながら進めていければと考えています。","id":"exchange-029"},{"speaker":"まつざわ委員","kind":"質問","question":"そうすると、例えば小規模の改修をしている、例えば大きな金額というのはある程度積算で出るわけではないですか。どこかで大規模改修というのは、品川区の考え方として絶対に持っていかなければいけないのかと思っていますので、意見として言わせていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"新妻委員","kind":"質問","question":"こんな活用の仕方ができるのですかというところなのですが、今、音がするために貸出しができないというお話がありました。ピアノの体験をされているケースがあると思いますが、例えば、こういう機会にそういう活用の仕方というのはどうなのか尋ねました。","respondent":"大森文化観光戦略課長","answer":"施設のほうと連携しまして、音楽ホールを貸して事業的にやるという話になると、難しくなってしまうかという。なるべくそういった使える機会には開けていくような形は考えていきたいと思います。","id":"exchange-031"}]},{"id":"topic-05","title":"夏季屋外プールの開放","agenda":"夏季屋外プールの開放","exchanges":[{"speaker":"新妻委員","kind":"確認","question":"１点だけ確認します。５校ということなのですけれども、もともと５校だったのか、利用状況も含めて現状をお聞きしたいと思います。","respondent":"山下スポーツ推進課長","answer":"実施校ですけれども、私どものほうも、せめて一部でいいので実施していただけないかということで協議させていただいていたのですけれども。７月の水泳の授業が終了した場合は、そういう事情もあって、協力できるところが少なくなっていることなのかと考えております。","id":"exchange-032"},{"speaker":"新妻委員","kind":"確認","question":"もっと過去は多かったのではないかという印象がありましたので、確認をさせていただきました。これ以上減ることがないように、また教育委員会部門との連携も協力も要請をしていただきながら、維持をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"まつざわ委員","kind":"質問","question":"何かそういったきっかけの一つにしてほしいと私も思っているので、区民プールは、今５００人の予約制ではないですか。予約で５００人が入るとして、それで １日５０人だとするとして、おなかが痛くなってしまう子とかもいるではないか尋ねました。","respondent":"山下スポーツ推進課長","answer":"ですので、今後も部活動の地域移行に関しましては展開があるかと思いますので、必要に応じて教育委員会と協議してまいりたいと思います。キャンセルに関しましては、取りあえずこちら、夏季限定でやっておりますので、キャンセル機能は特にないかと思います。","id":"exchange-034"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"キャンセルのやり方というのもいずれ検討していただきたいのと、やってもらいたいですから、ぜひお願いします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問・要望","question":"私からは、学校プールについて、先ほどからも出ていましたが、少し聞いておきたいと思います。先ほど利用者数についてもしかしたら質問されていたと思うのですが、そういった実態をもし把握されていれば、教えてほしいと求めました。","respondent":"山下スポーツ推進課長","answer":"利用者数ですけれども、令和５年が約１,６００人、令和６年と７年が約１,３００人で推移しています。申し訳ございません。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"学校プールの一般開放時には、どのような職種のスタッフの方が何名程度配置されているのかというのを把握されていたら教えてください。安全管理体制というところでお聞きしたいと思います。","respondent":"山下スポーツ推進課長","answer":"衛生の講習会ですとか、必要な講習会を毎年行って、それを受けていただいた方にお願いをしています。１つのプールに関しまして、申し訳ございません、人数までは分からないのですけれども、そのような形で二重の体制で開放は行ってあります。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問","question":"状況を教えてくださって、ありがとうあります。今回は学校が１校減ってしまったということですが、計画して、区民の皆さんの余暇の充実というところを引き続きお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.29ku.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":30,"characters":37293,"voices":106}},{"id":"r08-20260629-7","meetingId":"r08-m0708","date":"2026年6月29日","dateIso":"2026-06-29","committee":"厚生委員会","time":"午前10時00分～午後４時38分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を103件整理しています。","topics":[{"id":"topic-01","title":"第６４号議案、品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第６４号議案、品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうことで介護保険料が１０万円増えた人も上がらなくて済むという措置で、これは区民にとってはとてもプラスなので賛成するものです。教えていただきたいのが、介護保険段階では何段階の人が対象になるのか、その２点を教えてほしいと求めました。","respondent":"佐藤高齢者福祉課長","answer":"本番の計算ですと若干ずれるかもしれませんが、２５０人程度になります。こちらにつきましては、みなしでそちらになることが２から４の本人非課税に戻るといいますか、減免されるというのが今回の内容になります。","id":"exchange-001"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今回のこういったことに関して、何かホームページとかで周知は区でお考えか尋ねました。","respondent":"佐藤高齢者福祉課長","answer":"７月になりましたら、お問合せがありましたら、丁寧にご説明したいと考えております。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"確認","question":"なぜ３２８万円なのか、計算の仕方ですか、そこら辺をもう少し分かるように教えていただけたらと思います。地域包括支援センターのサブセンターと居宅介護支援事業所という２つの事業を行っていると思うのですけれども、現在、教えていただけたらと思います。","respondent":"佐藤高齢者福祉課長","answer":"例えば在宅介護支援センターですと、少ないところですと８万円、多いところですと２２万円で差があります。品川区の在宅介護支援センターの中で、直接、在宅介護支援センターから東京都に申請する仕組みとなっております。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１.９５％ということで、では２.０３％は今回は関係ないのか、教えていただきたい。このことによってどの程度賃上げになるのか、あったら、そこら辺の賃上げの額とかも、想定されるものがあったら説明を求めました。","respondent":"佐藤高齢者福祉課長","answer":"在宅介護支援センターは、それもそれぞれ事業所ごとに人数は違いますが、おおよそ月に７,０００円ずつ分配があるような形になっております。その原資にする趣旨で補助金が出ている、あるいは介護報酬が上がっているとご理解いただければと思います。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"意見","question":"賃上げという点では、７,０００円だけだととても足りなくて、厚生労働省のつい最近の発表でも８万２,０００円の差があるという発表でした。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"やなぎさわ委員","kind":"質問","question":"少しお伺いしたいのですが、それに比べて月に７,０００円というのは、この差額分はどのように考えたらいいか尋ねました。","respondent":"佐藤高齢者福祉課長","answer":"特に居宅介護支援事業所、今回につきましては、いわゆる基準月の報酬に概算で１５％を掛けて出されているのも１つあると考えております。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういう方たちへも分配されると考えてよいのでしょうか。マネジメント的なお仕事の方たちにはそういう支援があまりないとご要望をいただいているので、その方たちにも、伺いたいと思います。","respondent":"佐藤高齢者福祉課長","answer":"賃上げの介護報酬の改定についてのご質問と思います。介護職員のみならず、趣旨としましては、広く事業者に対して賃上げをしてくださいという形での報酬改定がされたとご理解いただければと思います。","id":"exchange-007"},{"speaker":"若林委員","kind":"質問","question":"さっき７,０００円と数字が出てきていましたが、７,０００円のうち、合わせて平均して７,０００円です。そこも含めて、今の私の表現の仕方に対して、何か国が考えていることはどういうことなのか尋ねました。","respondent":"佐藤高齢者福祉課長","answer":"こちら、それに基づいて今回の補助金を計算して支給されておりまして、どのぐらいを賃上げに回すかはそれぞれの事業所のところだと思います。","id":"exchange-008"},{"speaker":"若林委員","kind":"確認","question":"押し並べて１人、一般的なヘルパーも含めた職員の方に平均で７,０００円上乗せされるという、そういうざくっとした言い方はあまり適切ではない。一応そこは数字で、また言い方もありますので、そこは確認したいと求めました。","respondent":"佐藤高齢者福祉課長","answer":"失礼いたしました。補助金を単純に割り返すというご説明でしたけれども、今回の趣旨としましては、今後も表現については注意していきたいと考えています。","id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問","question":"高齢者スマートフォン購入支援について伺います。どういうものの購入を想定してこの補助額なのか説明を求めました。","respondent":"樺島高齢者地域支援課長","answer":"中には３万円の上限の中で買える機種もあるとは思いますので、３万円を超えた場合には、その超過分は自己負担になります。１人につき１台３万円までを補助するという形で今回はするものになります。","id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問","question":"力の入れ具合も変わってくると思うので、まずその辺をどう、品川区自体は他の施策も含めた中で把握されているか。それとは別で、今回、補助金申請審査事業委託で、審査事業は、どういうところを想定して、どういう内容なのかも説明を求めました。","respondent":"樺島高齢者地域支援課長","answer":"それにおきまして、そこからのスマートフォン不保持率を算出したおおよそのシミュレーションとしては、１万８,０００人ぐらいいるという結果です。最終的に今回、区としましては、助成対象人数としては２００人ぐらいを想定しております。","id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問","question":"すみません、今の１.８万人というのは不保持率か尋ねました。","respondent":"樺島高齢者地域支援課長","answer":"今のは不保持率、持っていない方の率が、以前試算した際には １万８,０００人ぐらいいるだろうというところから、この事業を検討しております。これにつきましては、区民の方から申請いただいた申請書のチェック、その部分を委託するということで、この予算で計上しています。","id":"exchange-012"},{"speaker":"渡辺委員","kind":"質問・要望","question":"本当に３時間や５時間かかる。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"若林委員","kind":"確認","question":"助成金は２００人で決まってくるのですが、それに対してこの委託事業の６００万円余の中身をまず確認したほうがいいですね。お願いします。","respondent":"樺島高齢者地域支援課長","answer":"内容が、申請審査および事務処理を適切に効率的に実施するため、ある程度専門的な業務を委託する内容となっております。併せてもろもろの事務費、諸経費を計上しておりますが、大半は人件費になっております。","id":"exchange-014"},{"speaker":"若林委員","kind":"確認","question":"そこは確認、幾ら安いのがあるといっても、そこで買ってしまうといわゆるこの流れには乗っからない。例えばスマホよろず相談とか地域センターに改めて行って、要するに自分では申請できないわけですから。","respondent":"樺島高齢者地域支援課長","answer":"ふだんショップに行って、ショップの店員と１対１ の場合が多いと思いますけれども、いろいろな説明を受けることが多々あると思います。それも基本的にはスマホ教室とみなしまして、それはキャリア問わず実施するものになっております。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"６５歳以上でスマートフォンを所有していない方が対象ですけれども、６５歳ぐらいの方はもうかなりスマートフォンを所持していらっしゃると思います。１万８,０００人の不保持者がいらっしゃるということですけれども、８０代とか、不保持者の年齢別の把握とかはされていますか尋ねました。","respondent":"樺島高齢者地域支援課長","answer":"先ほど１万８,０００人ぐらいと全体の数をお示しした中では、恐らく１万人近くは８０歳以上の方が対象であろうと想定しています。７０歳から７９歳の方でも一定の数はいると思いますが、圧倒的に多いのは８０歳以上の方であろうと、我々の認識として持っております。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問・要望","question":"もう１点質問で、なぜ今まで不所持だったのか、理由の分析も必要だと思います。毎月のお金がかかってくると理解していただくのがいいと思いますが、その点、いかがお考えか尋ねました。","respondent":"樺島高齢者地域支援課長","answer":"特に高齢者の方ですと、やはりいろいろな部分をきちんと説明するのが必要と思います。そこの事前の購入時の丁寧な説明は、今回の事業におきまして、各ショップ・各キャリアにしっかり求めていきたいと考えています。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問・要望","question":"あまり後ろ向きなことを言ってもしようがないのですけれども、ぜひ今回、きっかけとしてデジタルデバイドの解消を進めてほしいと求めました。予算書で、一般財源がマイナス１,７００万円になっているのですが、一般財源は持ち出ししなくていいからマイナスにしたということでいいか尋ねました。","respondent":"芝野障害者支援課長","answer":"日中一時支援は、もともとございました国の地域生活支援事業費等補助金を活用する。合わせて１,７００万円の一般財源の削減につながってあります。","id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問","question":"この事業を品川区でどうやって昇華させるのか、１つ、渋谷区が以前行った高齢者向けのデジタルデバイド解消事業が参考になると思っています。今ご紹介しました渋谷区の事例とかを踏まえて、何かお考えのことはありますか尋ねました。","respondent":"樺島高齢者地域支援課長","answer":"区におきましては、先ほど委員のご紹介もありましたとおり、スマホよろず相談、スマホ体験教室、こういった事業を数年前から実施しています。","id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"提案","question":"これは提案ですけれども、加算ではないけれども、助成金をつける。我々でもできることではあるので、ぜひそういったことも検討していただきたいと思うのですが、いかがか尋ねました。","respondent":"樺島高齢者地域支援課長、菅野福祉部長","answer":"ただ、現在、そういった方でも既にスマホを持っていらっしゃる方への支援は、介護職員の方がふだんからやられていると我々も認識しています。ただ、そういったところへさらに支援が可能かは、今後検証しなければならないと思います。予算額が３億６,５００万円だったので、品川区では当時、今あったスマホはじめて教室やスマホよろず相談などの事業を展開していた経過があります。","id":"exchange-020"},{"speaker":"やなぎさわ委員","kind":"意見","question":"同じようなスキームでやってほしいのではなくて、そういったものが大事だと出てきているので、これをどのように品川区で活かしていくかをご検討いただければですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２００人を超えた場合は、それとも先着２００名で切ってしまうのか、教えていただきたい。住民票で購入できるのかを確認させていただきたいのと、確認させていただいて、その点について伺います。","respondent":"樺島高齢者地域支援課長","answer":"定かではございませんが、住所の確認で、いわゆる本人確認の１つに当たると考えております。マイナンバーカードがなければスマートフォンを購入できないものではないと認識しております。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そんなことないはずと言ったのですけれども、そこら辺は、お店に今回こういう３万円の助成がつきますと周知していただくようになると思うのです。それからマイナンバーカードがない人にも、住民票でできますという周知もぜひしてほしいと求めましたが、いかがか尋ねました。","respondent":"樺島高齢者地域支援課長","answer":"ただそれは、電子申請という行為そのものへのハードルの高さは一定程度あると思いますので、そこをショップのスタッフの方と一緒に進めていく。ショップが申請するのではなくて、あくまでも本人が申請するとなっております。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問・要望","question":"補助率が東京都４分の３の助成なので、品川区は４分の１の負担でよくなったのか、その点についても確認させてください。それから、生活介護延長受入事業所と日中一時の延長受入れの施設数と、１施設当たりの受入れ人数をそれぞれ教えてほしいと求めました。","respondent":"芝野障害者支援課長","answer":"３つ目の生活介護と日中一時支援の受入れの状況ですが、職員体制とかその辺もしっかりと検討しなければいけない中で、二名の受入れや。日中一時支援はこれからの話ですので、民間事業所、できるだけ受入れをしていただけるように働きかけを行ってまいりたいと考えています。","id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問","question":"合わせて１日２５人くらいで、それは１０人受け入れるところもあれば１人のところもあって、トータルでそのようになると考えていいのか伺いたいです。日中一時は３か所だと思うのですが、これは何で６か所と５か所となっているのか、ここの箇所数の試算理由も伺います。","respondent":"芝野障害者支援課長","answer":"専門職加算ですが、現在、生活介護の８事業所で体制がとれていますので、その中でこの事業に携われる方がいらっしゃいましたら、加算対象になります。生活介護と日中一時支援の数の話ですが、この事業を開始するに当たって、この予算の算定になってあります。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、今、にじのひろば２か所とぐるっぽの３か所だと思うのですけれども、それがさらに増える可能性があると考えていいのか、その確認だけお願いします。","respondent":"芝野障害者支援課長","answer":"そうですね、お話をさせていただいている例えば就労継続支援Ｂ型の事業所とか、いろいろな事業所があるのですが、今の３か所以上に増える可能性はあります。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問","question":"この増額分は全額東京都から来るのか、改めて伺います。それから、３倍に値上げした基準、額の３倍は、なぜ３倍になったのか、東京都は何と説明しているのかも伺います。","respondent":"宮澤福祉計画課長","answer":"それらの相談や支援に対応していくための知識を習得していくための自己研さんにも充てていただきたいというものになっております。そういった中で、各地区民生委員協議会で施設見学の研修をしているなど、それぞれの民生委員の方々の活動で研修を実施していると伺っております。","id":"exchange-027"},{"speaker":"鈴木委員","kind":"意見","question":"今の３万円でもボランティアという状況だとは思うのですけれども、そういう点では、より充実させていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"質問","question":"民生委員の件、続きですみません、お聞きしたいのですけれども、民生・児童委員、定数が３２５名で、実際に３０８名と書かれて、差の１７名は、要は欠員、足りていないという認識でよろしいのか尋ねました。","respondent":"宮澤福祉計画課長","answer":"民生・児童委員の定数は、記載のとおり、３２５名で、この３０８という数字は、予算上の数字になっています。実際に活動されている実人数になりますと、最新ですと、６月現在で２７６名、つまり、 その差に関しては、欠員が生じてあります。","id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"確認","question":"実数でいうと、思った以上に足りていないと実感しました。確認ですけれども、そういったかかった費用に対して支払われるのか、確認です。","respondent":"宮澤福祉計画課長","answer":"民生・児童委員の活動費は、実費弁償になっております。一つ一つの領収書等で出していただくのではなくて、民生委員の活動報告というのを１人ずついただいておりますので、それで代えしています。","id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問","question":"というと、今回活動費が３万円になるのですけれども、毎月３万円は満額支払われて、ある程度、正直、多少余る分は、民生委員の活動としてあとは自由に使うような考え方でよろしいか尋ねました。","respondent":"宮澤福祉計画課長","answer":"認識としては、委員ご指摘のとおりです。そういった経費に充てられているところです。","id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"意見","question":"それを踏まえて、例えば今、実働で２７６名というお話もあって、民生委員が足りていない原因として、例えば活動費が少ないからやれないのだという声があるのか、また別の要素があるのか、その辺の区としての受け止めはどのようにお考えでいらっしゃいますかとの意見を述べました。","respondent":"宮澤福祉計画課長","answer":"その中では、協力員という形で不在地区をフォローしていただいているところもありますが、それでも不足しているのが現状です。そこら辺の原因、理由につきましては、活動費だけではなくて、推薦をいただいている町会・自治会の高齢化等も原因にあると認識しています。","id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"提案","question":"当然、今回活動費が増えるのは非常にいいことではありつつ、やはりまだまだ人員をカバーするための課題は多いと認識しましたので、これは今後の課題として、厚生委員として私も提案を考えたいと思いますけれども、区としてもそういった認識は引き続き持って取り組んでほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"吉田委員","kind":"確認","question":"ただ、これ、あくまでやはり趣旨としては、親の就労支援でいいのか、 確認が１つ。１８歳の壁で、そういうお考えはどうなのか、改めて伺います。","respondent":"芝野障害者支援課長","answer":"もう１つが、親の就労の継続支援です。こちらの２つの面でこの事業を進めていきたいと考えております。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"１８歳を超えると障害者になる、就労までいかなくても、でも一種の就労であってほしいということなのだろうと思います。働く、社会参加ということの施策もこれから進められるべきと思うのですけれども、 その点についてお考えを伺いたいと思います。","respondent":"芝野障害者支援課長","answer":"今後の日中一時支援の在り方のご質問だと思うのですが、日中一時支援、研究してまいりたいと思います。日中一時支援を何とか活用できないかと事業を始めておりますが、委員おっしゃったような課題も認識しておりますので、研究してまいりたいと思います。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは本当に強く要望しておきます。それから民生委員のこと、いいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"高齢者だけで暮らしていると、介護を社会化した２０年前の考え方の中に、やはり民生委員の待遇などもぜひ検討していただきたいと思うのです。もしお考えがあれば承りたいと思います。","respondent":"宮澤福祉計画課長","answer":"民生委員の方、今回は活動費が増額されますので、ご自身で負担されていたところはなくなるだろうという見込みであります。大変な部分はあろうかと思いますけれども、やりがい等を区民に知っていただきつつ、担い手となっていただくように啓発を進めていきたいと思ってです。","id":"exchange-037"},{"speaker":"やなぎさわ委員","kind":"意見","question":"１つ戻って、歳出が約２,５００万円で、歳入が約４,６００万円です。歳入が２,０００万円ぐらい多いのであれば、さらに単価の引上げとかサービスの拡充ができると思ってしまうのですが、その辺はいかがか尋ねました。","respondent":"芝野障害者支援課長","answer":"今回、補正予算反映後で５,７６０万円程度の予算を想定しておりますので、その差分の２,５６５万円程度を補正予算として計上しています。区の一般財源で支出する予定でしたので、１円もありませんでしたので０ 円で、区が持ち出している状況になっております。","id":"exchange-038"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それと、単独ワクチンが２５０ 人ということで予算が組まれていると書かれているのですが、これはどのように算定したのかを伺いたいと思います。それから、ワクチンの接種費用は５,０００円と３,０００円の助成ですけれども、その点についても伺えたらと思います。","respondent":"五十嵐保健予防課長","answer":"どのぐらいの方が実施されるかは正直あまり分からない部分でして、何とも言えないのですけれども、一応想定を出させていただいて。半額強ぐらいが助成する額とさせていただいていますが、任意接種ですので、医療機関によってある程度の差は出てくると考えています。","id":"exchange-039"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう人と接する機会が多いところにワクチンをより受けてほしいという、また、周知をどうしていくのかも伺いたいと思います。それから、実際にワクチンを受けたい場合は、指定の病院で抗体検査を受けたいといって受けられる仕組みになるのか、その仕組みについても伺います。","respondent":"五十嵐保健予防課長","answer":"周知については、広報とホームページ等で周知する予定にしております。実施していただける医療機関を広報やホームペー ジでお知らせさせていただいて、その後また予防接種をしていただくことで想定しています。","id":"exchange-040"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、広報やホームページとかで、ここの病院だったら抗体検査とワクチンを受けられるので、そこに行って、区に申請して抗体検査無料券をもらうとかではなくて、病院に行って直接やりたいということでできる仕組みでいいのか、確認だけ、お願いします。","respondent":"五十嵐保健予防課長","answer":"希望される方は、契約させていただいている医療機関に予約していただいて、それで行っていただければできる状況になってあります。","id":"exchange-041"},{"speaker":"若林委員","kind":"確認","question":"生活介護、日中一時支援の確認で、表がありまして、区分ごとに現行１人当たりの助成額が出ています。都は区分の５と６をフラットにしているのは、どういう意図なのでしょうかという質問、確認です。","respondent":"芝野障害者支援課長","answer":"重度の方が区分の５と６と東京都では考えておりまして、同じ金額で補助していこうという考えだろうと、同じ金額としています。","id":"exchange-042"},{"speaker":"若林委員","kind":"意見","question":"３倍となっているのですが、現場は区分の５と６でフラットなのかというのが出てくるという懸念はありますので、また注視してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"}]},{"id":"topic-02","title":"令和８年陳情第１７号、住宅宿泊 事業における「家主同居型」の営業制限緩和に関する陳情","agenda":"令和８年陳情第１７号、住宅宿泊 事業における「家主同居型」の営業制限緩和に関する陳情","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"民泊については年間１８０日という規定がありますけれども、商業地域・近隣商業地域は曜日に関係なく１８０日で、その点を伺います。私はそちらのほうが苦情が多いと思っているのですけれども、その苦情の件数も併せて伺います。","respondent":"赤木生活衛生課長","answer":"先ほどの６月１５日の数とは多少差異がありますけれども、その差引の数が現在営業している住宅数であるとご認識いただければと思います。","id":"exchange-044"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その理由が分かったら教えていただきたいのと、その苦情は、１７０件が旅館業法で管理人がいない施設が１７０件ということでよいのでしょうか。その辺の苦情の中身も教えていただきたいのと、できる前とか、そういう不安の区への相談はどのような状況があるのか伺います。","respondent":"赤木生活衛生課長","answer":"本年の３月からにはなるのですが、こちらで施設も確認をさせていただいた段階で、各町会長様宛に個別にお知らせをするような運用を開始をしています。そういった中でお知らせをすることによって、その声に少しでもお答えできればという思いで、そういった運用を開始した次第です。","id":"exchange-045"},{"speaker":"鈴木委員","kind":"質問・要望","question":"民泊は１８０日ですけれども、旅館業法は３６５日営業できるので、伺います。２４件しかないわけですから、陳情者の要望も含めて検討してもよいと思うのですけれども、その点についてもいかがか尋ねました。","respondent":"赤木生活衛生課長","answer":"旅館業につきましては、第１種住居地域ですとか住居専用地域ではできないのですけれども、住居地域であればできるところもあります。ではどうすべきかというご助言ですとかはさせていただいているとともに、可能な限り区民の方々のお立場に寄り添った対応を心がけてあります。","id":"exchange-046"},{"speaker":"鈴木委員","kind":"意見","question":"最後にもう１つ、品川区における住宅宿泊事業の実施運営に関するガイドラインがあります。それが令和６年７月２５日に最終改定になっていて、その平成３０年のガイドラインからこの令和６年の最終改定で、お聞かせいただけたらと思いますとの意見を述べました。","respondent":"赤木生活衛生課長","answer":"実際大枠の規制につきましては、あとは曜日の話であったり、そういった大枠は基本的にはその段階では変更はしていないところです。申し訳ありません、今すぐに回答が難しいですけれども、大枠については基本的には変更していないとご理解いただければと思います。","id":"exchange-047"},{"speaker":"やなぎさわ委員","kind":"質問","question":"基本的な区のお考えとしてお伺いしたいのが、家主同居型と家主不在型で、苦情は今回１５件あるうちの家主同居型はゼロ件と思うのですが、やはりこの２つのタイプによって、生じる問題は違うという認識はもともとあるのか、伺います。","respondent":"赤木生活衛生課長","answer":"先ほど冒頭の説明でも申し上げましたとおり、基本的には管理の形態を問わず適正に管理してくださいと指導徹底させるのが区の役割だと思ってあります。","id":"exchange-048"},{"speaker":"やなぎさわ委員","kind":"質問","question":"では、少し質問を変えて、今回１５件苦情があった。その辺は１年間でということで、直近の１年間だと思うのですけれども、ではもう少し広げて、３年とか５年とかの範囲で言うといかがか尋ねました。","respondent":"赤木生活衛生課長","answer":"先ほど令和７年度につきましては１５件と申し上げましたけれども、令和６年度につきましては７件、令和５年度につきましては８件です。もう一年遡りますと、令和４年度につきましては１件です。","id":"exchange-049"},{"speaker":"やなぎさわ委員","kind":"質問","question":"正直それほど民泊に対して区がいろいろ何か制限をかけるほど、重大な事態、近隣トラブルになっていないという考え方でよろしいか尋ねました。","respondent":"赤木生活衛生課長","answer":"先ほど申し上げたとおり違法民泊に関する通報が６件、あとは民泊自体に反対をされるその営業開始前の不安の声、そういったのをまとめたのが７件です。必要な規制のあり方、品川区にそぐう形のあり方については、引き続き検討をしてまいりたいと存じます。","id":"exchange-050"},{"speaker":"筒井委員","kind":"意見","question":"苦情について、令和７年度は、苦情は全体で１５件あったうち、家主同居型はゼロ件ですけれども、 これも過去この条例制定当初から見て、ずっと家主同居型は苦情がなかったのか、その状況を聞きたいですとの意見を述べました。","respondent":"赤木生活衛生課長","answer":"家主同居型に対する苦情があったかのお問合せかと存じますが、大変申し訳ありません、令和７年度の集計はさせていただいてはおったのですが、令和６年度以前に家主居住型に対する苦情があったかについては集計できておりません。","id":"exchange-051"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。２ページ目に、品川区では現在このような苦情が出ているとか、その運営の状況というのは入ってきていますか尋ねました。","respondent":"赤木生活衛生課長","answer":"６月になっての実際に報道されているものとしまして、１０月１日からの施行を目指して、条例の改正案を議会に提出しているという旨の報道があります。","id":"exchange-052"},{"speaker":"筒井委員","kind":"意見","question":"今おっしゃられた台東区でも逆に規制を強化する流れもあり、非常に何か今、民泊に対する懐疑、全体的な見直し、それが必要と思っています。当然区民からのいろいろなご意見を踏まえて、規制緩和することは、やはり一定の何かハードルがあるとお考えなのか尋ねました。","respondent":"赤木生活衛生課長","answer":"規制緩和に対する考え方です。規制を緩和することによって、我々もはかりかねる部分がありますので、現状としましては規制の緩和ということについては考えてはございません。","id":"exchange-053"},{"speaker":"筒井委員","kind":"質問","question":"ですので、今後情勢の変化もあるので、慎重に他区の状況等々を見ながら、研究・検討はしていくということでよろしいのか尋ねました。","respondent":"赤木生活衛生課長","answer":"委員のおっしゃるとおり、基本的には先ほどの繰り返しにもなりますけれども、区民であすとかその営業者の方々の様々な声を真摯に受け止めながら、品川区に合った規制のあり方についての検討は引き続き継続していきたいと考えています。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"何かその２つになってしまっていますけれども、私は年齢的に１９６４年の前の東京オリンピックを知っているのですが、それは本当によい試みだった。少し言葉の定義が私の中でぐちゃぐちゃになっているので、一回整理させていただきたいのですけれども、いかがか尋ねました。","respondent":"赤木生活衛生課長","answer":"こちらは我々の認識としましては、実際のそこのオーナーがそちらの同一施設内にいることが前提となっている業態が、家主同居型の住宅宿泊事業です。それがいわゆる家主不在型と言われている定義づけというご理解をいただければと思います。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問","question":"もう１つ、先ほどのご答弁の中で少し出てきたのですけれども、誤訪問は結構あるものなのでしょうか。こういうことがあるのだとそのときすごくびっくりしたのですけれども、何か把握されていることがあったら伺いたいのですけれども、いかがでしょう。","respondent":"赤木生活衛生課長","answer":"誤訪問に関するご質問かと存じます。誤訪問につきましては、旅館業に関することとして２件、別のお宅に入り込のでしまうといった事例はあったと区にご相談として寄せられているものです。","id":"exchange-056"},{"speaker":"吉田委員","kind":"質問","question":"たまたまかもしれませんけれども、地域の中で話しかけてこられ、ご意見を伺うときには、やはり民泊に対する苦情は結構直接伺うところです。もう少し実態を把握するようなことはできないものか、難しいのか尋ねました。","respondent":"赤木生活衛生課長","answer":"我々としては先ほど来申し上げておりますとおり、お問合せですとか、そういったところにつきましては真摯に対応しています。お考えであったり、広くこちらとしても把握をさせていただいた上で、今後どうしていくべきなのかについては検討をさせていただきたいと考えています。","id":"exchange-057"},{"speaker":"若林委員","kind":"質問","question":"品川区らしい規制を考えて今の条例の形があるということなので、そもそもの出発点の土・日のみとした、そのときの品川区の考え方はどういうものだったのか尋ねました。","respondent":"赤木生活衛生課長","answer":"冒頭のご説明と一部重複をしてしまう部分もありますけれども、近隣商業地域についてはそちらの周辺の地域と定義がされていると認識をしております。その考えの下に、基本的にはそういった地域では平日を１８０日の範囲内とはいえ、整理をしたという考え方です。","id":"exchange-058"},{"speaker":"若林委員","kind":"質問","question":"１０回、２０回で初めて品川区に通報する、私はこれが実態だと思います。そこら辺の実態も含めて、しっかり見ていかなくてはいけないという感想を述べて、終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"筒井委員","kind":"意見","question":"実情を丁寧に調査研究して、緩和するかの検討がやはりしばらくまだ時間をかけて行っていくべきだと思います。現時点では直ちに規制緩和することは認められないのが理由ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"渡辺委員","kind":"意見","question":"それと同時にこの陳情を見ていて、２枚目にあったように、やはり闇民泊ですとか、品川区への提言等ある中で、やはり適正に運営されている方もいる。それと、議会も含めて行政と連携して、条例をはじめ対応すべきというような思いで会派としてはおりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"若林委員","kind":"意見","question":"悩ましいという言葉遣いもさせていただきました。それは逆に緩和してしかるべき、重ねて感想を述べながら、今日の今の時点では不採択という会派としての結論になりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"鈴木委員","kind":"意見","question":"本日結論を出すで、不採択でお願いしたいと思います。それからそのオーナーの方々の実態とかも含めて、ぜひ区としても把握していただいてご検討もいただくということで、お願いはしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"吉田委員","kind":"質問・要望","question":"この陳情者の方がなさっているのは、でも、中にはやはり相応の実費をお互いの合意で支払ってもらっていた方もあると伺っています。この方の思いは分かりますけれども、その現実を無視して、ここで一気に規制緩和を区に求める決断はできないと判断をいたしまして、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"理由は、今回の陳情の趣旨が土・日の制限の撤廃で、緩和だけを求める内容になっているからです。差別化を図って相対的に優遇する措置もしていますので、そのような形でめり張りをつけていくことを今後進めていく必要があると考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問・要望","question":"どういう事業者なのか教えていただきたいのと、検討の結論は今年度いっぱいかけて出すことになるのでしょうか。それから、心身障害者福祉会館の建て替えまたは大規模修繕を遅らせる要因になることはないと考えていいのか、その点についても伺えたらと思います。","respondent":"石橋障害者施策推進課長、芝野障害者支援課長","answer":"どの程度なのか、今後どのような形で検討していくのかを併せて、委託と同時並行で所管ではしっかりと考えていくべきことだと認識をしております。躯体を含めた全体の老朽度合いの調査の結果を基に検討すると考えておりますので… 今残っている資料の中で２０１９年まであるのですが、２０１９年１０月の通知の辺りから、その辺から検討を進めしています。","id":"exchange-066"},{"speaker":"吉田委員","kind":"質問","question":"私たちも受変電設備はどうなっているのですかと質問もしなかったし、でも何でここまで、幸いにしてトラブルが起きなかったのでしょうか。その辺全然詳しくないので、ご説明いただけるとありがたいのですけれども、いかがか尋ねました。","respondent":"芝野障害者支援課長","answer":"その中で受変電設備もしっかり点検させていただいて、正常に稼働しているということでずっとこれまで使用してまいりました。２０１９年１０月の報告のときに更新の推奨という形で通知をいただきまして、それで検討した結果が今の更新という形に結びついてあります。","id":"exchange-067"},{"speaker":"吉田委員","kind":"質問・要望","question":"点検は当然だと思うし、それにしても何か結果がよかったとここまで判断されてきたのはどういうことなのでしょうか。一度もこの更新は議論はされなかったのか伺いたいと思います。","respondent":"芝野障害者支援課長","answer":"建て替え等々検討の記録というのは特に残ってないところですが、そちらも踏まえまして、ここまで使用させていただいているです。あくまでも利用者への影響というのを第一に考えまして、今後の計画につきましてもそれを第一に考えまして検討していくという形になるかと思います。","id":"exchange-068"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですので、これは要望にとどめておきますけれども、利用者の方たちにまず説明してほしいと求めました。それは要望として求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"筒井委員","kind":"意見","question":"結論といたしましては、不採択でお願いいたします。心身障害者福祉会館の建て替え計画には影響がない、関連しないということが分かりましたので、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それとあとは心身障害者福祉会館の整備は、我が会派としても迅速な整備を変わらず求めていきたいと思います。その点はもう前提としてやっていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"若林委員","kind":"確認","question":"いずれにしても影響し合わないことが確認をされました。ということで、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択でお願いしたいと思います。今回の受変電設備更新工事が、心身障害者福祉会館の整備を迅速に進めてほしいというこの陳情者の思いはよく分かりますし、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"吉田委員","kind":"意見","question":"本日結論を出すで、採択でお願いしたいと思います。それをとどめることはないというご答弁はいただきましたけれども、やはりこの陳情者の思いをちゃんと議会として受け止めて、採択にしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"理事者の説明によって、今回の受変電設備の工事が改修・建て替え等の延期につながらないものということは理解できました。一方で、やはり今回の要旨にあるように、整備を迅速に進めるように品川区に強く求める趣旨には賛同いたしますので、趣旨採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"}]},{"id":"topic-03","title":"令和８年度陳情第２８号、犬のふん尿被害に対する生活衛生課の実効性ある対応および相談 対応の改善を求める陳情","agenda":"令和８年度陳情第２８号、犬のふん尿被害に対する生活衛生課の実効性ある対応および相談 対応の改善を求める陳情","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"今、区が行っていることをご報告いただきましたけれども、今回、この方の被害に対して品川区としてできること、取った対応、そしてまたこの方が求めているけれども、これはこういう理由でできないということをご説明いただけたらと思います。","respondent":"赤木生活衛生課長","answer":"陳情者の申出、ご要望に対して、陳情者に対する対応で、区としてでき得る対応、できない対応の部分に関するご質問についてお答えをします。","id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そこに何か注意喚起の文書の配布をしてほしいと、この方は要望されていると思うのですけれども、区としてはできないのかについて伺います。２枚目で、発生日時、区としてはこういうのはどう考えられているのかについても伺えたらと思います。","respondent":"赤木生活衛生課長","answer":"実際我々の対応といたしまして、「地域センターを通じて町会・自治会の掲示板に犬の散歩のマナーに関するポスターの掲示を依頼しました。","id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問","question":"今でも、そういう被害はずっと同じように続いている状況なのか、そこら辺の実態を教えていただけたらと思います。","respondent":"赤木生活衛生課長","answer":"不快な思いをされていらっしゃるのは区としても認識はしているのですけれども、ふん尿、区としてもそこの事実については確認ができていない状況です。飼い主として処理ができていないと断定するには、区としてそういったところについては現場確認ができていないのが現状です。","id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問・要望","question":"まだそのようにしてしまうのを何とかなくす方法は、突き止めて注意するとか、方法は何かないのでしょうか。そこは救われる手立てが何かないのか、そういうところは区として今後も含めてどのように対応しようとしているのか伺います。","respondent":"赤木生活衛生課長","answer":"陳情者の方への対応につきましては、至らぬ点もあったとは思ってありますし、課一丸となってそれは引き続き取り組んでまいりたいと考えています。","id":"exchange-079"},{"speaker":"鈴木委員","kind":"確認","question":"令和７年ということなので、実際に清掃とかをやったのかまで確認をしていただくとか、本人にも分かる形で示していただく。引き続いて、すごく追い詰められていると現場を見て思いましたので、寄り添う形でぜひお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"吉田委員","kind":"確認","question":"これは９月２２日品川区議会厚生委員会の発言で、そういうことの啓発とかもあって、予防接種には絶対に行きます。そういうところでされているのか、改めて確認したいのですけれども、いかがか尋ねました。","respondent":"赤木生活衛生課長","answer":"冒頭の説明でも申し上げましたとおり、あとは広報しながわで、そちらに毎年９月１１日号に散歩のマナーについて啓発をさせていただいてあります。犬のしつけ方教室を年に２回ほど実施をさせていただいておりまして、周知啓発はトレーニングの方法等も含めてしています。","id":"exchange-081"},{"speaker":"吉田委員","kind":"質問","question":"ということは、私は予防接種のときしか思いつかないので言っているのですけれども、例えばそのような一人一人への対面の具体的な啓発の場は、今はない理解でよろしいか尋ねました。","respondent":"赤木生活衛生課長","answer":"一人一人への具体的な周知、こと詳細な周知につきましては、委員のおっしゃるとおりと存じます。チラシなど、１人でも多くの飼い主の方にマナーとして知っていただくことは、今後も引き続き様々な機会を捉えてやっていきたいと思ってあります。","id":"exchange-082"},{"speaker":"吉田委員","kind":"質問・要望","question":"私もその方にそのような注意をいちいちする勇気もなく、じくじたるものはあるのですけれども、その辺の啓発もぜひ続けていただきたい。もう少し一人一人に啓発するようなことも考えていただきたいと思うのですけれども、現在検討されていることがあったら伺いたいと思います。","respondent":"赤木生活衛生課長","answer":"今後取り組もうと考えていることですけれども、そういった教室への参加に意欲的な方への周知は一定程度できていると認識しておりますが。引き続きどういった形で効果的に皆さんに広く知っていただいて守っていただけるようにできるかは引き続き検討してまいりたいと考えています。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"確認","question":"１点だけ確認ですけれども、これ以上連絡しないようにとかいろいろ結構厳しい対応を取られたと書いてあるのですけれども、この辺の事実関係はどのように捉えていらっしゃいますか尋ねました。","respondent":"赤木生活衛生課長","answer":"先ほど来ご説明をさせていただいたとおり、基本的に個々の事案に応じて、生活衛生課としてまずできることをしっかりと説明をする。ただ、そういったところになりますと、そちらについてはそれぞれの所管について適切につないでいくことが我々としての役割だとは認識しています。","id":"exchange-084"},{"speaker":"筒井委員","kind":"質問","question":"町会への周知啓発として、区の掲示板、町会掲示板に昨年の２月、３月にやっていただいたというご答弁があったと思います。個別にふん尿をさせている方に直接対応していただくのがよいと思いますが、その点、今後のご対応について伺います。","respondent":"赤木生活衛生課長","answer":"１点目の掲示板への改めての周知につきましては、そういったタイミング等を見て、我々で対応することは可能です。２点目ですけれども、実際に個別の対応についてですが、個別の声かけについては我々としても対応させていただきたいと思ってあります。","id":"exchange-085"},{"speaker":"筒井委員","kind":"意見","question":"やはり今後そうしたものができると、トラブルも起きかねないので、より周知啓発を徹底していただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"筒井委員","kind":"質問","question":"結論といたしましては不採択でお願いします。周知啓発の強化をしていただけるということと、状況によっては個別に丁寧に対応していただけるということで、そうした理由で不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから資料を付けていただいたのも１０枚以上の資料が付いている、何かそのようなことも含めて寄り添った対応をぜひしていただきたい。掲示板にもまた改めて出していただきたいというのも含めて、寄り添った対応をしていただけたらと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"吉田委員","kind":"質問・要望","question":"飼い主さんの意識の中で解決すべき問題と思いますし、啓発でここまで来たわけですから、そういう品川区であってほしいという私の要望もあります。ですので、これについては不採択とさせいただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"理由としては、やはり陳情の中での要望がかなり多岐にわたる中で、第一にマナーの向上を優先させるべきだと思います。運動とか気分転換とか社会性を身につけることに代わってきているとお伺いして、啓発活動をしていただきたいと強く要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"}]},{"id":"topic-04","title":"令和８年請願第３号、ヘルパーの警鐘を国に伝えてください～介護報酬大幅引き上げの意見 書を国に提出するよう求める請願","agenda":"令和８年請願第３号、ヘルパーの警鐘を国に伝えてください～介護報酬大幅引き上げの意見 書を国に提出するよう求める請願","exchanges":[{"speaker":"やなぎさわ委員","kind":"意見","question":"ヘルパーに至っては９０％が女性で、これはジェンダーの問題に結びついているものだと私は思っております。より多くの委員の賛同を得られればと考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"},{"speaker":"鈴木委員","kind":"質問","question":"現場の声を伺う機会がたくさんあるのですけれども、そして、また居宅介護支援事業所も増やしていくことが必要だと思うのです。品川区の認識、ケアマネジャーの人材不足で居宅介護支援事業所が大変な状況になっていることに対して、どのような認識を持っているのか伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"鈴木委員","kind":"質問・要望","question":"８４％の首長が国の公費負担割合の引上げという回答をしていますので、そういう声をもっともっと上げていくことが求められていると思います。ぜひ改善させるためにも、どんどん国に求めていくことが必要だと思いますので、いこうということで呼びかけをさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"介護人材政策研究会の５団体が同行しておりまして、まさに今、本当に求められる施策だと思います。区議会として、やはりここは何とかしてほしいと、現場の窮状を一丸となって訴えていくということをしていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"吉田委員","kind":"質問・要望","question":"しかもコロナのときはマスクの着用を求められつつ、さすがに介護の仕事が好きな娘でも大変だったと言っていました。ぜひこれは国に、この場合は介護ですけれども、介護報酬の引上げを区として求めていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"筒井委員","kind":"質問","question":"介護報酬改定を３年に１回から毎年行うこと、ただ、毎年だと社会情勢の変化とかを見定めることもできない。介護報酬改定を毎年行うべきことや介護報酬の国庫負担を引き上げること、できないとする課題、そうした情報は入っているのか尋ねました。","respondent":"佐藤高齢者福祉課長","answer":"そういったところ、介護報酬とは言っていなかったと思いますが、意見を出している状況です。","id":"exchange-096"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはりこうした問題は、１つの自治体というよりは、その下、課長会で話されて、特別区長会で、ある程度、束になってまとめて介護報酬の改善を求めていくべきと考えておりますので、引き続きそうした課長会や区長会で取り上げてほしいと求めましたので、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"筒井委員","kind":"質問・要望","question":"結論は不採択でお願い申し上げます。特別区の課長会、ひいては区長会でこの介護報酬の問題はぜひ取り上げてほしいと求めましたので、不採択でお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"若林委員","kind":"質問・要望","question":"介護報酬引上げについては、国の制度の問題で、国会の中でも私どもから要望なり、また、議論なりさせていただいていると認識しております。そういった議論は私どもやっておりませんので、そういったことを議会の意見書として出すことについては、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"鈴木委員","kind":"質問・要望","question":"月７,０００円で、最大でも１万９,０００円なので、実際にここまで上がらないと思います。さらに５％も言われている中で、そういうところに使うべきですし、そして待ったなしに求められている切実な状況の改善につなげるべきだと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"吉田委員","kind":"意見","question":"そういう現状を踏まえると、今この請願にも出ているとおり、やはり女性に片務的である実態は、それが現実だと思います。ぜひ介護報酬の引上げはやるべきですし、それからそれはやはり国の役割であると思いますので、こういう意見書の提出はぜひ採択したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"},{"speaker":"やなぎさわ委員","kind":"意見","question":"代わりに１つできたからプラスマイナスゼロという状況ではない、早急にこういった意見書は品川区議会として上げるべきだと考えています。〔「筒井委員個人の意見ではなく、会派の意見」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-102"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"会派の意見としてそうなられたのでしょうかと思うのです。そうであれば、そういったこともぜひもっと詳しく説明をしていただきたい、委員間討議を含めてお話をいただきたかったと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.29ko.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":65,"characters":83437,"voices":276}},{"id":"r08-20260629-8","meetingId":"r08-m0708","date":"2026年6月29日","dateIso":"2026-06-29","committee":"建設委員会","time":"午前１０時００分～午後３時２８分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を90件整理しています。","topics":[{"id":"topic-01","title":"第６５号議案、 品川区手数料条例の一部を改正する条例","agenda":"第６５号議案、 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料１の下段の、それらの手法の実績というのはこれまでどれぐらいあったのかなというのをお伺いしたいのと、これの実績というのはどれぐらいこれまであったのかを伺いたいと思います。","respondent":"川原住宅課長、森建築課長","answer":"新たに１棟リノベと言われる、あとは、いわゆる再建決議というものが新たにマンション再生事業の中に加わった形です。災害等で滅失したマンションがあった敷地を売却する事業となる、敷地売却決議… 容積率緩和の特例許可の現在までの申請件数ですけれども、現在のところはございません。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問","question":"その管理不全マンションの放置というのは、大体でいいのですけれども、区として把握されている棟数を教えてほしいと求めました。","respondent":"川原住宅課長","answer":"そのまま放置すれば周辺の区民の方に著しく危険が達するおそれがあるといったマンションについては、今のところ、なしということで把握をしています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"意見","question":"やはり老朽化マンションの建て替えには、更新のための要件緩和だけでは難しいのかなと思います。抜本的な様々な支援制度が必要なところではありますけれども、更新のためのこういう要件緩和自体は否定するものではございませんので、賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]},{"id":"topic-02","title":"第６６号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正 する条例","agenda":"第６６号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正 する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それぞれのもともとの容積率と高さの最高限度は幾らだったのか伺いたいのと、７５０％、７００％になったのか伺いたいと思います。","respondent":"森建築課長、中道都市開発課長","answer":"現状がどうだったのかというところですけれども、３０ｍ以内のところが容積率４００％、３０ｍを超えたところが容積率３００％です。高さの制限は、高度地区等、特にはございません。 それが５００％になります。促進区の地区計画を使うことで、容積を適正に配分するということができますので、今回７５０％ または７００％といった容積になってあります。","id":"exchange-004"},{"speaker":"安藤委員","kind":"意見","question":"かなりの容積率の緩和ということで、促進区も使ったということもありましたけれども、やはり上位計画や行政が、こうした超高層ビルが林立するような地区計画を誘導しているということがよく分かりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"安藤委員","kind":"意見","question":"２割もの権利者の方が同意をしていない、地区計画など情報が秘匿されている、そして大崎駅の混雑を一層ひどくするなどの理由でした。その再開発の具体化の条例であるため、反対いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問","question":"私のほうから幾つかお伺いしたいと思います。北品川三丁目その３の入札不調のところですが、資料に書かれておりますが、こちらの今後のスケジュールが分かっていれば示すよう求めました。","respondent":"関根河川下水道課長","answer":"２点ご質問をいただきました。資料でご説明をいたしました、今年の１２月からおおむね１年間の工事の中で、今回入札不調になった範囲も含めて工事を実施していく予定としています。","id":"exchange-007"},{"speaker":"おぎの委員","kind":"質問","question":"技術者の配置困難ということで、今言われております建設業界の人手不足や物価高騰など、工事を受注しにくいという現実があるのかなと思います。こちらの北品川三丁目その３以外も、今あちこちでやっていると思いますが、そちらのほうは予定どおりに進んでいるのか尋ねました。","respondent":"関根河川下水道課長","answer":"今年度につきましては、当初３件の工事を予定しておりまして、そのうち１件が本日ご説明させていただいた入札不調のあった案件です。残り２件につきましては、契約のほうは締結をいたしまして、現在、予定どおり工事のほうを進めている状況です。","id":"exchange-008"},{"speaker":"おぎの委員","kind":"意見","question":"インフラの更新が遅れますと、やはり安全性や維持管理などコストにも問題が出てきますので、ぜひ引き続きよろしくお願いいたします。こちら１点だけ、こちらは７,８００円から９,８００円になっておりますが、こちらは消火器の物価高という認識か尋ねました。","respondent":"遠藤防災体制整備担当課長","answer":"委員おっしゃった、昨今の物価高、上昇によって、今年度価格改定をするというところで、７月から価格改定でこのたびの価格に変更するです。","id":"exchange-009"},{"speaker":"安藤委員","kind":"確認","question":"家具転倒防止のほうですが、１００世帯という予算なのですけれども、その根拠を伺いたいのが１つです。確認なのですけれど、分電盤型の非木造住宅の補助というのが拡大するという意味なのでしょうか、伺います。","respondent":"羽鳥防災課長、遠藤防災体制整備担当課長","answer":"私からは、家具転倒防止の１００世帯という根拠についてお答えします。今回補助を活用することで、さらに多くの方にご利用いただけるということを見込んで、切りのいいところで １００世帯とさせていただきました。 令和５年度が３９５本、令和６年度が６０２本、令和７年度が７９１本となっています。委員おっしゃるとおり、非木造住宅についても分電盤型の感震ブレーカーの補助を拡大するというところで実施をしたいと考えております。","id":"exchange-010"},{"speaker":"こんの委員","kind":"質問・要望","question":"やはり在宅避難をするということが主流ですから、そうなると、この感震ブレーカーが非木造住宅に拡大されたのは本当にありがたいというところです。一般質問でもご答弁をいただいたところをいま一度確認したいのですが、たしか、いま一度その辺も確認したいと求めました。","respondent":"羽鳥防災課長、遠藤防災体制整備担当課長","answer":"私のほうからは家具類転倒等対策器具のスケジュールについてお答えします。都の補助金を申請するというスケジュールですので、そういった期間を踏まえて、１２月末までとさせていただきました。 １点、区のほうで考えているのは、粉末タイプの物で補助することを考えています。今回、全家屋対象ということで、一般のプレハブ住宅にも適用するというものになってあります。","id":"exchange-011"},{"speaker":"こんの委員","kind":"確認","question":"スプレー式は入らないのですかというお聞きをしたつもりだったのですが、そのスプレータイプも入れたらどうですかといったところです。確認をいま一度させていただきましたので、この事業というのは必要だなと考えていますので、引き続きよろしくお願いしたいと思います。","respondent":"羽鳥防災課長、遠藤防災体制整備担当課長","answer":"今回の補助金は来年度まで実施予定ということは伺っておりますので、予定どおりいけば、来年度は当初の段階からＰＲできるのかなと考えています。今年度の実施の状況を踏まえて… スプレー式の物も採用したらどうかといったご質問でした。一応こちらのほうにつきましても、予算等を鑑みながら、採用できるようであれば検討して進めていきたいと思いますので、よろしくお願いいたします。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"家具類転倒等防止器具のことでお尋ねなのですけれども、この２の事業内容の中の（６）その他のところで、改めてその周知方法についてお尋ねをさせてほしいと求めました。","respondent":"羽鳥防災課長","answer":"今回、委員おっしゃられたとおり、高齢者地域支援課のほうで、福祉的な視点から取付けも含めた補助をやっているです。高齢者地域支援課の事業のほうでも、双方でお互いの事業というのをしっかりＰＲしていきたい、連携を図っていきたいと考えています。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ、連携して周知を図ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"えのした副委員長","kind":"確認","question":"私からも何点か少し確認をします。以前私もこれを質問させていただいたのですけれども、内容が違うということで、あっせんの消火器の種類について示すよう求めました。","respondent":"遠藤防災体制整備担当課長","answer":"街頭消火器の薬剤の種類ということでよろしいですか。","id":"exchange-015"},{"speaker":"えのした副委員長","kind":"質問","question":"種類はそのときに質問したのですけれども、今回のあっせん販売する消火器は、ノズル式、粉末式と言っていましたが、それというのは電気火災にも対応するような種類になっているのか尋ねました。","respondent":"遠藤防災体制整備担当課長","answer":"大変失礼しました。今回の、あっせん販売する粉末タイプに関しましては、電気火災にも対応している物となっています。","id":"exchange-016"},{"speaker":"えのした副委員長","kind":"確認","question":"確認が取れました。安心して、こちらは電気火災に対応するということで確認させていただきました。","respondent":"遠藤防災体制整備担当課長","answer":"漏電遮断機能がついていない物がありますので、こういった物に関しては、ブレーカーの中に感震ブレーカー機能が入った物にそのまま交換をする。ご自宅の設置状況によって、感震ブレーカーのタイプを選定して、購入してから設置するというような形になりますので。","id":"exchange-017"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"マンションにお住まいの方が８割以上と言われているので、大変助かると思うのですが、なかなかこれは分かりづらいと思うのです。なので、ぜひ周知の際には分かりやすく、こういった図も示したりしながら周知をしていただければと、こちらは要望です。","respondent":"遠藤防災体制整備担当課長","answer":"先ほど、こんの委員のご質問の中で、私、スプレータイプの物について検討しますという答弁させていただいたのですけれども、今回取り扱う物は全てノズルの消火器といったところになりますので、そちらのほうだけご理解していただければと思いますので、よろしくお願いいたします。","id":"exchange-018"}]},{"id":"topic-03","title":"令和８年請願第５号、リニア中央新幹線工事再開に対し 再度住民説明会を求める請願","agenda":"令和８年請願第５号、リニア中央新幹線工事再開に対し 再度住民説明会を求める請願","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"これから審査するということですので、やはり審査の中身にも関わってくることですので、ぜひご希望があれば冒頭からでも意見陳述を受け付けるべきだと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"こんの委員","kind":"意見","question":"質疑終了後で取扱いを決めるでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"おぎの委員","kind":"質問","question":"参加された方からもし感想等をお聞きになっているようでありましたら、どういった声が出ていたのかというのを併せてお聞かせほしいと求めました。〔傍聴席にて騒ぐ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"おぎの委員","kind":"確認","question":"もう一点なのですが、補償についてお伺いしたいと思います。本当に住民の方の心配の根底には、万が一といったときは、必ずそういったものは何らかの補償の確認等はしっかりとされているのか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"いわゆる家屋補償の件についてお答えいたします。工事の実施前に、もし万が一、そういった資料を基にしっかりと交渉していくということを聞いているところです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回リニア中央新幹線工事再開に対し再度住民説明会を求める請願ということで、追加で出された署名などの数が分かれば教えてほしいと求めました。いかがか尋ねました。","respondent":"あくつ委員長、大石まちづくり立体化担当課長","answer":"当委員会としての回答をさせていただければと思いますけれども、先ほど書記からもご説明あったとおり、５名の追加署名がございました。本日の分につきましては… その中では、今後、今回の説明会の開催方式についての考え方をお示しくださいといったところが掲載しているものです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"次の質問に行くのですけれども、４月２２日に掘進が再開されたということなのですが、工事による住民からの通報や問合せなどはあったのでしょうか。そのトンネル沿線の地元地域や、その町会などから、品川区長に対してはどのような要望が出ているのか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"ＪＲ東海に今後の対応について申し入れていただきたいといったものが１件、次の説明会はいつ開催されるのでしょうかといったところがございました。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは、数えると１０もの町会長が再度、説明会を求めていると。これをＪＲ東海に求めてほしいという、この求めを区としてはどういうふうに受け止めているのか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"これまでもＪＲ東海に対して、区民への丁寧な説明と適切な措置を図るよう、繰り返し求めてきているところです。なお、ＪＲ東海からは、 今後も掘進時期に合わせて順次、オープンハウス型の説明会は開催する予定と聞いているところです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"そんなのは当然なことであって、今すぐ一斉説明型の説明会を開いてほしいということが住民の望みなわけです。こういう要望書が届いているという事実自体は、所管としても把握しているということでよろしいのか確認したいと求めました。","respondent":"大石まちづくり立体化担当課長","answer":"実際に、区のほうに届けられたかというところまでは、申し訳ございませんが現時点では所管としては把握していないです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのは、これらの請願ですとか要望書にあるように、さらに踏み込んで要望をしてほしいと求めました。これだけの１,２００人を超す署名、地元を中心とした旗の台等からの１０もの町会長からも要望していることですから、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"ＪＲ東海のほうが十分な説明をするなど責任を持って対応すべきものと考えているため、区民への丁寧な説明を行うよう求めてきております。区といたしましては、引き続きＪＲ東海に対しまして、一斉説明型の開催も含めまして様々な手法を用いて説明を行うよう求めてまいります。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"旗の台のほうからもこういった強い要望が出たという中で、区から要請はしていただけるのでしょうか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"私としては、 もう当然ですけれど、当然の要望なので、求めるべきだと思っているわけですが、これは実は議会も問われているということになるのです。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"こんの委員","kind":"確認","question":"今の質疑で確認させていただいた部分もありましたので、意見陳述は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"安藤委員","kind":"意見","question":"請願者の思いを聞いて審査をするというのは、私は当然そうあるべき議会だと思いますので、聞いていく必要があると思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"おぎの委員","kind":"質問・要望","question":"説明会の目的としては、情報を共有することが説明会の趣旨だと思いますので、一斉説明型の手法にこだわることではないのかなとも思います。引き続き強く要望していただきたいとお願いをしまして、会派としては、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"えのした副委員長","kind":"確認","question":"オープンハウス型のほうがより分かりやすかった、今後もＪＲ東海は、そういった説明会をしていくということで確認が取れました。〔傍聴席にて騒ぐ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"こんの委員","kind":"提案","question":"オープンハウス型というところも提案されていて、質問をしてお答えをいただく、こうした手法もありだなと思います。今後も区としては求めていただきたい、このことを要望しまして、今請願につきましては不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"再度の教室型、一斉説明型の説明会を求めるというのは、本当に何ら不思議がないことだと思います。ぜひ、今、不採択と表明された会派の皆さんもいますけれども、今からでも考え直してほしいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"この要望書が、北品川工区については議題に上がるようなことも私もお聞きしておりますので、この調査対象地区の家屋に入っております。各町会長にはいろんな声が届いておりますので、ぜひこれは改めて、この説明会を求める請願に対しては採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"陳情第２０号を審査する上で少し伺いたいのですが、どういうことなのか、区からの説明を求めたいと思います。９６３億円、２０２５年３月 １３日の予算特別委員会の答弁なのですけれども、明らかにする時期の基準というのを伺いたいと思います。","respondent":"中道都市開発課長","answer":"そういったものを近隣説明会の中で報告したほうがいいのではないかというようなご提案がございましたけれども、いわゆる都市計画決定の前というのは。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"大崎ウエストシティタワーズの地区の丸々２棟分の補助金額と同じなのですけれど、なぜこれだけ増えるのかという理由を伺いたいと思います。伺いたいのは、そもそもこの小山三丁目第１地区の組合員数というのは何人になっているのか伺いたいと思いますし、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"そこについて弁護士に相談したところ、弁護士とも問題がないというような回答を得ているというところは、区のほうに報告が来ているところです。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"これは、何でそうなるのですかというところ、それが知りたかったのでお伺いしたいなと思います。これは、くどいようですけれど、マンション区分所有者の従前資産を安く見積もっているということにならないのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"いわゆる都市再開発法にのっとってマンション区分を持っている方を１と考えて、この地区では全体で約８４％の方がこの再開発に同意をされております。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"詳しい説明を求めたいとあるので、詳しい説明を行政担当者に求めたいとありますので、こちらをご答弁ほしいと求めました。もう組合認可後になってしまっている今回の小山三丁目第１地区というケースと、都市計画手続に入る前のケース、それぞれで伺いたいと思います。","respondent":"中道都市開発課長","answer":"続きまして、補助金の考え方です。その中で、組合がそういった申請書を出されれば、それは交付すべきものという認識です。","id":"exchange-040"},{"speaker":"安藤委員","kind":"意見","question":"そういった分譲マンションがたくさんあるようなところで超高層再開発を進めていくということが本当にいいのかと、私は見直すべきだなと思います。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"おぎの委員","kind":"質問・要望","question":"地権者住民の要望を無視しているということで、まちづくりの主体はそこに住む人たちだということ、私も同意見です。先ほど８４％という数字となっておりましたが、実際住民の方の要望というのは、その辺をもう少し詳しくお聞かせいただけたらと思います。","respondent":"中道都市開発課長","answer":"もう一つ、やはり商店街の活力という意味で、今後１００年、商店街を継続させていかなければいけないという声もいただいてあります。いわゆるパルム商店街は今、２階部分でもデッキを張って、そういった中で区としてもいろいろと調整を進めているです。","id":"exchange-042"},{"speaker":"おぎの委員","kind":"質問・要望","question":"弁護士に確認したところ、これは国の法律ですので、ここの国の法律を区でどうこうというわけにはいかないのかなとは思っております。弁護士にも確認しており、相談窓口設置など不安な気持ちに寄り添うように引き続き、区としても適宜介入して求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"えのした副委員長","kind":"質問","question":"弁護士の方も問題がないと回答していると、区として報告を受けているということで、不採択とします。〔傍聴席にて騒ぐ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"こんの委員","kind":"確認","question":"主張、こうした出されたものに対して理解しないわけではありませんけれども、これまでの会議録を確認してきました。確認もさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、趣旨採択でお願いしたいのですが、手続の不備は、私は明らかだと言わざるを得ないと思います。それぞれの委員の見解も明らかにすべきだと思いますし、陳情者の気持ちも分かるのですけれども、趣旨採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今後のことを今この時点で、支出があるのかないのか明らかにというのは恐らく断言するのは難しいのではと思い、不採択とします。状況に応じて資金計画の確認はしっかりと今後も行っていただきたい、ここの点は要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択を主張したいのですが、やはり再開発への補助金の支出額というのは、私は予定額も含めて早期に議会や住民に明らかにすべきであると思いますので、採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"おぎの委員","kind":"質問・要望","question":"住民の方からの要望といったところで、商店街の活力であったりとか、そういった希望なども多く出ているということを確認させていただきました。今回は、こちらは不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"安藤委員","kind":"意見","question":"趣旨採択なのですけれど、独り暮らし高齢者をはじめ、弱小権利者を置き去りにして推進してきたことに対する怒りが陳情全体から伝わってまいります。気持ちは本当によく分かるので、この趣旨を酌み取って趣旨採択ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問・要望","question":"個人的な要望なのですけれども、投機マネーというのでしょうか、何らかの方法も併せて考えていただきたいなと思います。最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、趣旨採択でお願いしたいのですが、現時点において区の判断で１円も補助金を出さないということは難しいかもしれませんけれども、そもそも巨額な税金を使うべきではない事業だということには私は変わりないと思いますし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"}]},{"id":"topic-04","title":"号、品川浦周辺地区まちづくりガイドライン策定に関して現状等を住民 に説明・質疑応答する会と対象地域から除外を希望する住民の希望調べの実施と次回の意見交換会・ア…","agenda":"号、品川浦周辺地区まちづくりガイドライン策定に関して現状等を住民 に説明・質疑応答する会と対象地域から除外を希望する住民の希望調べの実施と次回の意見交換会・ア…","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"陳情の本文のほうから伺っていきたいのですが、なぜそれを上位計画に縛られないといけないのか、本当に分かりませんと。そのような陳情者の当然の要求はどうしたらかなえられるのか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"新しい建物への居住や商店の継続、もしくは補償金により地区外に出るか、ご自身で選択できる仕組みとなっています。区といたしましては、いただいたご意見等を準備組合に届けるとともに、丁寧な対応を行うよう準備組合に伝えてまいりたいと考えているところです。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"今のご答弁ですと、出ていく権利もありますし、ビルに入る権利もあるのだと。結果的にそこに住み続けたいという方が住み続けられなくても、まちづくりのためには仕方ないという認識なのでしょうか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"先ほどご答弁申し上げたのはそういった趣旨ではなく、まちづくりにつきましては、地域の皆さんで話し合いながら進めていくことが重要と考えています。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"今のような感じですと、私はこういった陳情者の方のような要望も含めて、大事にしていくようにはならないと思うのです。伺いたいのですが、午前中の武蔵小山の質疑もありましたけれども、この地区ではどうなっているのか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"６棟で３１８戸、２棟で１２３戸、３棟で１４０戸と聞いてあります。次の加入についてですが、準備組合に確認したところ、基本的にはマンションごとの加入と聞いているところです。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれども、したがって、先ほどのマンションの軒数の件も併せて、陳情にあるように、準備組合は住民の一部にすぎないと。しかも、再開発を進めたい方々の集まりだけであって、地区内住民の代表とは到底言えないと思うのですけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"より多くの方によりましてまちづくりの検討がなされるよう、準備組合に加入されていない方に対しても丁寧な説明を行うよう、繰り返し求めております。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"３月に３地区の理事長とともに、時間はどれぐらい話し合ったのか、伺いたいと思います。来た準備組合に対して区が言ったという、まちづくりの進展に合わせて必要な対応を図るというのはどういう意味なのか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"質問の２点目の、必要な対応を図るという記載がありますが、地域として不安の声が上がっているという声をいただいてあります。そのような方たちに対しても丁寧な説明と対応を行って、 理解と協力をいただくことが必要と考えている。","id":"exchange-057"},{"speaker":"安藤委員","kind":"確認","question":"伺いますけれども、再開発準備組合ニュースにある、姿勢に変わりがないことは確認済みであるというのはどういう意味なのでしょうか。現時点ではという話もありましたけれども、本会議等での答弁から立場が変わったということなのか、もう一度伺います。","respondent":"大石まちづくり立体化担当課長","answer":"現時点で区域の指定や都・国への働きかけ等は考えていない、現時点において、区独自で補助金を交付することは考えていないと答弁したものです。総合的に考える必要が生じるものと考えておりますが、現時点におきましては、補助金に対する考え方に変更はございません。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"冒頭の説明ではこの陳情項目に対してのお答えがなかったので、 私としても設けてほしいと求めましたが、いかがでしょうか。その相違点を教えていただきたいとありますので、ぜひこちらを教えていただきたいのですが、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"お電話や窓口等でお問い合わせいただければ、区として引き続き丁寧に対応してまいりたいと考えているところです。当該地区につきましては、先ほど申したとおり、これによって市街地再開発の事業の実施有無に影響を与えるものではないと考えているところです。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"陳情項目②についても伺いたいのですが、４月１４日の陳情審査では、再開発区域から除外してほしいという陳情者の要望に対して。住民が再開発によって悩まされているわけですから、私は行うべきだと思うのですけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の陳情項目の②につきましてですが、地域主体でまちづくり検討がなされている範囲について、ガイドラインを策定することを検討しております。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"除外するのではなくて、そこだけ話せというのではない、再開発のことも話せる場にしてほしいと思いますけれども、いかがでしょうか。閲覧も可能なものにしてくださいという要望が書かれておりますが、こちらについても、こういった意見をどう反映するのか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の陳情項目③のところですが、まず、詳細につきましては今後の検討になります。どのような開催方法やアンケートの記載方法がよろしいかというのは、今後検討してまいりたいと考えているところです。","id":"exchange-061"},{"speaker":"おぎの委員","kind":"質問","question":"どうしても再開発というと、イコールタワーマンションとか、そういうイメージも出てきてしまうのですが、そもそもの意見交換会の趣旨としては、地域全体の魅力であったり防災や景観について、みんなでまずは話し合うという認識でよろしいでしょうかということを説明するよう求めました。","respondent":"大石まちづくり立体化担当課長","answer":"今まちづくりの検討が行われている地区に対して、区が考えるものや、まちづくりの指針となるように策定していくものです。","id":"exchange-062"},{"speaker":"おぎの委員","kind":"確認","question":"いろいろな意見を聴いてガイドラインに落とし込んでいく作業というか、そういった機会を持っていくということで確認いたしました。中立な会となるようにということで、あと推進派と反対派が同じグループになるのも避けてくださいということですが、これは可能なのか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"区が考えるまちの課題等を説明しまして、参加者の方の理解度が均等になるように努めるなど、あくまで中立な立場で開催したものです。２点目の推進派と反対派ですが、そういったところで中立性を担保してまいりたいと考えて、前回は実施したところです。","id":"exchange-063"},{"speaker":"おぎの委員","kind":"質問","question":"お互いの考えていることが理解できて納得できるような、そういった会をしっかりとつくってほしいと求めました。今回のこちらは不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"えのした副委員長","kind":"確認","question":"区の予定も確認ができました。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"こんの委員","kind":"確認","question":"区としては、先ほど質疑の中にありまして確認しましたけれども、あるべき姿のまちづくりをお願いしたいと思います。ですので、本陳情については、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"安藤委員","kind":"意見","question":"採択でお願いしたいのですが、開発企業主導で進める超高層再開発準備組合に加担するということが、行政の行うまちづくりではないと思います。したがって、採択を主張したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"}]},{"id":"topic-05","title":"令和８年陳情第２９号、危険行為、違反行為を行った建設事業者にペナルティー等を科すこ とを求める陳情","agenda":"令和８年陳情第２９号、危険行為、違反行為を行った建設事業者にペナルティー等を科すこ とを求める陳情","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"今、看板の設置のお話がご説明ありましたけれども、陳情の工事現場で、理由のところにありますような隣地への落下物なども含めて、ほかの違反行為とか危険行為は確認されたのか伺いたいと思います。","respondent":"川原住宅課長","answer":"今説明申し上げました説明の看板以外のところです。関連部署から確認をするなどの対応をしていただいて、このようなことだったということで、取りまとめは住宅課でさせていただいていたといった形です。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"必要な指導も行ったということでしたので、書かれていることは間違いではないのかなと理解いたしました。公表というペナルティーを規定するということは可能なのか、また、他区の例はあるのかなど伺いたいと思います。","respondent":"川原住宅課長、森建築課長","answer":"２つ目の質問から、こちらで把握している限り、ペナルティーを科している事例は聞いたことがないといった状況です。しっかりと予定を提示するといったところは、そこまでの事後のところの対応は、困難なのかなと考えているところです。今回、シートは張ってあったので違反ではないのですが、全く張らないで、物が落ちるような状況で工事を進めている場合は、罰金等の規定があります。","id":"exchange-069"},{"speaker":"おぎの委員","kind":"質問","question":"違法といいますか、不適切なものに関しては、適宜介入していただくということで、一方で、しっかりとされていても、思わず事故が起きてしまうことはあると思うのですが、最近ニュースにもなっていましたが、西五反田の足場の倒壊等のときも、区ではどういった介入を行ったのか尋ねました。","respondent":"森建築課長","answer":"警察や消防も来ていました。様々連携を取りながら、そういうことがないように指導しています。","id":"exchange-070"},{"speaker":"えのした副委員長","kind":"質問","question":"近隣住民説明会も行われているということで、今後も建築主および近隣住民に対して、問題解決するようにご調整をお願いいたします。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"こんの委員","kind":"質問・要望","question":"対応できるものはしてくださっていることが確認できましたので、今後もこういう紛争については、できるだけご対応いただけるようにしていただきたい。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"安藤委員","kind":"意見","question":"何を危険行為とするか、違反行為をどう判断するかは難しい点はあるのですけれども、区の規定の改善の検討はあってもよいと思われます。は検討からというところで、趣旨採択を主張しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"高橋（伸）委員","kind":"意見","question":"もっとそれ以上にいろいろやっていけなければいけないので、恐らくこの陳情の事業者に対しては、まれな事業者なのかなと私は感じております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"}]},{"id":"topic-06","title":"令和８年請願第４号、先日ギックリ腰になりました。ベンチがなくて辛かったです～ベンチ 増設の請願","agenda":"令和８年請願第４号、先日ギックリ腰になりました。ベンチがなくて辛かったです～ベンチ 増設の請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２つ増えて２８７基となったのですけれども、もう少し場所なども詳しく伺いたいというのが一つと、お休み石やベンチをさらにこれからも増やしていくという考えがあるのかどうか伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"一定数のお休み石を設置してきていまして、一定程度、設置できるところについては設置してきたという経緯があります。その中で、ご要望、また交通状況等含めて、適地があり、かつご要望があるところであれば、検討していきたいと考えています。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのと、樹冠被覆率というのではないかと思うのですけれども、それと違うのでしょうか。樹冠被覆率ですとか、そういったものをここまで持っていくという目標を持つ考えは品川区にはあるのでしょうか、伺いたいと思います。","respondent":"髙梨都市計画課長","answer":"現在検討中ですので、現在それも一つ、重要なファクターとして検討を進めているところです。海外の事例も今広く調査をしているところで、品川区での適用等についても、今後検討の中で考えてまいりたいと考えています。","id":"exchange-076"},{"speaker":"安藤委員","kind":"確認","question":"ごめんなさい、樹木被覆地と同じ意味だということなのかという確認と、あと、そういった数値的な目標を持つ考えはあるのかというのを伺ったので、もう一度お願いします。","respondent":"大友公園課長、髙梨都市計画課長","answer":"樹木被覆地と樹冠被覆率なのですけれども、正式には若干異なるところはあるのですが、ほぼイコー ルというところで考えて捉えていただいて大丈夫かと思います。 数値目標を樹冠被覆率で設けるかどうか等についても、現在検討中です。","id":"exchange-077"},{"speaker":"おぎの委員","kind":"質問","question":"他区の状況はどうなっているのでしょうか。お休み石マップみたいなのを、そういったものがあれば行動計画が立てやすいのかなと思いますが、その辺りに関してはいかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"同様の町なかベンチ設置事例という形で申し上げますと、豊島区６０基、かなり多い状況かとは思っております。２点目のマップにつきましては、少しデータの整理等ありますが、今後様々な形でお知らせ、周知していければと考えています。","id":"exchange-078"},{"speaker":"おぎの委員","kind":"質問・要望","question":"要望があれば、先ほど要望として少し上げさせていただきましたが、ぜひ周知してほしいと求めました。こちらの請願は不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"お休み石の設置、ベンチ、こちらも区民の要望から増えていると。木陰の面積も増えているということで、シェードポリシーにも期待をしておりますということで、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですので、事前に品川区はこれだけ設置されているのだということも私は確認して、今日は出席をしております。それでも区としては要望があれば、また、歩道上安全性が確保されて適地であれば、設置をするという考え方も持っていただいている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"安藤委員","kind":"確認","question":"なかなか歩くのが大変だということを２度経験しているのですけれども、そういうことで、こういった方の気持ちはよく分かります。質疑を通して、これからも増やしていくという意思はあるということも確認させていただきましたけれども、私は採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"}]},{"id":"topic-07","title":"令和８年７月区営住宅入居者募集","agenda":"令和８年７月区営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"参考というところですけれども、直近の令和８年１月の募集でも、やはり倍率は２９.１倍と、大変高い倍率を示していると思います。一般質問で公営住宅の増設を求める質問については、今の住宅ストックは幾つなのですかというのを伺いたいのと、伺います。","respondent":"川原住宅課長","answer":"３,６００戸、最大で家賃が４万円、引き続き協力の依頼をしっかりと図っていきたいと考えているところです。次に２点目が、公営住宅の増設について、適正な時期の建て替え時に戸数を増やす考えはあるのかといったところです。","id":"exchange-083"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは要望なのですが、これは余っている戸数なのですか、それだけの戸数があるという意味なのでしょうか。どちらなのか尋ねました。","respondent":"川原住宅課長","answer":"あくまでも借家数ということで、戸数です。空きがある住戸数とはまた別という形です。","id":"exchange-084"},{"speaker":"安藤委員","kind":"質問・要望","question":"住宅に困窮している方が入れるものではございませんし、住宅ストックがあるといっても、そこが空いているとも限らないと。現在の生活困窮者の方々の住まいの相談を受けている業界の皆さんなどの現場の声もよく聴いて、住宅政策を見直していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"こんの委員","kind":"質問・要望","question":"区営住宅は電子の申込みは今ないと認識しているのですが、今後はそういうことは考えていらっしゃるのですかといったところが１点。もう１点が、何年前になるでしょうか、二葉一丁目区営住宅の建て替えについてという要望を、これまで何度か議会質問で上げさせていただいてきました。","respondent":"川原住宅課長","answer":"都営住宅については令和５年から電子申請を開始したというところで、今、改めて電子申請についても検証を進めていきたいと考えているところです。","id":"exchange-086"},{"speaker":"こんの委員","kind":"確認","question":"そういった方向性も考えられるといったことを思っていらっしゃるのだと確認させていただきましたので、この先、時代的にもあるのかなと思うと。ですが、更新をしないということではないということも、今のお答えで確認をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"}]},{"id":"topic-08","title":"専決処分の報告について（報告第１９号）","agenda":"専決処分の報告について（報告第１９号）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"通行人など人に当たる可能性は、時間帯によってはあったと考えているのか伺いたいと思います。そして、なかなか簡単ではないと思うのですけれども、再発防止策というのはどういったことを考えているのか伺います。","respondent":"森道路課長","answer":"本樹木も樹木診断を実施して、倒木が起きる前に伐採をしていくように考えていたところ、集中的に診断を進めているところです。そういった形で樹木診断をしっかりやりながら、できるだけ早期に樹木の伐採、それから、その後の新植という形で進めていきたいと考えています。","id":"exchange-088"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"６月２６日のこしば議員の地域公共交通についての質問なのですけれども、今後の地域公共交通全体についての方針をどのように考えているのかというのを伺うのと、現時点での区の考え方も伺えればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"安藤委員","kind":"質問","question":"６月２７日に台風が２つ、７号・８号が来たわけですけれども、基準みたいなのがあればお伺いしたいと思います。","respondent":"羽鳥防災課長","answer":"先日の台風７号・８号についての対応についてご質問がありましたので、お答えさせていただきたいと思います。今回は事前にレベル３の大雨警報が発表される可能性が高かったので、本部は立ち上がらずに対応を終了したという経緯になってあります。","id":"exchange-090"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.29ke.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":61,"characters":73361,"voices":314}},{"id":"r08-20260629-9","meetingId":"r08-m0708","date":"2026年6月29日","dateIso":"2026-06-29","committee":"文教委員会","time":"午前10時00分～午後１時55分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件整理しています。","topics":[{"id":"topic-01","title":"第６７号議案 品川区文化財保護条例の一部を改正する条例","agenda":"第６７号議案 品川区文化財保護条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"修理の補助金というのが、指定文化財制度にも登録文化財制度にもありますが、これ、額は違うものなのか伺いたい。保存と活用を促進するということですが、活用というのは、 例えばどういうことなのか、伺いたいと思います。","respondent":"舩木庶務課長","answer":"そこまでの規制を設けることなく、何か変更する場合には、それを受理することでその変更を認めていきたいと考えております。区指定文化財制度と区登録文化財制度に同等の必要と認められるものをしっかりと対応していくということを予定して考えておりますが。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、緩やかな規制というところでは、届出を受理された時点でもう形や色の変更ができるということなのですね。現在、指定文化財は区内にどのくらいあって、２３区では、今、登録文化財制度はどこまで広がっているのか、説明を求めました。","respondent":"舩木庶務課長","answer":"区の指定文化財は、現在１４３件あります。２３区に目を向けますと、１６区ほどこの登録文化財制度を導入済みであることを確認しております。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"指定文化財は今まであったわけですけれど、指定文化財が登録文化財に変わっていくということはないのですね。指定文化財はもうずっと指定文化財のまま、 登録文化財になるのは新たなものという考え方でよろしいか尋ねました。","respondent":"舩木庶務課長","answer":"区教育委員会といたしましては、約３年強にわたって審議を重ねた中で、このたびお示ししている案で考え方がまとまったです。歴史あるということで、今１４３件と申し上げましたが、今の段階ではそういうことは想定をしておりません。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"要望が非常に多くなってきているなと思うのと、その管理の方法というのはやはり問題かなと思っています。運用上、細かい規定が必要なのかなというのが多々あると思いますが、その件はいかがか尋ねました。","respondent":"舩木庶務課長","answer":"しっかりコミュニケーションを図っていく上で、繰り返しになりますが、保有している権限の中で調整といったところは進めていきたいと考えています。おおむね１.５万円から５万円の範囲内で、それからそれぞれ区分があるのですけれど、そういう形で支援しています。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"だから事前に確認してくださいなどと、そこを共有していかないと、いいことをやっても大きなもめごとにつながってしまいます。いかがか尋ねました。","respondent":"舩木庶務課長","answer":"先ほど申し上げました２３区のうち１６区導入している事例もありますので、それを品川区に置き換えて進めていかれればと考えております。登録文化財制度という両輪で進めていくに当たっては、しっかりと条例等の中で理解が得られるように進めていきたいと考えております。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問・要望","question":"学校との連携についてお伺いしたいのですが、これは区内の全校が行っているのかというところと、校長先生の判断などで学校ごとに実施されているのか。具体的にどんなことをされているのかということを教えていただきたいなというところです。","respondent":"舩木庶務課長","answer":"そういうところで進めているという中で、学校としては、大森貝塚や伊藤博文公のお墓といったところにも少し触れられております。この辺りは、どういう対応が取れるかは、教育委員会の内部でも検討してまいりたいと考えています。","id":"exchange-006"},{"speaker":"澤田委員","kind":"意見","question":"今回登録文化財というのも出てきたので、地域に対する愛着や誇りを醸成していく活動を今後いろいろやっていただけたらなと思います。お考えをお聞かせいただけたらと思いますとの意見を述べました。","respondent":"舩木庶務課長","answer":"委員ご指摘のところは大事な視点かと考えています。それを進めていく中で、魅力を感じていただくというところが、歴史文化を理解していただくことにつながるように展開していきたいと考えております。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"学校にでの制度の周知についても視野に入れて取り組んでほしいと求めました。これは要望も含めて、お聞きできればと思います。","respondent":"舩木庶務課長","answer":"保護者の方も含めて、こういった制度を設ける背景や目的については、広く区民にしっかり浸透できるように進めていきたいと思っています。併せて、学校ということを踏まえたときにどういう進め方ができるかについては、教育委員会内部でも検討してまいりたいと考えております。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それから品川歴史館、それから学校、また地域団体ですかね。もう少しお考えを伺いたいと思います。","respondent":"酒川指導課長、舩木庶務課長","answer":"学校教育での文化財の扱いの１点目について、お答えします。これは社会科です。そういうことについて、区全体の理解を強めることで、活動の継承がより確実なものになっていくという効果もあるのではないかと考えています。","id":"exchange-009"},{"speaker":"山本副委員長","kind":"質問・要望","question":"私から何点かお伺いいたします。既に何かもう区民からの要望等で候補があるようでしたら、説明を求めました。","respondent":"舩木庶務課長","answer":"審議会の中で審議をし、そこで登録の妥当性を検討して、その内容を教育委員会に報告という形にしていきたいと考えています。ここら辺は、今申し上げた部分を含めて対応していかれればと考えております。","id":"exchange-010"},{"speaker":"山本副委員長","kind":"質問・要望","question":"補正する必要がないのかというところの確認と、もう一つ、登録文化財となった場合の周知方法です。３０件、４０件これから増えていくものを、どのように区民にお知らせしていくかということについて、方針があれば説明を求めました。","respondent":"舩木庶務課長","answer":"既存の予算の中で対応していかれないかということは、今後、しっかりと対応できるようにしていきたいと考えています。登録文化財というものが区には存するのだというところを、より知っていただく、理解を深めていただくというところは努めてまいりたいと思います。","id":"exchange-011"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。区民の郷土への関心、愛着を高める取組と思いますので、ぜひ効果のあるものとして進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"賛成なのですが、今回、保存と活用ということで、活用という部分が入ったと思います。保存という形ではなくて、そうあるべきだなと思いますので、そこに私たちは注目していきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"第８０号議案 児童相談所を設置する特別区における措置費共同経理課の共同設置に関する 規約の変更","agenda":"第８０号議案 児童相談所を設置する特別区における措置費共同経理課の共同設置に関する 規約の変更","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今、ご説明されたとおりだと思いますが、要は、児童相談所を開設する区が新たに増えると、こういう議案になるということなのか尋ねました。","respondent":"柴田子ども施策連携担当課長","answer":"委員のおっしゃるとおり、児童相談所を設置する区が増えましたらば、毎回このような形で議会にお諮りして議決をいただく。こういったプロセスを踏んでいく形となっております。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"１１か所とのことですが、これは何か所まで増える予定なのでしょうか。私たち品川区にとってのメリットは何か尋ねました。","respondent":"柴田子ども施策連携担当課長","answer":"１点目の児童相談所は杉並区が１１か所目なのですが、あと１区、北区が開設予定を公表しております。こちらは、児童養護施設それから乳児院等に対して、措置費という子どもの生活に関わるお金の支払事務を措置費共同経理課がまとめて実施しております。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"それは、今１１か所だから、１１か所の自治体が出資しているという感覚でいいのですか。いろいろ経費などがかかると思うのですが、そういう感覚でよろしいのか尋ねました。","respondent":"柴田子ども施策連携担当課長","answer":"それから、設置している自治体、当初予定していたけれどやめますというような自治体も中には出てきてあります。現状は、先ほどお伝えしたとおり、今後設置が予定されているのは北区が１区ですね。","id":"exchange-016"},{"speaker":"西本委員","kind":"提案","question":"今１１か所になり、いろいろ情報共有することによって、運用上のヒントや改善提案などができるかと思います。そういう仕組みにもなっているということか尋ねました。","respondent":"柴田子ども施策連携担当課長","answer":"特別区が児童相談所を設置できるという法改正があった平成２８年から、随時、情報共有会議というのが開かれております。来月も予定されていたりと、いろいろノウハウを学びながら、児童相談所の運営の充実につなげてまいりたいと考えています。","id":"exchange-017"},{"speaker":"澤田委員","kind":"質問","question":"私からお伺いしたいのは、病児保育についてです。お伺いしたいのは、お分かりになれば、まずそこを教えていただいてよろしいか尋ねました。","respondent":"染谷保育施設運営課長","answer":"区立保育園において、急遽保育士が何らかの事情でお休みを取った際の応援体制というところかと思います。各園に１人ないし２人という少人数しかいない職種に関しては、ほかの園から応援派遣という形で、現状においても体制としては取っております。","id":"exchange-018"},{"speaker":"澤田委員","kind":"質問","question":"そうすると、やはり保育士が急遽お休みすることがあるという声を伺っております。保育士が足りないときに応援できる体制というか、情報共有も含めて、そういうことができるプラットフォームというのはあるのか尋ねました。","respondent":"染谷保育施設運営課長","answer":"病児保育につきましては、委員おっしゃるとおりで、利用児童３人に対して１名の保育士を配置する基準となっています。区の支援があったほうがいいというお声は、何か協議会みたいなものを設置し、区としてどういう形で支援ができるかといったところも含めて。","id":"exchange-019"},{"speaker":"澤田委員","kind":"質問","question":"どうしても抜けられない仕事があったときには、どうしたものかという保護者もいらっしゃるのかなと思うと、課題もあると思っています。課題認識というか、そちらも教えていただけたらと思います。","respondent":"染谷保育施設運営課長","answer":"隔離ができるスペースといったものも施設として用意していく必要がありますが、その中で、やはりお話を聞いている中でもあるのかなと考えています。","id":"exchange-020"},{"speaker":"澤田委員","kind":"提案","question":"一度やっていただく機会を施設に提案していただいたり、働きかけていただくことというのも１つあるのかなと思いました。いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"子育てのための施設等利用給付交付金の上限引上げについて伺います。国はなぜこれを引き上げようとしたのか、理由を伺いたいのと、それぞれ分かれば教えていただきたいのですが。","respondent":"佐藤保育入園調整課長、染谷保育施設運営課長","answer":"こちらの施設等利用給付交付金が、国は、直近の物価水準や賃金動向を踏まえて見直しを実施するというようなところでお知らせが来ております。その数ですが、今回補正というところで… １９時半までお預かりした場合は、１,１５０円の利用料がかかりますが、現状７００円だったものが６６０円になると。そういった意味で言いますと、 一定の方に関しては負担をいただいているという状況にあります。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういったところでの対応というのは、引き続き求めていっていただきたいなと思っています。最初のところだけ、数字が、何の数字だったのかというのを伺います。","respondent":"佐藤保育入園調整課長","answer":"失礼いたしました。私のほうで申し上げたところにつきましては、今回の補正でプラスになる方の人数というところです。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"病児保育の新規も４名ということですけれど、病後児保育は何人の定員なのかを伺いたいのと、利用率はいかがでしょうか。それについて目標というのはあるのでしょうかということを伺いたいと思います。","respondent":"染谷保育施設運営課長","answer":"現状７施設の病児保育を整備することによりまして、数としては充足してきているところにあるのかなと考えております。そういったエリアに関しては、地域をある程度絞った形で今後開設を進めていくというのが目標というか、目的として進めていかれればと考えております。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"どこにどういうふうに使われる鋼材なのかということと、鈴ケ森小学校の工事の入札が不調だったということです。工期延長は本当にないのですかというところを、もう少し具体的に改めて伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"こちらは今年３月に契約いたしまして、令和８年１２月いっぱいまでは既存校舎の解体工事を進めております。本件で補正予算をご議決いただいた後、次回の第３回定例会でしっかりと入札手続を進めて契約をしていけば、十分間に合うだろうと見込んです。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"こういうふうに変わったというのは分かりますが、品川区にとってどういう影響があるのでしょうかというのを知りたいのです。どういう区分けをしていますかということをまず説明を求めました。","respondent":"佐藤保育入園調整課長、染谷保育施設運営課長","answer":"今回、先ほど申し上げた理由で、補助金の額を増額したというところではあります。都の負担が４分の１ということで、区の負担も４分の１ある形ですので、国の給付費引上げに係る部分に関しましては１,１００万円程度計上しています。病気の治療中であって、医師により、症状が軽度であり入院加療の必要がないと診断されている児童をお預かりするのが病児保育です。","id":"exchange-026"},{"speaker":"西本委員","kind":"確認","question":"子どもにとってと考えたときに、この病児保育というのがどういう意味を持つのでしょうかということをきちんと考えないといけないと思います。だけど、子どもにとってどうなのか尋ねました。","respondent":"佐藤保育入園調整課長、染谷保育施設運営課長、荒木学校施設担当課長","answer":"最終的には、差額は、歳出が６００万円余のプラスになっております。都の補助以外に区の持ち出しという形になっている制度ですので… こちらもそういうふうに考えているところではありますが、就労支援ですとか、非常に重要な事業であると認識しております。… 先ほどご説明した鈴ケ森小学校の建築工事につきましても、昨年度１度入札不調が発生しています。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"１８校ですか、改築をまだ決めていないところもあるということで、やらなければいけないです。私は非常に危機感を持っているのですけれども、そこの危機感をどう感じておられるかだけ教えていただけますか尋ねました。","respondent":"柴田子ども施策連携担当課長、荒木学校施設担当課長","answer":"区の取組が子どもにとってどう受け止められているのかという視点も持ちながら、そういったところで意見聴取を進めていきたいと考えています。 公共施設整備の発注者として、しっかりと対応していきたいと考えています。具体的には、現在私どもで進めている取組ですが、１点目が、適正な予定価格での発注です。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"どうなるか分からない。子どもたちの校舎ですから、うまく新しい校舎を短い期間で何とか造れてという形で、ぜひご努力ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"ゆきた委員","kind":"確認","question":"保育の利用補助について伺います。地域偏在を解消して、利用者が身近な場所で利用できる環境を整えることが主な目的という理解でよろしいか、改めて確認でお聞きしたいと思います。","respondent":"佐藤保育入園調整課長、染谷保育施設運営課長","answer":"ホームページ等で制度のご案内はしておりますので、そういったところについては速やかに修正して、案内をしていくというところ。そのタイミングに合わせて… 今回の開設が仮にない状況でありましても、区内全域で見た場合の需給状況としては充足しているというところはあります。","id":"exchange-030"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"こちらは要望で終わりたいと思います。利用しづらいとか、近くに施設が欲しいといったご意見とか要望は区に寄せられているのか、お聞きしたいと思います。","respondent":"染谷保育施設運営課長","answer":"西大井のエリアにお住まいの保護者のお声は、現状においては把握しておりませんが、いただくご意見の中で、施設が近くになくて利用しづらいというお声というのは、エリアは限定されませんけれども、 多少いただいております。","id":"exchange-031"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。整備の候補地域を選定していくのに、選定基準といったものはあるのか、お聞きしたいと思います。","respondent":"染谷保育施設運営課長","answer":"整備をどのような形で進めていくかというところにつきましては、現状において、エリアごとに需要と供給の数字をこちらで出しているものがあります。そういった数字を見ていく中で、必要なところに整備していくという考え方で進めてまいりたいと考えております。","id":"exchange-032"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"西大井周辺も含めて、引き続き区民の声を把握し、必要な地域への施設整備につなげていただくことを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問","question":"ほかの委員からもありましたが、この図でいくと、大井町の横の駅は下神明なのですかね。いろいろなご事情でどうしてもやめてしまうこともあるけれど、 でもそこはというのを、契約上何とかできるのかというところをお伺いします。","respondent":"染谷保育施設運営課長","answer":"そこについては、需要をきちんと把握した上で、必要に応じて施設整備は引き続き進めていきたいと考えております。一定、財産処分に必要な経費などがかかる部分というのはきちんとご説明させていただいて、長期的な形での運営というのはお願いをしています。","id":"exchange-034"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"きちんとお願いするというところを確認いただきたいのと、マンションがたくさんできて、お子さんがたくさん転居されてきているところもあります。これは要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-03","title":"令和８年度第１回家庭教育講演会","agenda":"令和８年度第１回家庭教育講演会","exchanges":[{"speaker":"澤田委員","kind":"意見","question":"ぜひ広く子育てに関わる皆さんに視聴していただけたらなと思います。申込みも要らないし、時間帯も働いている方でも見られるのは本当にありがたいと思いますので、どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"１点お願いしたいことがあるのですが、この講演は何時間やるのでしょうか。それをすると、さっと見られるかどうかというのが分かりやすいので、それが欲しいと思ったのですが、いかがか尋ねました。","respondent":"舩木庶務課長","answer":"全体で６０分程度の構成にしております。大体１５分刻みぐらいで、よりご関心のあるところから視聴できるような環境を整えております。","id":"exchange-037"},{"speaker":"ゆきた委員","kind":"質問","question":"今ご説明の中で、幅広い区民への周知を行っていくということでした。本当に支援を必要としている方に対しての周知というのを改めてどうやって行っていくかお聞きしたいと思います。","respondent":"舩木庶務課長","answer":"本当に生の実体験から、より多くの方々に１つでも子育てのヒントになるような情報をお届けしたいというお気持ちからご協力をいただいたものです。そこも含めて、現時点では詰めていく必要があるかなとは思いますけれども、委員のご指摘のとおり進めていかれればと考えています。","id":"exchange-038"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"確認できました。必要な保護者への情報提供、情報の周知というのも必要かと思いますので、そこについては要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-04","title":"令和８年度新入学学校別増減要因一覧","agenda":"令和８年度新入学学校別増減要因一覧","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今、学校選択に際して、希望申請して入れなかった人を記載していないとおっしゃっていたと思いますが、どれくらいの子というのは、今この場で数字を持っているのか尋ねました。","respondent":"石井学務課長","answer":"小学校につきましては、６１７件の希望申請があり４７４名が入学しておりますので、大体入学率としては７６.８％ほど。４９５名の希望申請がございまして入学者数が１８０名ですので、３６.４％ほどの入学率となっております。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"中学校のほうが入学率が低いというのは、どういう要因か尋ねました。","respondent":"石井学務課長","answer":"中学校ですけれども、令和８年度入学から１クラスが３５名になりました。そのことがこの入学率になっていると、今のところ考えております。","id":"exchange-041"},{"speaker":"澤田委員","kind":"質問","question":"学校選択制の在り方、進め方というものの検討が必要となってくると思いますが、区としてはどのようにお考えか尋ねました。","respondent":"石井学務課長","answer":"こちらですが、一定程度、令和６年の学事制度審議会答申では、児童数のピークは、 小学校が令和１９年度、中学校は令和２２年度とまとめています。まずは就学人口の動向をきちんと見定めていくということがすごく大事になってくるのではないかなと考えています。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"抽せんの結果が、２月初めに分かるではないですか。その現状を教えてほしいのと、第三日野小学校は、３７名が私立に行ってしまうのですね。","respondent":"石井学務課長","answer":"大体小学校は１月ぐらいから申請を受け始めながら、そういったことを含めながら、指定校変更についても一定程度議論していくという形になります。私立に通う方は４１.６％でしたが、令和８年度の数を見ますと同じく４１.６％で、そこで少し高止まりしているという現状です。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"抽せんに漏れてしまったら、別の学校を選ばなければいけないわけではないですか。それがいいか悪いかはここでは言えませんが、そういう傾向もあるのではないかなと思うのですが、その辺に対してどうお考えになっていますか。","respondent":"石井学務課長","answer":"私も着任して２年目ですけれども、かつての時代は、かなりの方々が抽せんに漏れた後、指定校変更の手続をなさっていると聞きました。当然、公立学校は公立学校の一つの使命を忘れずに、今後も教育委員会としっかりやっていきたいと考えています。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"動向を見ながらいろいろ考えてほしいと求めましたが、今、こだわるのですよね。これは意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問","question":"も４１％のお子さんが私学に行ってしまうということで、これは、結局やっていますけれどということではないのですかね。所管が学務課ではないので申し訳ないのですが、その辺をお願いします。","respondent":"新井特別支援教育担当課長、酒川指導課長","answer":"知的の特別支援学級や、全校に設置しておりますが特別支援教室で、その子に応じたきめ細やかな支援を行っております。支援が必要な子が… 大規模校、小規模校の学校支援人材ですが、大規模校においては、スクールサポートスタッフ、エデュケーションアシスタント、副校長補佐を必要に応じて複数配置して支援しております。","id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、それはそれとして、私立もそうだけれど公立もこうだというのをもう少しＰＲしていただきたいなと。ですから、この前の北区の事故ではありませんけれども、ぜひ大規模校に対する支援をしっかりとしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"山本副委員長","kind":"質問","question":"私から質問します。やはり義務教育学校に希望が集まっているということかと、この数字を見ると思うのですが、その辺り、区の認識はどのようになりますか。","respondent":"石井学務課長","answer":"一方で、学校については、中学校連携グループを組みながら、９ 年間の一貫した教育というのは品川区全体で行っている部分ではあります。希望もありながら、入学の実績としては、一定程度受入れ可能数が確保できる義務教育学校の中で実績があると考えております。","id":"exchange-048"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ご答弁いただきまして、やはり義務教育学校には一定の希望される方々がいるということだと思います。できるだけ希望する方々は入れるようにしていただきたいですし、三木小学校など、そういうことも含めてご検討いただきたいなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"高橋（し）委員","kind":"意見","question":"すみません、１つだけ。トータルで１０１人抜けて、それで１３４人なのですが、城南第二小学校についてはその辺はどのような見込みでいらっしゃるのか尋ねました。","respondent":"石井学務課長","answer":"我々としても、そういったところでまた就学人口を推定していきたいと考えています。新入学者の受入れ枠の部分でも一定程度考慮していかなければいけない部分があるのかなと考えております。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"すみません、今、質問がありました浜川小学校１６３名ですが、これは５クラスになるのでしょうか。どういう現状なのか尋ねました。","respondent":"石井学務課長","answer":"その前は２１６名、その前は２４６名ということで、実は少しずつ減ってきております。もう少し前のほうが、住民基本台帳上の人数は多かったという現状です。","id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"先ほどもご心配の質問がありましたが、クラス数などは大丈夫なのですか。これはどう考えられていますか。","respondent":"石井学務課長","answer":"今後の就学人口推計は足元では増えてはおりますが、今のところ例えば学区を変更しなければならないほど増えているという現状ではございません。そういった状況を見ますと、今のところは、学区変更といったことではないような形で考えております。","id":"exchange-052"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"こういうことが起きたのは、セキュリティが弱かったのでしょうか。今、何件というお話もありましたけれど、保育園や幼稚園というのは結構なところで採用していると思うのですけれど、どのぐらい使われているのか尋ねました。","respondent":"染谷保育施設運営課長","answer":"ただ、例えば個人情報保護委員会といったところの判断を仰ぎながら、長期的な対策をしていくという話は聞いております。全園一括して契約している関係がありますので、今回の対象になった園というのは、残念ながら区立の全園です。","id":"exchange-053"},{"speaker":"西本委員","kind":"意見","question":"いろいろ漏えいしたということで、私も最近２枚のカード会社から連絡があったりしているので、あり得ることなのだろうなと思うのです。保護者の利便性を考えると、やめる方向に行かれてしまうと困るだろうと思いますので、お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問","question":"全部ですか。保育園で言うと全園という話でしたけれど、全保護者というわけではなくて、一部の保護者ということでいいのか、そこを伺いたいと思います。","respondent":"舩木庶務課長、染谷保育施設運営課長","answer":"事業者から、対象となった保護者宛てに個別に通知がなされておりまして、全保護者ではないという認識でおります。漏えいの内容につきましては、先ほどご説明しましたとおり住所、電話番号、氏名ということで… 登録自体は保護者の任意ですが、現在６割ぐらいの保護者がサイトに登録している状況です。まだそこの数字については、こちらとしては把握できておりません。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"在園児の人数を教えてもらえますか。何歳児が何人というのが分かれば。","respondent":"佐藤保育事業担当課長","answer":"全体で６８人というのが分かってございまして、歳児ごとの人数につきましては、すみません、今、 手元に資料がございません。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"そうしたら、６８人が周りの保育園に行くということですか。希望者になると思いますが、それは枠がそれだけあるという認識でよろしいか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"優先転園を希望される方が何名かにもよるとは思いますが、当該箇所にあった園から大体１kmぐらいの範囲内でございましたら、在園されているお子様の数の空きというのは現状で確保することができるという状況です。","id":"exchange-057"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.29bu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":44,"characters":52896,"voices":235}}]);
